import{k as m,p as z,l as k,C as b,n as N}from"./daguanyuan-lite-CNDybvA7.js";import l from"./normal-journal-albums-BJc5hgMM.js";import"./preload-helper-DMGCcr4D.js";import"./three.core-3TnwmHjw.js";const S={"fu-rongmen":"（第三回）街上的宁、荣二府门面相近，黛玉先经宁府，再向西到荣府。此门显示家族门第，却不是她乘轿进去的通道；入府须从西角门另走一程。读这处建筑，宜把正门的体面与实际出入的路径分开，才不至把荣府画成只剩一座大门的空壳。 第三回这番先望门面、再循角门入内的写法，也给后面层层穿堂、拜见贾母的路线定了起点。","fu-lixiang":"（第四回）梨香院原是荣国公暮年静养之处，房屋虽不大，却自有前厅后舍。薛家入京后，贾政请姨太太一家住在这里，让亲戚既能照应，又有相对独立的院落。到第八回，宝玉在这里见宝钗并看金锁；一座客院因此接上了两家的日常往来。 薛姨妈一家由此与荣府近而不杂，往后宝钗、薛蟠的行动，也常从这座院子接入两府故事。","fu-tiren":"（第十八回）元妃省亲时，在此更衣、稍事歇息。院名带着典礼意味，和大观园里供姑娘们居住的竹馆、草庐不同。车驾入府的路线要有可停、可整仪容之处，这里便是省亲礼序中的一站；看它时不必当作人物长住的闺阁。 匾额所记的是元妃一夜归省的节次，不能据此推成她在园中常有起居的院落。","fu-jiashe":"（第三回）邢夫人领黛玉去拜见大舅贾赦，出荣府西角门后另乘车而行。到了院中，格局比贾母那边小巧，不以正堂轩峻取胜。这个转场也提醒读者：同是荣府一支，长房与二房的居处并不混成一处；黛玉一天里所走的路，正是两房间的关系图。 同一日数次换车、换轿，正显出府宅广大与拜亲访长的繁复，黛玉不得不处处留心。","fu-ancestral":"（第五十三回）贾氏宗祠在宁府西边，是岁暮祭祖时全族依次行礼的所在。黑油栅栏、重门与匾额将日常院落隔开，进门便换了规矩：人物按辈分站立，礼数比家宴更严。这里既是家族记祖功之所，也是一面照见府中长幼秩序的镜子。 祭仪在此举行，除夕的热闹先经过肃礼，随后才回到各房的团聚宴饮。","fu-ningzheng":"（第五十三回）宁府正堂在祭祀年节时显出规模：厅、抱厦、廊檐和丹墀，把宾客与家人引向各自的位置。平日游园读到的都是诗社、花木，走到这里便见另一种富贵——它靠门第和礼仪支撑。建筑不只是背景，谁能站到堂上，也由它划定。 到第五十三回，岁时礼法把这份堂皇写成具体行动，府第的外观也就有了人的秩序。","fu-youshi":"（第五十三回）除夕祭事后，尤氏上房铺毡设席，人物从祠堂的肃穆转回屋内叙话。宁府这处家常空间承接节令的忙碌：外面需按礼行事，里头还要照料来往亲眷。游记把它与正堂分开，便能看清同一座府中公事与内宅的不同。 一方红毡看着寻常，实是家族岁末走动繁密时，内宅预先备下的接待工夫。","fu-qinke":"（第五回）宝玉在宁府午倦，由秦可卿领到房中安歇，见画、陈设与气息，便入了太虚幻境之梦。此处屋内物象写得浓丽，常与梦境连读；但室内的画与对联仍属于现实中的房间。读这一站须记住两层：先有可卿安排的歇处，随后才有梦里的册页与曲文。 房中陈设与梦境互相映照，却须分清书中所见、梦中所闻，免得把象征写成实物。","fu-tianxiang":"（第十一回）天香楼是宁府的楼上空间，家宴往来曾在此展开；到第七十五回，中秋前后的宴饮又使它有了另一番气氛。两次提及相隔甚远，不能把楼当作只服务某一段情节的舞台。楼下院落与楼上席位相接，见得宁府待客自有层次。 上楼下楼之间，宴席中的宾主次序与各人的面子，也有了可以落脚的实际位置。","fu-jie":"（第六回）刘姥姥为求周济，带板儿一路打听，才摸到宁荣街。对府里的人，街名只是出门即到；对初来求见的乡下客，却要问路、等门、认人。这条街因而不只是两府之间的方位，也把门第内外的距离写得分明。 过了这条街再入府，故事便从乡村人的眼睛，重新打量平日被府中人视为寻常的富贵。 此后每一道门槛，都是她求见凤姐时必须亲自跨过的。"},O="第六回初进荣府，她虽有求于人，仍肯放下身段把话说圆；第四十、四十一回再入园，逗笑众人之外，也常拿乡村的日用来衡量贾府的排场。",C="她在宝玉房里管衣食起居，既照顾他的细处，也替大人留心他的行止。读袭人不能只看一句劝学话，还要看怡红院日常有多少事由她收拾。",D="她心气高，做事利落，却难把脾气藏得严严实实。第五十二回病中补裘、到第七十七回抱病离园，两处相照，才见能干与脆弱都在她一身。",E="他随母亲李纨生活，年纪虽小，已被贾家视作下一辈读书的人。第二十六回他拿着小弓在园里追鹿，撞上宝玉；第七十八回贾政命他和宝玉、贾环各作一首《姽嫿词》，李纨的清静日子里也多了一层母亲的牵念。",T="他在宁府承接长辈差遣，出入荣宁两府之间，常把长辈的意旨变成具体跑腿与应酬。看他行事，应连同宁府的家长秩序一并读。",$="怡红院诸丫鬟里，她不以锋芒夺人，宝玉不在时也能照看屋中琐事。她的一笔一语虽少，正好补出大院生活并非只靠几个最响亮的人物运转。",v={liulaolao:O,xiren:C,qingwen:D,jialan:E,jiarong:T,sheyue:$},J="（第二十六回）贾芸初进怡红院，宝玉倚在这张床上看书。床身的填漆与帐子的红金写出少年房里的富贵，却又不是只供陈列的器具；人坐卧其间，书页、说话和来客一齐进入画面。看它宜分清原著所写的床与帐，别照一般园林卧榻随意代换。",P="（第四十一回）镜子嵌在雕空紫檀板壁中，原可开合，板壁后还藏着门。刘姥姥酒后误把镜中人当成面前的人，伸手摸去，才碰开机括。镜子既是屋里照人的用物，又把园中精巧机关变成一场笑事；人物对新鲜物的惊讶也正在这里。",M="推定。原著说怡红院的槅格可贮书、安笔砚，却没有逐字点出这张花梨书案的形制与位置。游戏为让写字、读书有落脚之处，依室内动线置一张案；案上的痕迹只说明当下可以使用，不应据此把它写成书中确有的一件古物。 案旁的椅子同属布景，书里不曾给它指定席次。",B="（第十七回）贾政一行见室内槅格有安置笔砚之处，这一点有原著依据。眼前的青花笔筒、湘竹笔和端砚的具体组合，则是为可看可用的场景所作推定。笔墨不只装饰房间，也接得上宝玉题匾、作诗的日常；陈列时须把书里所见与画面补足分开。",A="（第十七回）怡红院的槅格有贮书之处，屋中有书可信；六函的数量、函套颜色和此刻翻开哪一卷，都是游戏陈设。宝玉读的书也不能一概写成自己的诗稿。读此物时可由书橱想到日后诗社与私下阅读的不同场景，勿把推定的案头内容当作原文记载。 若要辨书目，仍须回到各首诗出现的具体回目。",I="推定。正文明间这张紫檀方桌来自室内布置方案，原著没有指认一张同式八仙桌。第六十三回夜宴确有桌席，但所写桌式、位置须与此区分。游戏把桌子设在可往来之处，是为了容茶具与交谈；它说明生活用法，不充当逐字复原的证据。 桌面如今空着，也不表示书中某次席面没有器皿。",L="推定。第六十三回夜宴，书中确有丫鬟端椅陪坐；可那两把椅是否为圈椅、是否分列方桌东西，原著并未交代。游戏取圈椅的弧形扶手，使席间座次一目了然。看这组陈设时，应把书中确有的坐椅和画面推定的款式、摆位分开。 椅背木纹与扶手工艺也只代表这一版造型。",X="推定。怡红院常有奉茶待客之事，四只白瓷盖碗与一把茶壶的定数、摆法却不是原文逐件列出。游戏将它们置在明间桌上，让人看见丫鬟烧水、奉茶之后可落杯之处。它写的是富贵人家院内的日用，不宜拿一套茶具反推某一次宴席的确切陈设。 杯盏的釉色与式样同样是美术选择。",F="（第十七、四十一回）怡红院屋里有贴壁的琴剑瓶炉，远看像画，近看才知是实物。这张琴的用意正在嵌壁：它不另立琴桌，也不占屋心的行走位置。若在这里听一段琴声，那是游戏的观赏层；原著写的是陈设的奇巧，未写宝玉在此弹奏这一曲。 墙槽与琴面相平，远望才有画中藏物之趣。",G="（第三十七回）晴雯说十锦槅顶上的一对联珠瓶尚未收回，秋纹便讲宝玉把园中新开的桂花插瓶，分别送给贾母与王夫人。瓶子由此牵出一件小小的孝心，也牵出送花丫鬟所得的赏赐。游戏以联珠瓶还原物名；具体釉色与三珠相连的形制仍属推定。",H="推定。墙槽里的悬瓶有第十七回的记载，眼前这只青花梅瓶却是游戏另添的桌上器物，两者不可混称。小口丰肩适宜单枝插花或独立观赏，放在屋里也可与大面积红帐、锦槅错开色彩。它承担的是画面的清静一笔，并无对应的一段原著情节。 瓶边空白留给观看，不强添一段并不存在的故事。",K="（第四十一回）刘姥姥误入怡红院睡去，袭人悄悄安顿，往香鼎中添百合香，以免宝玉察觉屋里的异样。一个小铜器牵出丫鬟做事的细密，也把笑闹收在室内日常中。游戏的鼎形、罩纹可供近看，原著可据的核心是添香这件事与袭人的用心。",Q="（第十七回）室内格架确有安放盆景的位置；青花六角盆、小松以及东北角高几的具体组合，则是游戏据园林趣味补出的陈设。盆景把户外山林缩入屋中，与槅格曲折的空间相衬。看它可见居室爱玩山石花木的兴致，也应留意器形与植株并非原文逐件指定。",R="（第四十一回）刘姥姥醉中入房，把板壁上的仕女画误作迎面走来的人，伸手招呼，反碰着墙。画像画得真，才有这场误认；笑处也在看画的人与屋内人所见不同。游戏选一幅人物画安于板壁，是顺着这一节做的可见形象，画家和画中女子都不应凭空定名。 画的姓名未详，恰使误认集中在一眼看错的瞬间。",U="推定。书中写屋里灯火与移灯、剔灯的动作，却未逐件交代明间左右这两座铜烛台。游戏让烛光在夜里照亮案、槅与帐，便于辨认房间层次。铜质、数量、位置都是场景安排；赏灯可见夜间生活的气息，不能据此当作原著器物清单。 只借光影说明屋内有人生活，不借它另造情节。",V="（第十七回）怡红院内不止一间直通的屋子，碧纱厨与锦槅层层相隔，贾政一行还曾被它绕得难辨出路。纱色使隔断能透光而不全露，进到深处才见床与起居之所。它既管视线，也分内外：众人题额时所见的奇巧，到宝玉住进来后成了每日经过的房间。",W="推定。床边这座紫檀衣架是为了给外褂和日常更衣找一个合宜的位置，原著没有在怡红院逐字列出它。院中丫鬟要照料衣饰，屋里自然需要收挂的办法；游戏用一件可见器具交代这层生活工夫。材质与摆位均属画面选择，不宜指作书中定制。 衣架旁是否另有衣箱，仍以原文可考之处为准。",Y="（第三十五回）袭人端来脚踏请莺儿坐，说明屋中确有这种低矮、便于落脚或临时坐人的用物。游戏把一件安在床前，并让漆色与床相应；此处位置、配色是推定。读原文要把那次待客动作和常设陈列分开，才不致误以为脚踏永远只在床边。",Z="（第十七、三十六、五十七回）十锦槅子以雕空木板分隔，格眼藏物又透视，初来的人一时难辨门窗。后文仍有人从槅子间出入、陈设小玩器，可见它不是只为初游造奇的摆设。游戏保留通透与可穿行的结构，读者可沿着它理解屋内分间而不封死的妙处。",_="（第三十一回）水晶缸里湃着果子，暑气中取来便觉清凉。鸳鸯送果子的往来，把怡红院与贾母处的日常照应连起来；一缸果子也写出大宅夏日消暑的讲究。游戏让缸壁见凉意，是将文字里可感的冷意转为画面，不必把果品种类与每只盘碟都补作定数。",nn="（第二十三回及后文）院中鸟架与人声相伴，鹦鹉学话，常把屋里的叫唤传到檐下。它不是一只只为点缀颜色的鸟：同样的声音，在热闹时令人发笑，人物散去时又显得空落。游戏把笼架留在院中，读者可由它听见怡红院的日常，也听见时日流转后的变化。",an={yh01:J,yh02:P,yh03:M,yh04:B,yh05:A,yh07:I,yh08:L,yh09:X,yh10:F,yh11:G,yh12:H,yh13:K,yh14:Q,yh15:R,yh16:U,yh17:V,yh18:W,yh19:Y,yh20:Z,yh21:_,yh22:nn},un={续论:{zanghua:"第23回埋桃花时，两人的心意原是相通的；到第27回，黛玉独自再来，旧地便添了昨夜的误会。宝玉并未先见她的面，读者也跟着他隔坡听见哭声，情节因此有了距离。花神节本该送尽残春，姑娘们却仍尽力留花，黛玉偏把一时的节令想到日后的归宿。看她手里的花囊、锄头与脚下净土，便知葬花既是动作，也是她向不肯明说的忧惧求一个安放处。不要把诗中的自问当作已经发生的身世结局；这一回写的是眼前人对无常的预感。",pudie:"第27回这一段最妙处，是一双蝴蝶先领宝钗走入无人处，隔扇又把她变成无意的听者。她随即判断：若让红玉知道有人听见私语，事情恐怕难以收拾。机敏的一句借口救了眼前的局，却把黛玉的名字放进另一个人的疑心里。红玉与坠儿议的本是手帕与贾芸，原与黛玉无涉，读者因而能同时看见三层心事：宝钗的自保、红玉的惶急、黛玉的不在场。前后两场都在送花神的日子发生，热闹景色并未消去人的戒心。",zuiyan:"第62回众人找湘云，才在山石背后发现花瓣覆身的一幕。她睡着时仍念席上的令，醒后却要面对一圈笑她的人，豪兴与羞意都落在同一个姑娘身上。卷中若只画落花与睡姿，便容易把她当作供观赏的景；把找人、围看、醒来三步连起来，才看得到同伴间亲昵的分寸。寿席同时为几人而设，湘云并非被单独摆成一幅奇景；她是在群体里一时放松，才有这一觉。红香圃的花与酒令都短暂，故这一日尤其值得存入册中。",youyuan:"第40、41回的游踪像一根线，把贾母、凤姐、鸳鸯、妙玉以及园中诸人串在一处。刘姥姥见新鲜便问，听热闹便笑，既肯顺势逗老人开心，也会计算一顿螃蟹宴抵得上乡下多少日用。她的眼光替读者量出园子的阔绰；人物对她的态度，又反照各人的性情。到了怡红院醉眠，笑场仍有体恤：袭人悄悄收拾，替她遮过尴尬。此卷不宜只读成村妪出丑；富贵园与乡下日子在她身上短暂相逢，才是两回的厚味。",haitang:"第37回起社时，花笺先到，白海棠后到，平日散在各院的人就有了约期相聚的理由。诗社虽说重诗才，也离不开李纨掌坛、探春筹划、众人按礼相让这些日常安排；园中姑娘的聪明在这套小小章程里各显其长。作同一题时，宝钗与黛玉并不写成一种花：一人将情思藏在节制里，一人把灵秀放到字面上。听评诗时还要看宝玉的急切与李纨的持平。此刻社名初定，后来聚散未至；这份兴会正因尚有余日而格外可亲。",pinchamei:"第41回的茶席先有尊客与私客之分，贾母一行所饮、宝钗黛玉被邀去尝的茶，各有器皿与水的讲究。妙玉既愿款待，又在刘姥姥碰过杯后露出洁癖；她的修行与俗世人情并不容易分开。第50回雪天的红梅换了场面：众人明知她不喜喧闹，却也知道宝玉去求，未必空手回来。两回相照，茶是她设下的门槛，梅又像从门内送出的回音。卷中把相隔九回的事并置，是为了辨认同一人不同的待客姿态，并非说它们发生于同一天。",lianju:"第76回的中秋原该赏月团圆，宴席却渐见冷落，黛玉、湘云到水边另寻说话处。两人以景接句，鹤从暗水中惊起，月仍照着池面；越是实见之物，写进诗里越显孤清。妙玉不是偶然来夺诗，她在旁听出词意过悲，才接过笔来收束。三人并坐一夜，既不能消除各自的身世之感，也暂得一个能听懂的人。山上的笛声、水边的鹤影与庵里的灯火，都是同一夜的层次；这卷宜从声音和行路看人如何由宴席走向知音。",aida:"第33回贾政的责打，起于数桩相继而来的消息，既有父亲对儿子的震怒，也有荣府与外面官府、王府牵连的压力。王夫人赶来先想到早逝的长子，贾母到场才真正止住板子；同是一家人，拦人的话各有根由。第34回众人探病，才让这场冲突的余波落到屋里：有人问伤势，有人劝他改过，有人只在旧帕上读懂未说的话。画册若停在板子落下，人物便只剩苦相；把帕子与题诗接进来，才能看见痛后尚未说尽的情意。",zhengmen:"第17回试园不是闲逛：一处处景都待拟名，宝玉随父亲与清客走，边看边答。正门先有府第的规制，入门又让大石挡住视线，园林把眼前景色藏起来，才容得人移步细辨。清客的赞语与宝玉的判断常不一样，贾政虽斥他言语轻狂，仍叫他继续应答；父子的紧张藏在题额的次序里。画这一卷时，先见门，再见石，再望向石后，不必一下子铺开全园。读者循这道遮掩而入，也才懂后来各院为何各有自己的名字和气息。",gexing:"第49、50回雪中聚会，一面是烤鹿肉的烟火，一面是争联即景诗的机锋。芦雪广的茅檐土壁原是园林里有意经营的野趣，席上却坐着锦衣的公子姑娘；景与人相碰，反倒生出活泼。湘云与宝玉忙着割肉，黛玉既笑又挑，等到联句时众人再换一副争先恐后的神情。平儿失镯在此埋下线索，欢聚之外仍有府内管束与差事。把炉火、雪色、诗笺连在一卷看，才见这一天从吃到写、从嬉笑到较量的完整节奏。",zhouru:"第18回的水路为元春省亲而设，灯火与绢花把夜船照得如在画中；匾额一改，又说明一处风景还得听尊客的裁定。到第40回，贾母率众再从水上经过，旧日灯彩不在，荷叶已残，黛玉却想到留它听雨。两次经过的是同一园景，人的心境、船上宾主、所见时令各不相同。读这卷可把岸上的题额与水上的倒影分开看：前者记一时的盛仪，后者容后来人再添自己的感受。园子之所以可重游，正因它不只停在省亲那一夜。",chufang:"第61回的争执从一碗鸡蛋起，厨房掌事的柳家母女、各房使唤的丫头，谁能领、谁能说，都有看不见的规矩。玫瑰露与茯苓霜本是小物，传过几双手便牵出私情、疑心和责罚。宝玉想替人担过，并不能独自把事了结；平儿要兼顾探春治事与各房体面，才把冤屈往回理。到第62回，厨房的差事才又归位。园中席面看着轻巧，后头却有采买、开火、分例、管人的劳作；这卷从一扇后门进去，替正院热闹补上日常的底账。",gongdu:"第23回两人读书时，桃花并非单为添景：风把花吹在书页上，也把书中的情意引到两人眼前。宝玉先爱惜落花，黛玉却想得更远，怕花随水出园，到了脏处受污，于是指向自己收花的所在。同一件事，两人都惜花，惜法却不全相同。戏文里的话被拿来相试，听的人也要辨明玩笑与心意的界线；起初的亲近，转眼又能闹别扭。后来葬花册再回沁芳闸，便不是凭空生出的新场面，而是这里一册书、一担花锄留下的余韵。"}},en={作品:JSON.parse('{"haitang-tanchun":{"题":"詠白海棠","作者":"tanchun","名":"探春","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","句":["斜陽寒草帶重門，苔翠盈舖雨後盆。","玉是精神難比潔，雪為肌骨易銷魂。","芳心一點嬌無力，倩影三更月有痕。","莫謂縞仙能羽化，多情伴我詠黃昏。"],"白话":"斜阳照着关上的门，雨后苔绿了盆。花的精神比玉、肌骨像雪，半夜的影子留着痕。末句说不要讲缟仙羽化，多情的人伴着它咏黄昏。","串讲2":"起社的是她，头一首也是她。「玉是精神難比潔」，咏花亦是自道骨气。册子上却画着放风筝，「千里東風一夢遙」，这一社的东道，终究是要远行的（第5回）。","出处":"dgy/codexData.js 作品条目（第 21 轮前已核维基文库）"},"haitang-baochai":{"题":"詠白海棠","作者":"baochai","名":"宝钗","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","句":["珍重芳姿晝掩門，自攜手瓮灌苔盆。","胭脂洗出秋階影，冰雪招來露砌魂。","淡極始知花更艷，愁多焉得玉無痕。","欲償白帝憑清潔，不語婷婷日又昏。"],"白话":"白天把门掩上，自己提瓮浇盆里的苔。洗掉胭脂才看见秋花，冰雪里招来魂。淡到极处才知道花更艳。末句是花不说话，婷婷地又到了黄昏。","串讲2":"李纨评她第一，只为「含蓄渾厚」。「淡極始知花更艷」，正是她一生的做法：不施胭脂，自然压人一头。下句偏又「愁多焉得玉無痕」，玉字落在她诗里，也落在她命里。","出处":"dgy/codexData.js 作品条目（第 21 轮前已核维基文库）"},"haitang-baoyu":{"题":"詠白海棠","作者":"baoyu","名":"宝玉","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","句":["秋容淺淡映重門，七節攢成雪滿盆。","出浴太真冰作影，捧心西子玉為魂。","曉風不散愁千點，宿雨還添淚一痕。","獨倚畫欄如有意，清砧怨笛送黃昏。"],"白话":"海棠的秋容浅，七节攒成一盆雪。他用出浴的太真、捧心的西子作比。晓风吹不散愁，宿雨又添一痕泪。末句是独自靠着栏杆，听砧声和笛。","串讲2":"李纨评他压尾，他倒说「這評的最公」。诗里太真出浴、西子捧心，用的尽是红颜薄命的人。他咏的是一盆花，眼里看的是一园子姊妹，自己还不知道。","出处":"dgy/codexData.js 作品条目（第 21 轮前已核维基文库）"},"haitang-daiyu":{"题":"詠白海棠","作者":"daiyu","名":"黛玉","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","句":["半卷湘簾半掩門，碾冰為土玉為盆。","偷來梨蕊三分白，借得梅花一縷魂。","月窟仙人縫縞袂，秋閨怨女拭啼痕。","嬌羞默默同誰訴，倦倚西風夜已昏。"],"白话":"帘半卷，门半掩，用碾碎的冰做土、用玉做盆。白借梨花，魂借梅花。月里的人缝白袖子，闺中人擦眼泪。末句是羞着不说，靠着西风，夜已经昏了。","串讲2":"「偷來梨蕊三分白，借得梅花一縷魂」，众人看了都道这首为上。李纨偏说风流别致是她，含蓄浑厚让蘅稿。黛玉不争第一，只是借来的这一缕魂，后来是还不回去了。","出处":"dgy/codexData.js 作品条目（第 21 轮前已核维基文库）"},"jishi-chun":{"题":"春夜即事","作者":"baoyu","名":"宝玉","回":23,"回目":"第二十三回　西廂記妙詞通戲語　牡丹亭艷曲警芳心","句":["霞綃雲幄任舖陳，隔巷蟆更聽未真。","枕上輕寒窗外雨，眼前春色夢中人。","盈盈燭淚因誰泣，點點花愁為我嗔。","自是小鬟嬌懶慣，擁衾不耐笑言頻。"],"白话":"春夜：帐子铺开，隔巷的更声听不真。窗外下雨、枕上微寒，眼前是春色、梦里是人。小丫头娇懒惯了，拥着被子还笑个不停。","串讲2":"搬进园来，宝玉心满意足，四时即事便是这时写的。枕上轻寒，眼前春色，都是太平闲情。外头势利人抄了去各处称颂，他倒先得了个才名（第23回）。","出处":"维基文库 zh-hant 第023回（2026-10 抓取稿）；机器转字处按底本改正：簾捲（原作「帘卷」）、裡（「里」）、棲（「栖」）、懷（「怀」），「舖」「鷫」照录"},"jishi-xia":{"题":"夏夜即事","作者":"baoyu","名":"宝玉","回":23,"回目":"第二十三回　西廂記妙詞通戲語　牡丹亭艷曲警芳心","句":["倦繡佳人幽夢長，金籠鸚鵡喚茶湯。","窗明麝月開宮鏡，室靄檀雲品御香。","琥珀杯傾荷露滑，玻璃檻納柳風涼。","水亭處處齊紈動，簾捲朱樓罷晚妝。"],"白话":"夏夜：绣倦了的人睡得沉，笼里鹦鹉叫着要茶。句里藏着丫鬟名字——麝月、檀云。琥珀杯、玻璃槛，水亭里团扇摇，朱楼卷帘卸了晚妆。","串讲2":"一句「金籠鸚鵡喚茶湯」，再一句把麝月、檀云嵌进诗里，宝玉写夏夜，也不忘屋里的人。这是怡红院人最齐的一夏，丫鬟的名字都还在一处。","出处":"维基文库 zh-hant 第023回（2026-10 抓取稿）；机器转字处按底本改正：簾捲（原作「帘卷」）、裡（「里」）、棲（「栖」）、懷（「怀」），「舖」「鷫」照录"},"jishi-qiu":{"题":"秋夜即事","作者":"baoyu","名":"宝玉","回":23,"回目":"第二十三回　西廂記妙詞通戲語　牡丹亭艷曲警芳心","句":["絳芸軒裡絕喧嘩，桂魄流光浸茜紗。","苔鎖石紋容睡鶴，井飄桐露濕棲鴉。","抱衾婢至舒金鳳，倚檻人歸落翠花。","靜夜不眠因酒渴，沉煙重撥索烹茶。"],"白话":"秋夜：绛芸轩里安静下来，月光透进茜纱窗。苔石边睡着鹤，井边梧桐的露水打湿了栖鸦。丫鬟抱被来铺，夜里酒渴睡不着，拨香要茶。","串讲2":"绛芸轩里月浸茜纱，「抱衾婢至舒金鳳」，夜里铺床的是谁，诗里不说。酒渴讨茶，原是富贵闲人的寻常日子，书到后来，连这寻常也难再有。","出处":"维基文库 zh-hant 第023回（2026-10 抓取稿）；机器转字处按底本改正：簾捲（原作「帘卷」）、裡（「里」）、棲（「栖」）、懷（「怀」），「舖」「鷫」照录"},"jishi-dong":{"题":"冬夜即事","作者":"baoyu","名":"宝玉","回":23,"回目":"第二十三回　西廂記妙詞通戲語　牡丹亭艷曲警芳心","句":["梅魂竹夢已三更，錦罽鷫衾睡未成。","松影一庭惟見鶴，梨花滿地不聞鶯。","女兒翠袖詩懷冷，公子金貂酒力輕。","卻喜侍兒知試茗，掃將新雪及時烹。"],"白话":"冬夜：三更了还睡不着。满院松影里只看见鹤，雪像梨花铺了一地。诗冷酒薄，幸好丫头懂茶，扫了新雪来煮。","串讲2":"「掃將新雪及時烹」，扫雪烹茶，是宝玉的冬夜。后来栊翠庵里，妙玉拿五年前收的梅花雪煮茶，还笑他是大俗人（第41回）。一样是雪，到了她手里便有高下。","出处":"维基文库 zh-hant 第023回（2026-10 抓取稿）；机器转字处按底本改正：簾捲（原作「帘卷」）、裡（「里」）、棲（「栖」）、懷（「怀」），「舖」「鷫」照录"},"zanghua-yin":{"题":"葬花吟","作者":"daiyu","名":"黛玉","回":27,"回目":"第二十七回　滴翠亭楊妃戲彩蝶　埋香冢飛燕泣殘紅","体":"歌行","句":["花謝花飛花滿天，紅消香斷有誰憐？","游絲軟繫飄春榭，落絮輕沾撲繡簾。","閨中女兒惜春暮，愁緒滿懷無釋處，","手把花鋤出繡閨，忍踏落花來復去。","柳絲榆莢自芳菲，不管桃飄與李飛。","桃李明年能再發，明年閨中知有誰？","三月香巢已壘成，梁間燕子太無情！","明年花發雖可啄，卻不道人去梁空巢也傾。","一年三百六十日，風刀霜劍嚴相逼，","明媚鮮妍能幾時，一朝飄泊難尋覓。","花開易見落難尋，階前悶殺葬花人，","獨倚花鋤淚暗灑，灑上空枝見血痕。","杜鵑無語正黃昏，荷鋤歸去掩重門。","青燈照壁人初睡，冷雨敲窗被未溫。","怪奴底事倍傷神，半為憐春半惱春：","憐春忽至惱忽去，至又無言去不聞。","昨宵庭外悲歌發，知是花魂與鳥魂？","花魂鳥魂總難留，鳥自無言花自羞。","願奴脅下生雙翼，隨花飛到天盡頭。","天盡頭，何處有香丘？","未若錦囊收艷骨，一抔淨土掩風流。","質本潔來還潔去，強於污淖陷渠溝。","爾今死去儂收葬，未卜儂身何日喪？","儂今葬花人笑痴，他年葬儂知是誰？","試看春殘花漸落，便是紅顏老死時。","一朝春盡紅顏老，花落人亡兩不知！"],"白话":"暮春花落，她把落花埋进干净土里，一句一句问自己：今天我葬花，笑我痴；将来谁来葬我？","串讲2":"芒种饯花那日，满园热闹，黛玉独在花冢边哭。「儂今葬花人笑痴，他年葬儂知是誰？」宝玉在山坡后听得痴倒。这是她给自己写的挽歌，后来字字都应了。","出处":"维基文库 zh-hant 第027回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","校字":[{"位置":"游絲軟系飄春榭","页面":"游絲軟系飄春榭","改":"游絲軟繫飄春榭","依据":"系结义的「系」改「繫」，同图鉴 codexData 文件头约定（该条图鉴 zanghua-yin 同改）"}]},"qiuchuang":{"题":"秋窗風雨夕","作者":"daiyu","名":"黛玉","回":45,"回目":"第四十五回　金蘭契互剖金蘭語　風雨夕悶製風雨詞","体":"歌行","句":["秋花慘淡秋草黃，耿耿秋燈秋夜長。","已覺秋窗秋不盡，那堪風雨助淒涼！","助秋風雨來何速！驚破秋窗秋夢綠。","抱得秋情不忍眠，自向秋屏移淚燭。","淚燭搖搖爇短檠，牽愁照恨動離情。","誰家秋院無風入？何處秋窗無雨聲？","羅衾不奈秋風力，殘漏聲催秋雨急。","連宵脈脈復颼颼，燈前似伴離人泣。","寒煙小院轉蕭條，疏竹虛窗時滴瀝。","不知風雨幾時休，已教淚灑窗紗濕。"],"白话":"秋夜雨里一个人灯下写词，一句一个「秋」字，写风雨穿窗、泪烛摇摇，到最后连窗纱都被眼泪湿透。","串讲2":"秋雨黄昏，黛玉拟《春江花月夜》之格写了这首，一句一个秋字。才写罢，宝玉披蓑戴笠来看她，她笑问「那裡來的漁翁」（第45回）。泪湿窗纱的人，见了他还是笑。","出处":"维基文库 zh-hant 第045回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"taohua-xing":{"题":"桃花行","作者":"daiyu","名":"黛玉","回":70,"回目":"第七十回　林黛玉重建桃花社　史湘雲偶填柳絮詞","体":"歌行","句":["桃花簾外東風軟，桃花簾內晨妝懶。","簾外桃花簾內人，人與桃花隔不遠。","東風有意揭簾櫳，花欲窺人簾不捲。","桃花簾外開仍舊，簾中人比桃花瘦。","花解憐人花也愁，隔簾消息風吹透。","風透湘簾花滿庭，庭前春色倍傷情。","閒苔院落門空掩，斜日欄杆人自憑。","憑欄人向東風泣，茜裙偷傍桃花立。","桃花桃葉亂紛紛，花綻新紅葉凝碧。","霧裹煙封一萬株，烘樓照壁紅模糊。","天機燒破鴛鴦錦，春酣欲醒移珊枕。","侍女金盆進水來，香泉影蘸胭脂冷。","胭脂鮮艷何相類，花之顏色人之淚，","若將人淚比桃花，淚自長流花自媚。","淚眼觀花淚易乾，淚乾春盡花憔悴。","憔悴花遮憔悴人，花飛人倦易黃昏。","一聲杜宇春歸盡，寂寞簾櫳空月痕！"],"白话":"帘外桃花开，帘里人比花瘦；用眼泪比花，泪流不停、花开自媚，杜鹃一叫春天走尽，只剩帘里空月。","串讲2":"宝玉一看便断定是潇湘子稿，宝琴笑说是她作的，书里两说并存。「簾中人比桃花瘦」，众人因此把海棠社改作桃花社，推黛玉为社主。花开得这样好，社却没起几回。","备注":"作者两说：宝玉认定「自然是瀟湘子稿」，宝琴笑说「現是我作的呢」，原文没有当面说破；图鉴 taohua-xing 条同样两说并存。这里先归黛玉名下，卡上建议标「（两说）」。","出处":"维基文库 zh-hant 第070回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-yong":{"题":"詠菊","作者":"daiyu","名":"黛玉","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["無賴詩魔昏曉侵，繞籬欹石自沉音。","毫端蘊秀臨霜寫，口齒噙香對月吟。","滿紙自憐題素怨，片言誰解訴秋心。","一從陶令平章後，千古高風說到今。"],"白话":"诗魔缠身，绕着篱笆倚着石头吟，对着月亮念，满纸写的是素日的怨；说自陶渊明评定菊花以后，千古高风一直说到今天。","串讲2":"菊花诗十二题，黛玉一人夺了三首，李纨公评《詠菊》第一。「滿紙自憐題素怨」，咏菊是题目，自怜是底子。魁首到底是潇湘妃子，这一回她最得意（第38回）。","备注":"第三十八回菊花诗十二题之一，页面署号「瀟湘妃子」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-wen":{"题":"問菊","作者":"daiyu","名":"黛玉","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["欲訊秋情眾莫知，喃喃負手叩東籬。","孤標傲世偕誰隱，一樣花開為底遲？","圃露庭霜何寂寞，鴻歸蛩病可相思？","休言舉世無談者，解語何妨片語時。"],"白话":"想打听秋天的心事没人知道，背着手低声去叩篱笆：你孤高傲世，能和谁一起隐？为什么偏偏开得这样迟？别说世上没人谈心，会说话的你不妨说两句。","串讲2":"「孤標傲世偕誰隱，一樣花開為底遲？」李纨评它第二。问菊原是问人：众芳都谢了，你何苦晚开。黛玉一生问的，大约都是这一句，只是没人答她。","备注":"第三十八回菊花诗十二题之一，页面署号「瀟湘妃子」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-meng":{"题":"菊夢","作者":"daiyu","名":"黛玉","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["籬畔秋酣一覺清，和雲伴月不分明。","登仙非慕莊生蝶，憶舊還尋陶令盟。","睡去依依隨雁斷，驚回故故惱蛩鳴。","醒時幽怨同誰訴，衰草寒煙無限情。"],"白话":"篱边醉了一觉清醒，和云伴月迷迷糊糊；不羡庄周化蝶，只想找回和陶渊明的旧盟；梦醒时的幽怨对谁说，只有衰草寒烟。","串讲2":"菊梦评了第三。梦里随雁去，醒来恼虫鸣，「醒時幽怨同誰訴」，结在衰草寒烟。她的诗凡写到醒处，总是一片冷清，梦倒比醒好些。","备注":"第三十八回菊花诗十二题之一，页面署号「瀟湘妃子」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-hua":{"题":"畫菊","作者":"baochai","名":"宝钗","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["詩餘戲筆不知狂，豈是丹青費較量。","聚葉潑成千點墨，攢花染出幾痕霜。","淡濃神會風前影，跳脫秋生腕底香。","莫認東籬閒采掇，粘屏聊以慰重陽。"],"白话":"这只是作诗之余的游戏笔墨，不必费心较量；泼墨成叶、染出一痕霜，别把它当成东篱闲采的真菊，只是贴在屏风上慰藉重阳。","串讲2":"宝钗画菊，偏说是「詩餘戲筆不知狂」。她劝黛玉时说过，作诗写字原不是分内之事（第42回）。样样都会，样样不肯当真，这一首里也看得出来。","备注":"第三十八回菊花诗十二题之一，页面署号「蘅蕪君」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-yi":{"题":"憶菊","作者":"baochai","名":"宝钗","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["悵望西風抱悶思，蓼紅葦白斷腸時。","空籬舊圃秋無跡，瘦月清霜夢有知。","念念心隨歸雁遠，寥寥坐聽晚砧痴，","誰憐我為黃花病，慰語重陽會有期。"],"白话":"西风里惆怅，蓼红苇白的断肠时节；空篱旧圃没了秋的踪迹，只在梦里知道；谁怜我为黄花生病，只好劝慰自己重阳会有个约期。","串讲2":"宝钗平日不露愁，诗里却说「誰憐我為黃花病」。她胎里带来一股热毒，要吃冷香丸压着（第7回）。丸药压得住热毒，压不住这一句。","备注":"第三十八回菊花诗十二题之一，页面署号「蘅蕪君」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-fang":{"题":"訪菊","作者":"baoyu","名":"宝玉","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["閒趁霜晴試一游，酒杯藥盞莫淹留。","霜前月下誰家種，檻外籬邊何處愁。","蠟屐遠來情得得，冷吟不盡興悠悠。","黃花若解憐詩客，休負今朝掛杖頭。"],"白话":"趁着霜晴出去走走，拄杖寻菊；霜前月下谁家种，篱边何处有愁；若黄花懂得怜惜诗客，别辜负今天杖头挂钱出来寻访的这一趟。","串讲2":"宝玉访菊，蜡屐远来，杖头挂钱，好一个闲人。「富貴閒人」这个号是宝钗给起的，他口说当不起，心里挺乐意（第37回）。这一首正是闲人的本色。","备注":"第三十八回菊花诗十二题之一，页面署号「怡紅公子」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-zhong":{"题":"種菊","作者":"baoyu","名":"宝玉","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["攜鋤秋圃自移來，籬畔庭前故故栽。","昨夜不期經雨活，今朝猶喜帶霜開。","冷吟秋色詩千首，醉酹寒香酒一杯。","泉溉泥封勤護惜，好知井徑絕塵埃。"],"白话":"扛着锄头把菊花从秋圃移来，篱边庭前栽满；一夜雨后居然活了，今朝带霜开；勤勤护惜，只愿这里的小路不染尘埃。","串讲2":"「好知井徑絕塵埃」，种菊的人盼一条小路不染尘埃。后来园子里抄检了一夜，各房箱笼都翻遍（第74回），干净的小路，到底一条也没剩下。","备注":"第三十八回菊花诗十二题之一，页面署号「怡紅公子」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-dui":{"题":"對菊","作者":"xiangyun","名":"湘云","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["別圃移來貴比金，一叢淺淡一叢深。","蕭疏籬畔科頭坐，清冷香中抱膝吟。","數去更無君傲世，看來惟有我知音。","秋光荏苒休辜負，相對原宜惜寸陰。"],"白话":"从别的园子移来的菊花，贵比黄金，一丛浅一丛深；坐在篱边抱膝吟诗，数来没有谁比它更傲世，看来只有我是它的知音。","串讲2":"湘云科头抱膝，口称「看來惟有我知音」，口气大得像醉卧芍药裀的那一个。曲子里说她「英豪闊大寬宏量」（第5回），菊花的知音，原该是她。","备注":"第三十八回菊花诗十二题之一，页面署号「枕霞舊友」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-gong":{"题":"供菊","作者":"xiangyun","名":"湘云","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["彈琴酌酒喜堪儔，几案婷婷點綴幽。","隔座香分三徑露，拋書人對一枝秋。","霜清紙帳來新夢，圃冷斜陽憶舊游。","傲世也因同氣味，春風桃李未淹留。"],"白话":"弹琴喝酒有菊作伴，几案上摆着幽雅的一枝；香从三径的露里分来，放下书正对着一枝秋；它傲世也因气味相投，春风里的桃李留不住它。","串讲2":"这一社是湘云做东，螃蟹却是宝钗替她预备的（第37回）。「拋書人對一枝秋」，琴酒书都撂下，只对着一枝菊。客中做东的人，这一枝秋是借来的。","备注":"第三十八回菊花诗十二题之一，页面署号「枕霞舊友」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-ying":{"题":"菊影","作者":"xiangyun","名":"湘云","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["秋光疊疊復重重，潛度偷移三徑中。","窗隔疏燈描遠近，籬篩破月鎖玲瓏。","寒芳留照魂應駐，霜印傳神夢也空。","珍重暗香休踏碎，憑誰醉眼認朦朧。"],"白话":"秋光层层叠叠，悄悄在三径间移动；窗隔着灯描出远近，篱把月筛碎；珍重暗香别踏碎，醉眼谁认得出这朦胧。","串讲2":"菊影一首写得最虚，窗隔灯，篱筛月，「珍重暗香休踏碎」。湘云最憨的人，偏写最怕碎的东西。册子上说她「湘江水逝楚雲飛」（第5回），到底也散了。","备注":"第三十八回菊花诗十二题之一，页面署号「枕霞舊友」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-zan":{"题":"簪菊","作者":"tanchun","名":"探春","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["瓶供籬栽日日忙，折來休認鏡中妝。","長安公子因花癖，彭澤先生是酒狂。","短鬢冷沾三徑露，葛巾香染九秋霜。","高情不入時人眼，拍手憑他笑路旁。"],"白话":"瓶里供、篱边栽，天天忙；折来别当镜里的妆；长安公子爱花，彭泽先生爱酒；短鬓戴着花沾露、葛巾染着霜，高情不入俗人眼，任凭路旁的人拍手笑。","串讲2":"探春簪菊，自比彭泽先生，「拍手憑他笑路旁」。后来她理家，赵姨娘当面哭闹，她也只按旧例办（第55回）。不怕路旁人笑的，这园里数她一个。","备注":"第三十八回菊花诗十二题之一，页面署号「蕉下客」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"ju-can":{"题":"殘菊","作者":"tanchun","名":"探春","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["露凝霜重漸傾欹，宴賞才過小雪時。","蒂有餘香金淡泊，枝無全葉翠離披。","半床落月蛩聲病，萬里寒雲雁陣遲。","明歲秋風知再會，暫時分手莫相思。"],"白话":"露凝霜重，花渐渐倾斜，赏宴刚过小雪；花蒂还有余香、枝上没有整片叶；半床落月、一声病蛩，万里寒云、迟迟的雁阵；明年秋风再会，暂时分手别相思。","串讲2":"十二题收在残菊，「明歲秋風知再會，暫時分手莫相思」。探春作结，说得这样笃定。她自己的分手，却是「一帆風雨路三千」（第5回），不是暂时的。","备注":"第三十八回菊花诗十二题之一，页面署号「蕉下客」。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"wumei-xi":{"题":"西施","作者":"daiyu","名":"黛玉","回":64,"回目":"第六十四回　幽淑女悲題五美吟　浪蕩子情遺九龍珮","体":"诗","句":["一代傾城逐浪花，吳宮空自憶兒家。","效顰莫笑東村女，頭白溪邊尚浣紗。"],"白话":"西施如今只剩一个传说：一代美人被浪花淘去，吴宫空自念着她；别笑东村效颦的女子，头发白了仍在溪边浣纱。","串讲2":"五美吟头一首。「效顰莫笑東村女，頭白溪邊尚浣紗」，效颦的活到白头，倾城的被浪花淘去。宝钗说她命意新奇（第64回），黛玉替古人叹，也是替自己叹。","组":"五美吟","备注":"《五美吟》五首之一（西施、虞姬、明妃、绿珠、红拂），宝玉看了说恰好五首，就叫《五美吟》。","出处":"维基文库 zh-hant 第064回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"wumei-yu":{"题":"虞姬","作者":"daiyu","名":"黛玉","回":64,"回目":"第六十四回　幽淑女悲題五美吟　浪蕩子情遺九龍珮","体":"诗","句":["腸斷烏騅夜嘯風，虞兮幽恨對重瞳。","黥彭甘受他年醢，飲劍何如楚帳中。"],"白话":"夜里乌骓风中嘶鸣，虞姬对着重瞳的项王含恨；韩信、彭越将来甘受酷刑，哪里比得上在楚营帐里拔剑自刎。","串讲2":"虞姬饮剑楚帐，黛玉说胜过韩彭受醢。她宁可干干净净地死，不肯苟且地活，葬花时早说过「質本潔來還潔去」（第27回）。","组":"五美吟","备注":"《五美吟》五首之一（西施、虞姬、明妃、绿珠、红拂），宝玉看了说恰好五首，就叫《五美吟》。","出处":"维基文库 zh-hant 第064回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"wumei-ming":{"题":"明妃","作者":"daiyu","名":"黛玉","回":64,"回目":"第六十四回　幽淑女悲題五美吟　浪蕩子情遺九龍珮","体":"诗","句":["絕艷驚人出漢宮，紅顏命薄古今同。","君王縱使輕顏色，予奪權何畀畫工？"],"白话":"王昭君绝艳惊人地出了汉宫，红颜命薄古今一样；君王纵使轻看颜色，生杀予夺的权力怎能交给画工？","串讲2":"「君王縱使輕顏色，予奪權何畀畫工？」黛玉替昭君问的，是谁说了算。她自己的终身，后来也是别人做主，连一句话都没问过她（第97回）。","组":"五美吟","备注":"《五美吟》五首之一（西施、虞姬、明妃、绿珠、红拂），宝玉看了说恰好五首，就叫《五美吟》。","出处":"维基文库 zh-hant 第064回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"wumei-lu":{"题":"綠珠","作者":"daiyu","名":"黛玉","回":64,"回目":"第六十四回　幽淑女悲題五美吟　浪蕩子情遺九龍珮","体":"诗","句":["瓦礫明珠一例拋，何曾石尉重嬌嬈。","都緣頑福前生造，更有同歸慰寂寥。"],"白话":"绿珠一例被抛作瓦砾间的明珠，石崇何曾真重视她；都因前世修下的顽福，还有同归于尽来安慰寂寥。","串讲2":"绿珠坠楼殉了石崇，黛玉偏说「何曾石尉重嬌嬈」，把殉情的体面揭了底。这眼光刁得很，深闺里的姑娘，看男人看得这样透。","组":"五美吟","备注":"《五美吟》五首之一（西施、虞姬、明妃、绿珠、红拂），宝玉看了说恰好五首，就叫《五美吟》。","出处":"维基文库 zh-hant 第064回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"wumei-hong":{"题":"紅拂","作者":"daiyu","名":"黛玉","回":64,"回目":"第六十四回　幽淑女悲題五美吟　浪蕩子情遺九龍珮","体":"诗","句":["長揖雄談態自殊，美人巨眼識窮途。","屍居餘氣楊公幕，豈得羈縻女丈夫。"],"白话":"红拂长揖雄谈、风姿特别，美人慧眼识得落魄英雄；杨素那样空占着尸居余气的官位，怎能羁縻这位女丈夫。","串讲2":"五美吟收在红拂：「美人巨眼識窮途」，五个里只这一个自己挑了人，走了出去。黛玉写到她，笔下才有一点快意，想来是羡慕的。","组":"五美吟","备注":"《五美吟》五首之一（西施、虞姬、明妃、绿珠、红拂），宝玉看了说恰好五首，就叫《五美吟》。","出处":"维基文库 zh-hant 第064回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"tipa":{"题":"題帕三絕","作者":"daiyu","名":"黛玉","回":34,"回目":"第三十四回　情中情因情感妹妹　錯里錯以錯勸哥哥","体":"诗","句":["眼空蓄淚淚空垂，暗灑閒拋卻為誰？","尺幅鮫鮹勞解贈，叫人焉得不傷悲！","其二","拋珠滾玉只偷潸，鎮日無心鎮日閒，","枕上袖邊難拂拭，任他點點與斑斑。","其三","彩線難收面上珠，湘江舊跡已模糊，","窗前亦有千竿竹，不識香痕漬也無？"],"白话":"她在宝玉送来的两条旧帕上题三首：第一首问眼泪为谁洒，第二首说泪擦不干，第三首对着窗前的竹子，问它认不认帕上的泪痕。","串讲2":"宝玉挨打后叫晴雯送来两块旧帕，黛玉一时「五內沸然炙起」，当夜题了三首。后来焚稿那日，她要了诗本子，又要这块旧帕，狠命要撕，却撕不动了（第97回）。","备注":"页面按「其二」「其三」分首，句里保留这两个小标题，竖排时各占一列。「鮫鮹」照页面。","出处":"维基文库 zh-hant 第034回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"liuxu-dai":{"题":"唐多令·柳絮","作者":"daiyu","名":"黛玉","回":70,"回目":"第七十回　林黛玉重建桃花社　史湘雲偶填柳絮詞","体":"词","句":["粉墮百花州，香殘燕子樓。一團團逐對成毬。飄泊亦如人命薄，空繾綣，說風流。","草木也知愁，韶華竟白頭！歎今生誰捨誰收？嫁與東風春不管，憑爾去，忍淹留。"],"白话":"柳絮落满百花洲，像人命薄：团团逐对成毬，飘泊没有归处；草木也知愁、韶华白了头，最后说嫁与东风它也不管，只能由它去、忍着挽留。","串讲2":"众人看了说「太作悲了」。「嫁與東風春不管」，柳絮如此，她的终身也如此，没有一个人替她做主。一开口便是粉堕香残，像是早知道散场。","备注":"咏柳絮词，众人看了说「太作悲了」；探春、宝琴、宝钗、湘云各有一首。","出处":"维基文库 zh-hant 第070回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"liuxu-chai":{"题":"臨江仙·柳絮","作者":"baochai","名":"宝钗","回":70,"回目":"第七十回　林黛玉重建桃花社　史湘雲偶填柳絮詞","体":"词","句":["白玉堂前春解舞，東風卷得均勻。","蜂團蝶陣亂紛紛。幾曾隨逝水，豈必委芳塵。","萬縷千絲終不改，任他隨聚隨分。韶華休笑本無根，好風頻借力，送我上青雲！"],"白话":"偏要把柳絮说好：它在白玉堂前随东风起舞，蜂团蝶阵里乱纷纷，万缕千丝始终不改，哪怕本无根，只要好风借力，就送我上青云。","串讲2":"人人写柳絮飘零，宝钗偏翻作「送我上青雲」，众人拍案叫绝，推为第一。她要的是上去，不是落下。后来金玉良缘成了，宝玉却随僧道去了（第120回）。","备注":"页面把这首词拆成三段，中间夹了湘云赞「東風卷得均勻」的一句叙述，此处只取词句；众人评这首为尊。","出处":"维基文库 zh-hant 第070回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"pangxie":{"题":"螃蟹詠","作者":"baochai","名":"宝钗","回":38,"回目":"第三十八回　林瀟湘魁奪菊花詩　薛蘅蕪諷和螃蟹詠","体":"诗","句":["桂靄桐陰坐舉觴，長安涎口盼重陽。","眼前道路無經緯，皮裡春秋空黑黃。","酒未敵腥還用菊，性防積冷定須薑。","於今落釜成何益，月浦空餘禾黍香。"],"白话":"借吃螃蟹讽刺世人：坐在桂荫桐阴下举杯，只盼重阳；它横行却路径无章，皮里春秋空有黑黄；酒也敌不过腥，要用菊和姜，如今落了锅有什么用，只剩月下水边的禾黍香。","串讲2":"持螯赏桂那日，宝钗一首螃蟹咏，众人说讽刺世人太毒。「眼前道路無經緯，皮裡春秋空黑黃」，平日最温厚的人，下笔骂起人来最狠。","备注":"页面把这首拆成三段，中间夹着宝玉说「寫得痛快」的叙述，这里只取诗句。众人说这是食螃蟹绝唱，只是讽刺世人太毒。","出处":"维基文库 zh-hant 第038回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","组":"螃蟹詠"},"haitang-xiangyun-1":{"题":"詠白海棠（其一）","作者":"xiangyun","名":"湘云","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","体":"诗","句":["神仙昨日降都門，種得藍田玉一盆。","自是霜娥偏愛冷，非關倩女亦離魂。","秋陰捧出何方雪，雨漬添來隔宿痕。","卻喜詩人吟不倦，豈令寂寞度朝昏。"],"白话":"湘云一进社就依韵和了两首。第一首说海棠像神仙昨日降到都门、种下的一盆蓝田玉，偏爱冷，不是倩女离魂；秋阴捧出雪，雨痕添了隔宿的印。","串讲2":"湘云来迟，一气和了两首，众人说这才不枉起海棠社。「自是霜娥偏愛冷」，最热闹的人偏写一个冷字。册子上说她「襁褓之間父母違」（第5回），冷是从小就有的。","备注":"湘云来迟，补作两首，众人说「不枉作了海棠詩，真該要起海棠社了」。","出处":"维基文库 zh-hant 第037回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"haitang-xiangyun-2":{"题":"詠白海棠（其二）","作者":"xiangyun","名":"湘云","回":37,"回目":"第三十七回　秋爽齋偶結海棠社　蘅蕪苑夜擬菊花題","体":"诗","句":["蘅芷階通蘿薜門，也宜牆角也宜盆。","花因喜潔難尋偶，人為悲秋易斷魂。","玉燭滴乾風裡淚，晶簾隔破月中痕。","幽情慾向嫦娥訴，無奈虛廊夜色昏。"],"白话":"第二首：蘅芷阶通到蘿薜门，海棠墙角盆里都宜；花因爱洁难寻同伴，人为悲秋易断魂；风里泪、月中痕，想对嫦娥倾诉，无奈走廊空、夜色昏。","串讲2":"第二首比第一首凉：「花因喜潔難尋偶，人為悲秋易斷魂」。曲子里说她嫁得才貌仙郎，「終久是雲散高唐」（第5回），难寻偶三字，竟说中了。","校字":[{"位置":"玉燭滴乾風里淚","页面":"風里淚","改":"風裡淚","依据":"作「内」讲的「里」改「裡」，同图鉴 codexData 文件头约定"}],"出处":"维基文库 zh-hant 第037回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"liuxu-yun":{"题":"如夢令·柳絮","作者":"xiangyun","名":"湘云","回":70,"回目":"第七十回　林黛玉重建桃花社　史湘雲偶填柳絮詞","体":"词","句":["豈是繡絨殘吐，捲起半簾香霧，纖手自拈來，空使鵑啼燕妒。且住，且住！莫使春光別去。"],"白话":"她看见柳花飘舞，随手填了这首小令：哪是绣绒吐残、卷起半帘香雾，是纤手拈起的，只让杜鹃啼、燕子嫉妒；且住且住，别让春光走了。","串讲2":"暮春湘云看柳花飘舞，随手填了这阕小令，拿给黛玉看，才起了柳絮社。「且住，且住！莫使春光別去」，留春的话只有她说得这样憨，春是留不住的。","备注":"暮春，湘云看柳花所作，拿给黛玉看，才引出下一日起社填词的柳絮题。","出处":"维基文库 zh-hant 第070回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"qimei-shi":{"题":"訪妙玉乞紅梅","作者":"baoyu","名":"宝玉","回":50,"回目":"第五十回　蘆雪广爭聯即景詩　暖香塢創製春燈謎[1]","体":"诗","句":["酒未開樽句未裁，","尋春問臘到蓬萊。","不求大士瓶中露，為乞嫦娥檻外梅。","入世冷挑紅雪去，離塵香割紫雲來。","槎枒誰惜詩肩瘦，衣上猶沾佛院苔。"],"白话":"被罚去栊翠庵向妙玉讨红梅，在黛玉、湘云催逼下一联联念出：不求观音瓶里的露，只乞嫦娥栏外的梅；入世挑红雪、离尘割紫云，衣上还沾着佛院的苔。","串讲2":"芦雪广联句宝玉落第，罚去栊翠庵讨红梅。「為乞嫦娥檻外梅」，檻外两字下得巧，后来妙玉给他的拜帖，落款便是「檻外人」（第63回）。","备注":"页面把每联拆在叙述之间，这里只取诗句，共五联十句分五行（首联第一句单列一行）。","出处":"维基文库 zh-hant 第050回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"liuxu-tan":{"题":"南柯子·柳絮","作者":["tanchun","baoyu"],"名":"探春、宝玉","回":70,"回目":"第七十回　林黛玉重建桃花社　史湘雲偶填柳絮詞","体":"词","句":["空掛纖纖縷，徒垂絡絡絲，也難綰繫也難羈，一任東西南北各分離。","落去君休惜，飛來我自知。鶯愁蝶倦晚芳時，縱是明春再見隔年期！"],"白话":"探春只写了半首：柳丝空挂、络络垂丝，既难系又难羁，任它东西南北各分离；宝玉续下半：落去你别惜，飞来我自知，莺愁蝶倦的晚芳时，纵是明春再见也隔年期。","串讲2":"探春才写了半阕，香便尽了，宝玉替她续下。上半「也難綰繫也難羈」，句句离散；下半「縱是明春再見隔年期」，倒像是替她送行。","句作者":[["tanchun"],["baoyu"]],"备注":"探春香快烧完只作了上半，宝玉本拈《蝶戀花》却没写成，见探春半首没完，提笔续成。上半「空掛纖纖縷…各分離」是探春，下半「落去君休惜…隔年期」是宝玉。","出处":"维基文库 zh-hant 第070回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","校字":[{"位置":"也難綰系也難羈","页面":"也難綰系也難羈","改":"也難綰繫也難羈","依据":"系结义的「系」改「繫」，同图鉴 codexData 文件头约定（该条图鉴 zanghua-yin 同改）"}]},"guihua-ci":{"题":"姽嫿詞","作者":"baoyu","名":"宝玉","回":78,"回目":"第七十八回　老學士閒徵姽嫿詞　痴公子杜撰芙蓉誄","体":"歌行","句":["恆王好武兼好色，","遂教美女習騎射。","穠歌艷舞不成歡，列陣挽戈為自得。","眼前不見塵沙起，將軍俏影紅燈裡。","叱吒時聞口舌香，霜矛雪劍嬌難舉。","丁香結子芙蓉絛，","不繫明珠繫寶刀。","戰罷夜闌心力怯，脂痕粉漬污鮫鮹。","明年流寇走山東，強吞虎豹勢如蜂。","王率天兵思剿滅，一戰再戰不成功。","腥風吹折隴頭麥，日照旌旗虎帳空。","青山寂寂水澌澌，正是恆王戰死時。","雨淋白骨血染草，月冷黃沙鬼守屍。","紛紛將士只保身，青州眼見皆灰塵，","不期忠義明閨閣，憤起恆王得意人。","恆王得意數誰行，姽嫿將軍林四娘，","號令秦姬驅趙女，艷李穠桃臨戰場。","繡鞍有淚春愁重，鐵甲無聲夜氣涼。","勝負自然難預定，誓盟生死報前王。","賊勢猖獗不可敵，柳折花殘實可傷，","魂依城郭家鄉近，馬踐胭脂骨髓香。","星馳時報入京師，誰家兒女不傷悲！","天子驚慌恨失守，此時文武皆垂首。","何事文武立朝綱，不及閨中林四娘！","我為四娘長太息，歌成余意尚傍徨。"],"白话":"贾政命作林四娘的事，宝玉先说要古体长篇歌行，边念边被贾政改：恒王好武又好色，教美女学骑射；流寇来犯，恒王战死，众将保身，林四娘率姬妾上阵殉难；满朝文武，还不及闺中林四娘。","串讲2":"贾政命题，众清客都作，宝玉这首长歌压了场。「何事文武立朝綱，不及閨中林四娘」，满朝文武不如一个女子，贾政听着点头，也不知骂的是谁（第78回）。","备注":"分句出自页面里被贾政、众人评语打断的几十处，这里按念出的次序合成一首（共 10 个念诵片段）。同一回里贾环、贾兰各有一首七绝，这里不收。贾政评「粗鄙」是对第一句。","校字":[{"位置":"將軍俏影紅燈里","页面":"紅燈里","改":"紅燈裡","依据":"作「内」讲的「里」改「裡」，同图鉴 codexData 文件头约定"}],"待核":"末句「歌成余意尚傍徨」：页面作「余」，繁体一般作「餘」（「余」也是合法繁体字，意思是我）。按页面照录，没有改；要不要改「餘」待下一轮对着纸本核。","出处":"维基文库 zh-hant 第078回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","组":"姽嫿詞"},"furong-lei":{"题":"芙蓉女兒誄","作者":"baoyu","名":"宝玉","回":78,"回目":"老學士閒徵姽嫿詞 痴公子杜撰芙蓉誄","句":["維太平不易之元，蓉桂競芳之月，無可奈何之日，怡紅院濁玉，謹以群花之蕊、冰鮫之縠、沁芳之泉、楓露之茗，四者雖微，聊以達誠申信，乃致祭於白帝宮中撫司秋艷芙蓉女兒之前曰：","竊思女兒自臨濁世，迄今凡十有六載。其先之鄉籍姓氏，湮淪而莫能考者久矣。而玉得於衾枕櫛沐之間，棲息宴遊之夕，親昵狎褻，相與共處者，僅五年八月有畸。憶女兒曩生之昔，其為質則金玉不足喻其貴，其為性則冰雪不足喻其潔，其為神則星日不足喻其精，其為貌則花月不足喻其色。姊妹悉慕媖嫻，嫗媼咸仰惠德。孰料鳩鴆惡其高，鷹鷙翻遭罦罬，薋葹妒其臭，茞蘭竟被芟鉏！花原自怯，豈奈狂飆，柳本多愁，何禁驟雨。偶遭蠱蠆之讒，遂抱膏肓之疚。故爾櫻唇紅褪，韻吐呻吟，杏臉香枯，色陳顑頷，諑謠謑詬，出自屏幃，荊棘蓬榛，蔓延戶牖。豈招尤則替，實攘詬而終。既忳幽沉於不盡，復含罔屈於無窮。高標見嫉，閨幃恨比長沙，直烈遭危，巾幗慘於羽野。自蓄辛酸，誰憐夭折！仙雲既散，芳趾難尋。洲迷聚窟，何來卻死之香？海失靈槎，不獲回生之藥。眉黛煙青，昨猶我畫，指環玉冷，今倩誰溫？鼎爐之剩藥猶存，襟淚之餘痕尚漬。鏡分鸞別，愁開麝月之奩，梳化龍飛，哀折檀雲之齒。委金鈿於草莽，拾翠㔩於塵埃。樓空鳷鵲，徒懸七夕之針，帶斷鴛鴦，誰續五絲之縷？況乃金天屬節，白帝司時，孤衾有夢，空室無人。桐階月暗，芳魂與倩影同銷，蓉帳香殘，嬌喘共細言皆絕。連天衰草，豈獨蒹葭，匝地悲聲，無非蟋蟀。露苔晚砌，穿簾不度寒砧，雨荔秋垣，隔院希聞怨笛。芳名未泯，檐前鸚鵡猶呼，艷質將亡，檻外海棠預老。捉迷屏後，蓮瓣無聲，鬪草庭前，蘭芽枉待。拋殘繡線，銀箋彩縷誰裁？折斷冰絲，金斗御香未熨。昨承嚴命，既趨車而遠涉芳園，今犯慈威，復拄杖而遽拋孤柩。及聞槥棺被燹，慚違共穴之盟，石槨成災，愧迨同灰之誚。爾乃西風古寺，淹滯青燐，落日荒丘，零星白骨。楸榆颯颯，蓬艾蕭蕭。隔霧壙以啼猿，繞煙塍而泣鬼。自為紅綃帳裏，公子情深，始信黃土壟中，女兒命薄！汝南淚血，斑斑灑向西風，梓澤餘衷，默默訴憑冷月。嗚呼！固鬼蜮之為災，豈神靈而亦妒。鉗詖奴之口，討豈從寬，剖悍婦之心，忿猶未釋！在君之塵緣雖淺，然玉之鄙意豈終。因蓄拳拳之思，不禁諄諄之問。始知上帝垂旌，花宮待詔，生儕蘭蕙，死轄芙蓉。聽小婢之言，似涉無稽，以濁玉之思，則深為有據。何也？昔葉法善攝魂以撰碑，李長吉被詔而為記，事雖殊，其理則一也。故相物以配才，苟非其人，惡乃濫乎？始信上帝委託權衡，可謂至洽至協，庶不負其所秉賦也。因希其不昧之靈，或陟降於茲，特不揣鄙俗之詞，有污慧聽。乃歌而招之曰：","天何如是之蒼蒼兮，乘玉虯以游乎穹窿耶？","地何如是之茫茫兮，駕瑤象以降乎泉壤耶？","望傘蓋之陸離兮，抑箕尾之光耶？","列羽葆而為前導兮，衛危虛於旁耶？","驅豐隆以為比從兮，望舒月以離耶？","聽車軌而伊軋兮，御鸞鷖以征耶？","問馥郁而薆然兮，紉蘅杜以為纕耶？","炫裙裾之爍爍兮，鏤明月以為璫耶？","籍葳蕤而成壇畸兮，檠蓮焰以燭蘭膏耶？","文瓟匏以為觶斝兮，漉醽醁以浮桂醑耶？","瞻雲氣而凝盼兮，仿佛有所覘耶？","俯窈窕而屬耳兮，恍惚有所聞耶？","期汗漫而無夭閼兮，忍捐棄余於塵埃耶？","倩風廉之為余驅車兮，冀聯轡而攜歸耶？","余中心為之慨然兮，徒嗷嗷而何為耶？","君偃然而長寢兮，豈天運之變於斯耶？","既窀穸且安穩兮，反其真而復奚化耶？","余猶桎梏而懸附兮，靈格余以嗟來耶？","來兮止兮，君其來耶！","若夫鴻蒙而居，寂靜以處，雖臨於茲，余亦莫睹。搴煙蘿而為步幛，列槍蒲而森行伍。警柳眼之貪眠，釋蓮心之味苦。素女約於桂巖，宓妃迎於蘭渚。弄玉吹笙，寒簧擊敔。徵嵩岳之妃，啟驪山之姥。龜呈洛浦之靈，獸作咸池之舞。潛赤水兮龍吟，集珠林兮鳳翥。爰格爰誠，匪簠匪筥。發軔乎霞城，返旌乎玄圃。既顯微而若通，復氤氳而倏阻。離合兮煙雲，空濛兮霧雨。塵霾斂兮星高，溪山麗兮月午。何心意之忡忡，若寤寐之栩栩。余乃欷歔悵望，泣涕傍徨。人語兮寂歷，天籟兮篔簹。鳥驚散而飛，魚唼喋以響。誌哀兮是禱，成禮兮期祥。嗚呼哀哉！尚饗！"],"白话":"在太平长久的年岁、芙蓉桂花争芳的月份、令人无可奈何的日子，怡红院的浊玉谨以百花花蕊、传说中鲛人织成的细纱、沁芳泉水和枫露茶，向白帝宫中掌管秋日芙蓉的女儿致祭。祭品虽然微薄，姑且用来表达诚心。\\n\\n想你来到人世，至今共十六年。你的祖籍和姓氏，早已无从查考。我与你在起居梳洗、休息宴游中亲密相处，只有五年八个月有余。回想你生前，金玉不足以比你的尊贵，冰雪不足以比你的纯洁，星辰太阳不足以比你的神采，花与月不足以比你的容貌。姐妹们都爱慕你的美好娴雅，年长的妇人也敬重你的贤德。\\n\\n谁料恶鸟嫉妒高飞的雄鹰，雄鹰反而落入罗网；恶草嫉妒芳香的兰草，兰草竟遭铲除。花本柔弱，怎受得了狂风；柳本多愁，怎禁得住骤雨。你遭了恶毒的谗言，便抱着难以救治的重病。嘴唇褪去红色，呻吟从口中传出；脸庞失去光泽，露出憔悴饥瘦的模样。谣言与辱骂从内室传来，荆棘般的恶意蔓延到门窗。你并非因自己的过错而被斥退，实是蒙受污辱而死。深沉的忧愁没有尽头，无穷的冤屈也含在心中。你品格高洁却遭嫉妒，闺中的遗恨如同贾谊被贬长沙；你刚直而遭祸，身为女子，遭遇比死于羽野的鲧更惨。辛酸独自承受，谁来怜惜你的早逝！\\n\\n如今你已如仙云消散，再难寻到踪迹。找不到聚窟洲，哪里求得使死者复生的香？失去了渡海的仙筏，也就求不到回生的药。你烟青的眉毛，昨日还由我描画；如今指环冰冷，又请谁来温暖？炉中剩药还在，衣襟上的泪痕未干。镜分鸾别，打开妆匣便觉悲愁；梳子如化龙飞去，断齿也令人伤心。金钿遗落草间，翠饰只能从尘埃中拾起。华楼空了，七夕乞巧的针徒然悬着；鸳鸯带断了，谁来接续五色丝线？\\n\\n正值秋天，白帝掌管时令。孤独的被衾中只有梦，空荡的房里再无你。梧桐阶前月色暗淡，你的魂魄与身影一同消失；芙蓉帐中余香渐尽，你的呼吸和细语都已断绝。衰草连天，何止芦苇；悲声遍地，尽是蟋蟀。晚间台阶生着露湿的青苔，帘内听不到捣衣声；秋雨打着荔枝掩映的院墙，隔院偶尔传来哀怨的笛声。你的名字还未被忘记，檐前鹦鹉仍在呼唤；你的美好形体将要毁灭，栏外海棠也早早衰败。屏后捉迷藏，再听不见你轻轻的脚步；庭前斗草，兰芽白白等着你。绣线散落，纸张和彩线由谁裁制？洁白的丝线折断了，金熨斗中的香炭也无人再用。\\n\\n昨日奉父亲之命，我乘车远行于芳园；今日冒着触怒母亲的风险，拄杖而行，却未能守在你孤零零的灵柩旁。听说你的棺木已被焚烧，我惭愧未能践行与你同葬的约定；棺椁遭毁，也使我愧对一同化灰的誓言。想到西风中的古寺，磷火滞留；落日下的荒丘，白骨零散。楸榆树声飒飒，蓬艾草声萧萧，猿啼隔着雾中的墓穴传来，鬼哭绕着烟中的田埂回荡。我自以为在红绡帐中用情很深，如今才信黄土坟中的女儿命薄。像汝南王哀悼碧玉那样的血泪，洒向西风；像石崇怀念绿珠那样未尽的悲情，向冷月默默倾诉。\\n\\n唉！固然是阴险小人造成了灾祸，难道神灵也嫉妒你吗？那些进谗奴仆的嘴应当封住，对他们的声讨怎能宽纵？便是剖开凶悍妇人的心，也不能平息我的愤怒！你在人间的缘分虽然短浅，我的情意却怎会终止？因为怀着深切的思念，我不禁反复追问，才得知天帝褒奖你，让你到花宫听候任命：生前与兰蕙为伴，死后掌管芙蓉。听小丫头的话，似乎没有根据；依我想来，却很有道理。为什么？从前有叶法善摄取李邕之魂书碑、李长吉被天帝召去作记的传说，事情虽不同，道理却一样。任命应当使花的品性与人的才德相配，若不是合适的人，怎能随意授职？所以我相信天帝的安排十分妥当，不辜负你的天赋。希望你不灭的灵魂能来到这里，请容我用粗浅的文字向你致意。于是唱歌招请你：\\n\\n天空为什么这样苍茫？你正乘玉龙游于高天吗？大地为什么这样辽阔？你正驾着美玉象牙装饰的车，降到地下吗？眼前光彩斑斓的车盖，是箕星、尾星的光吗？羽饰仪仗排列在前，危星、虚星护卫在旁吗？雷神丰隆随从着你，月神望舒也相伴吗？听见车轮咿呀作响，是你驾着鸾鹥出行吗？这浓郁的香气，是你把蘅杜香草串成了佩带吗？裙裾闪耀，是你用明月珠制成耳饰了吗？香草铺成祭坛，莲花形灯焰燃起芳香的油吗？雕饰的葫芦做成酒器，滤出的美酒中浮着桂花酒吗？我凝望云气，仿佛看见了什么；向幽深处侧耳，又恍惚听见了什么。你期望遨游无边、再无阻碍，难道忍心把我丢在人间？可否请风神为我驾车，让我与你并驾，一同归去？我心中如此悲愤，只是哀号又有什么用？你安然长眠，难道是天运在此发生了变化？既已安葬，返归本真，还会有什么变化？我仍受尘世束缚，你的灵魂能否到来，呼唤我相随？来吧，停在这里吧，你会来吗？\\n\\n你若居于混沌幽静的境界，即使到了这里，我也看不见。牵起烟雾中的藤萝作步幛，排列枪一般的菖蒲作仪仗；唤醒贪睡的柳眼，解除莲心的苦味。素女相约于桂岩，宓妃迎接于兰洲；弄玉吹笙，寒簧敲击敔这种乐器。请来嵩岳神妃，迎出骊山老母。神龟在洛水显灵，群兽随着咸池乐起舞。龙在赤水深处吟鸣，凤飞集于珠林。使神灵到来的是真诚，并不在于祭器。你从霞城出发，又回转旌旗向玄圃而去。幽明之间似乎刚刚相通，又被云气迅速隔断。聚散如烟云，迷蒙如雾雨。尘雾消散，星空高远；溪山明丽，月到中天。我为何仍忧心不安，像在梦与醒之间见到你鲜活的身影？于是抽泣怅望，流泪徘徊。人声寂静，只听竹林发出天籁；鸟儿惊散飞起，鱼儿吞吐水面发出声响。我以此祭告寄托哀思，祭礼完成，祈求吉祥。唉，悲痛啊！请来享用祭品！","串讲2":"第七十八回宝玉闻晴雯已死，撰《芙蓉女儿诔》于芙蓉花前祭之。上仿楚辞招魂，中述晴雯遭谗夭折之冤，下寄自己不能同穴之愧，是宝玉在书中写得最重、最见真性情的一篇文字。","出处":"第78回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诔文","备注":"全文（原先只收节选）","异文":["「自臨濁世」程乙本作「自臨人世」","「有畸」程乙本作「有奇」","「其為性則冰雪」程乙本作「其為體則冰雪」","「姊妹悉慕」程乙本作「姊娣悉慕」","「惠德」程乙本作「慧德」","「茞蘭竟被芟鉏」程乙本作「茝蘭竟被芟蒩」","「膏肓之疚」程乙本作「膏肓之疾」","「故爾櫻唇」程乙本作「故櫻脣」","程乙本无「豈招尤則替，實攘詬而終」一句","「既忳幽沉」程乙本作「既懷幽沉」","「閨幃恨比長沙」程乙本作「閨闈恨比「長沙」」","「直烈遭危」程乙本作「貞烈遭危」","「巾幗慘於羽野」程乙本作「巾幗慘於「雁塞」」","「鏡分鸞別」程乙本作「鏡分鸞影」","「拾翠㔩」程乙本作「拾翠盒」","「徒懸七夕之針」程乙本作「從懸七夕之針」","「細言皆絕」程乙本作「細腰俱絕」","「露苔晚砌」程乙本作「露階晚砌」","「海棠預老」程乙本作「海棠預萎」","「蘭芽枉待」程乙本作「蘭芳枉待」","「銀箋彩縷」程乙本作「銀箋彩袖」","「遠涉芳園」程乙本作「遠陟芳園」","「遽拋孤柩」程乙本作「遣拋孤柩」","「槥棺被燹」程乙本作「蕙棺被燹」","「慚違共穴之盟」程乙本作「頓違共穴之情」","「愧迨同灰」程乙本作「愧逮同灰」","「自為紅綃帳裏」程乙本作「豈道紅綃帳裡」","「汝南淚血，斑斑灑向西風，梓澤餘衷，默默訴憑冷月」程乙本作「汝南斑斑淚血，灑向西風；梓澤默默餘衷，訴憑冷月」","「豈神靈而亦妒」程乙本作「豈神靈之有妒」","「鉗詖奴之口」程乙本作「毀詖奴之口」","「在君之塵緣雖淺，然玉之鄙意豈終」程乙本作「在卿之塵緣雖淺，而玉之鄙意尤深」","「因蓄拳拳」程乙本作「因蓄惓惓」","「以濁玉之思，則深為有據」程乙本作「據濁玉之思，深為有據」","「苟非其人」程乙本作「苛非其人」","「以為比從兮，望舒月以離耶」程乙本作「以為庇從兮，望舒月以臨耶」","「車軌」程乙本作「車軸」","「問馥郁而薆然兮，紉蘅杜以為纕耶」程乙本作「聞馥郁而飄然兮，紉蘅杜以為佩耶」","「炫裙裾」程乙本作「斕裙裾」","「籍葳蕤」程乙本作「藉葳蕤」","「成壇畸兮，檠蓮焰」程乙本作「成壇畤兮，擎蓮焰」","「文瓟匏」程乙本作「文瓠瓟」","「漉醽醁」程乙本作「灑醽醁」","「凝盼」程乙本作「凝眸」","「俯窈窕而屬耳」程乙本作「俯波痕而屬耳」","「無夭閼兮，忍捐棄余」程乙本作「無際兮，捐棄予」","「君偃然」程乙本作「卿偃然」","「復奚化耶」程乙本作「又奚化耶」","「君其來耶」程乙本作「卿其來耶」","「匪簠匪筥」程乙本作「匪苕匪簠」","「返旌乎玄圃」程乙本作「還旌乎玄圃」","「若通」程乙本作「若逋」","「忡忡」程乙本作「怦怦」","「悵望」程乙本作「悵怏」","「傍徨」程乙本作「彷徨」","另：「余」程乙本多作「餘/予」，「鬪」作「鬥」等字形差异不逐条记"]},"dengmi-yingchun":{"题":"燈謎（算盤）","作者":"yingchun","名":"迎春","回":22,"回目":"第二十二回　聽曲文寶玉悟禪機　製燈迷賈政悲讖語","体":"谜诗","句":["天運人功理不窮，有功無運也難逢。","因何鎮日紛紛亂，只為陰陽數不同。"],"白话":"谜底算盘：天运人功道理不穷，有功没运也难逢；为什么整天纷纷乱，只为阴阳数不同。","串讲2":"算盘谜。「有功無運也難逢」，迎春的命正在这句里。贾政看了说是打动乱如麻，心里先不自在。后来嫁了中山狼，「一載赴黃粱」（第5回）。","备注":"元宵后贾政看众人制的灯谜，迎春这首谜底是算盘；贾政读时说「是算盤」，迎春笑着答「是」。迎春除灯谜外原书没有留下其他诗作。","出处":"维基文库 zh-hant 第022回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"dengmi-xichun":{"题":"燈謎（海燈）","作者":"xichun","名":"惜春","回":22,"回目":"第二十二回　聽曲文寶玉悟禪機　製燈迷賈政悲讖語","体":"谜诗","句":["前身色相總無成，不聽菱歌聽佛經。","莫道此生沉黑海，性中自有大光明。"],"白话":"谜底佛前海灯：前身色相一场空，不听菱歌听佛经；别说此生沉在黑海，性中自有大光明。","串讲2":"海灯谜。「不聽菱歌聽佛經」，小小年纪便有出家的意思，贾政嫌它清净孤独。册子上早写着她「獨臥青燈古佛旁」（第5回）。","备注":"贾政看了说「這是佛前海燈」，惜春笑答「是海燈」；他心里嫌这谜句有出家之意。","出处":"维基文库 zh-hant 第022回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"dengmi-tanchun":{"题":"燈謎（風箏）","作者":"tanchun","名":"探春","回":22,"回目":"第二十二回　聽曲文寶玉悟禪機　製燈迷賈政悲讖語","体":"谜诗","句":["階下兒童仰面時，清明妝點最堪宜。","游絲一斷渾無力，莫向東風怨別離。"],"白话":"谜底风筝：阶下孩子仰面看，清明时节装点最宜；游丝一断就没了力气，别在东风里怨别离。","串讲2":"风筝谜。「游絲一斷渾無力，莫向東風怨別離」，贾政嫌是飘飘浮荡之物。册子上她那一页，画的正是两人放风筝，大海大船，掩面泣涕（第5回）。","备注":"贾政看后「這是風箏」，探春笑答「是」；他嫌这谜句有离散之意。","出处":"维基文库 zh-hant 第022回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","组":"燈謎"},"dengmi-baochai":{"题":"燈謎（更香）","作者":"baochai","名":"宝钗","回":22,"回目":"第二十二回　聽曲文寶玉悟禪機　製燈迷賈政悲讖語","体":"谜诗","句":["朝罷誰攜兩袖煙，琴邊衾裡總無緣。","曉籌不用雞人報，五夜無煩侍女添。","焦首朝朝還暮暮，煎心日日復年年。","光陰荏苒須當惜，風雨陰晴任變遷。"],"白话":"谜底更香：朝罢谁带着满袖香烟，琴边被里都没缘分；不用报晓的鸡人，五更不烦侍女添；整天焦首煎心，光阴荏苒要珍惜，风雨阴晴任变迁。","串讲2":"更香谜。「焦首朝朝還暮暮，煎心日日復年年」，贾政看了，只觉小小之人作此词句，不是福寿之辈。焦首煎心，正是她嫁后守着的日子。","备注":"页面写明「七言律詩一首，卻是寶釵所作」；贾政看完觉得「此物還倒有限」，又嫌小小年纪作这样的词句更觉不祥。","校字":[{"位置":"琴邊衾里總無緣","页面":"衾里","改":"衾裡","依据":"作「内」讲的「里」改「裡」，同图鉴 codexData 文件头约定"}],"出处":"维基文库 zh-hant 第022回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆","组":"燈謎"},"zhongqiu-lian":{"题":"中秋夜大觀園即景聯句（湘雲黛玉二十二韻）","作者":["daiyu","xiangyun"],"名":"黛玉、湘云","回":76,"回目":"第七十六回　凸碧堂品笛感淒清　凹晶館聯詩悲寂寞","体":"联句","句":["三五中秋夕，清游擬上元。","撒天箕斗燦，匝地管弦繁。","幾處狂飛盞，誰家不啟軒。","輕寒風剪剪，良夜景暄暄。","爭餅嘲黃發，分瓜笑綠嬡。","香新榮玉桂，色健茂金萱。","蠟燭輝瓊宴，觥籌亂綺園。","分曹尊一令，射覆聽三宣。","骰彩紅成點，傳花鼓濫喧。","晴光搖院宇，素彩接乾坤。","賞罰無賓主，吟詩序仲昆。","構思時倚檻，擬景或依門。","酒盡情猶在，更殘樂已諼。","漸聞語笑寂，空剩雪霜痕。","階露團朝菌，庭煙斂夕棔。","秋湍瀉石髓，風葉聚雲根。","寶婺情孤潔，銀蟾氣吐吞。","藥經靈兔搗，人向廣寒奔。","犯斗邀牛女，乘槎待帝孫。","虛盈輪莫定，晦朔魄空存。","壺漏聲將涸，窗燈焰已昏。","寒塘渡鶴影，冷月葬花魂。"],"白话":"中秋夜在凹晶溪馆，黛玉起句、湘云接，二人轮流联了二十二韵：从满园管弦、分瓜射覆，一路联到秋湍、寒塘；湘云「寒塘渡鶴影」，黛玉对出「冷月葬花魂」。","串讲2":"中秋夜凹晶馆，湘云一句「寒塘渡鶴影」，黛玉对出「冷月葬花魂」。妙玉出来说过于颓败凄楚。两个没了爹娘的姑娘，在水边把一个团圆节联得这样冷。","句作者":[["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","daiyu"]],"备注":"每联两句，句作者依次是「出句 / 对句」。黛玉起「三五中秋夕」，其后湘云、黛玉轮流，每人先对上一句再出一句，最后黛玉独对「冷月葬花魂」。妙玉随后接续，见 zhongqiu-miaoyu。","出处":"维基文库 zh-hant 第076回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"zhongqiu-miaoyu":{"题":"中秋聯句續（妙玉十三韻）","作者":"miaoyu","名":"妙玉","回":76,"回目":"第七十六回　凸碧堂品笛感淒清　凹晶館聯詩悲寂寞","体":"联句","句":["香篆銷金鼎，脂冰膩玉盆。","簫增嫠婦泣，衾倩侍兒溫。","空帳懸文鳳，閒屏掩彩鴛。","露濃苔更滑，霜重竹難捫。","猶步縈紆沼，還登寂歷原。","石奇神鬼搏，木怪虎狼蹲。","贔屭朝光透，罘罳曉露屯。","振林千樹鳥，啼谷一聲猿。","歧熟焉忘徑，泉知不問源。","鐘鳴櫳翠寺，雞唱稻香村。","有興悲何繼，無愁意豈煩。","芳情只自遣，雅趣向誰言。","徹旦休雲倦，烹茶更細論。"],"白话":"妙玉出来拦住「太悲凉」，带二人回栊翠庵，提笔一挥而就续了十三韵，把联句从颓败拉回到「香篆、脂冰」的闺阁本色，结在「徹旦休雲倦，烹茶更細論」。","串讲2":"妙玉嫌二人联得太悲，自己续了十三韵，收在「徹旦休雲倦，烹茶更細論」。她要把人拉回来，自家判词却是「欲潔何曾潔」，「終陷淖泥中」（第5回）。","备注":"后书「右中秋夜大觀園即景聯句三十五韻」，湘黛二十二韵加妙玉十三韵共三十五韵。页面在她续句前先写：妙玉遂提筆一揮而就。","出处":"维基文库 zh-hant 第076回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"luxue-lianju":{"题":"蘆雪广即景聯句（雪）","作者":["xifeng","liwan","xiangling","tanchun","liqi","liwen","xiuyan","xiangyun","baoqin","daiyu","baoyu","baochai"],"名":"李纨等","回":50,"回目":"第五十回　蘆雪广爭聯即景詩　暖香塢創製春燈謎[1]","体":"联句","句":["一夜北風緊，開門雪尚飄。","入泥憐潔白，匝地惜瓊瑤。","有意榮枯草，無心飾萎苕。","價高村釀熟，年稔府粱饒。","葭動灰飛管，陽回斗轉杓。","寒山已失翠，凍浦不聞潮。","易掛疏枝柳，難堆破葉蕉。","麝煤融寶鼎，綺袖籠金貂。","光奪窗前鏡，香粘壁上椒。","斜風仍故故，清夢轉聊聊。","何處梅花笛？誰家碧玉簫？","鰲愁坤軸陷，龍鬪陣雲銷。","野岸回孤棹，吟鞭指灞橋。","賜裘憐撫戍，加絮念征徭。","坳垤審夷險，枝柯怕動搖。","皚皚輕趁步，翦翦舞隨腰。","煮芋成新賞，撒鹽是舊謠。","葦蓑猶泊釣，林斧不聞樵。","伏象千峰凸，盤蛇一徑遙。","花緣經冷聚，色豈畏霜凋。","深院驚寒雀，空山泣老鴞。","階墀隨上下，池水任浮漂。","照耀臨清曉，繽紛入永宵。","誠忘三尺冷，瑞釋九重焦。","僵臥誰相問，狂遊客喜招。","天機斷縞帶，海市失鮫綃。","寂寞對臺榭，清貧懷簞瓢。","烹茶冰漸沸，煮酒葉難燒。","沒帚山僧掃，埋琴稚子挑。","石樓閒睡鶴，錦罽暖親貓。","月窟翻銀浪，霞城隱赤標。","沁梅香可嚼，淋竹醉堪調。","或濕鴛鴦帶，時凝翡翠翹。","無風仍脈脈，不雨亦瀟瀟。","欲志今朝樂，憑詩祝舜堯。"],"白话":"雪天在芦雪庵联句，凤姐起了「一夜北风紧」，李纨接「开门雪尚飘」，随后香菱、探春、湘云、宝琴、黛玉、宝玉、宝钗、岫烟、李纹、李绮轮流联句；湘云联得最多，也最快。","串讲2":"芦雪广一场雪，凤姐一句「一夜北風緊」开了头，湘云抢得最多，宝玉落第受罚。这是大观园人最齐的一场雪，众人都在，一个也不少（第50回）。","句作者":[["xifeng","liwan"],["liwan","xiangling"],["xiangling","tanchun"],["tanchun","liqi"],["liqi","liwen"],["liwen","xiuyan"],["xiuyan","xiangyun"],["xiangyun","baoqin"],["baoqin","daiyu"],["daiyu","baoyu"],["baoyu","baochai"],["baochai","xiangyun"],["xiangyun","baoqin"],["baoqin","xiangyun"],["xiangyun","baochai"],["baochai","daiyu"],["daiyu","baoyu"],["baoyu","baoqin"],["baoqin","xiangyun"],["xiangyun","tanchun"],["tanchun","xiuyan"],["xiuyan","xiangyun"],["xiangyun","daiyu"],["daiyu","xiangyun"],["xiangyun","baoqin"],["baoqin","xiangyun"],["daiyu","xiangyun"],["baoqin","xiangyun"],["daiyu","baoqin"],["xiangyun","daiyu"],["baoqin","xiangyun"],["daiyu","baochai"],["baoqin","xiangyun"],["daiyu","baoqin"],["liwan","liqi"]],"备注":"每联两句，句作者是「出句 / 对句」。李纨自己联的是「開門雪尚飄，入泥憐潔白」两句，另在末尾补「欲志今朝樂」，李绮接「憑詩祝舜堯」收尾。全诗未用完二萧韵，是李纨喊停。","出处":"维基文库 zh-hant 第050回（解析稿 revid 与线上比对一致，2026-10 取）；Sonnet 逐字取，未凭记忆"},"yucun-wulv":{"题":"中秋有懷（未卜三生願）","作者":"jiayucun","名":"贾雨村","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["未卜三生願，頻添一段愁。","悶來時斂額，行去幾回頭。","自顧風前影，誰堪月下儔？","蟾光如有意，先上玉人樓。"],"白话":"三生之愿还卜不定，愁绪却频频添了一段。烦闷时皱着眉，走开后又几番回头。自顾风前孤影，月下有谁堪与为伴？月光若真有意，就先照上那玉人的楼。","串讲2":"第一回中秋，雨村自认甄家丫鬟娇杏回顾是有意，时刻放在心上，遂对月口占此律。风前影、月下俦，皆孤身未遇之叹。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"原无题，按书中情境拟题","拟题":true},"yucun-yilian":{"题":"雨村吟對聯（玉在匵中）","作者":"jiayucun","名":"贾雨村","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["玉在匵中求善價，釵於奩內待時飛。"],"白话":"美玉盛在匣中，等待识货的好价钱；金钗藏在妆奁里，等待时机腾飞。","串讲2":"第一回，雨村吟罢怀人诗，又思平生抱负，苦未逢时，遂高吟此联。玉钗藏器，待价而飞，士隐听了便笑他抱负不浅。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，拟题","拟题":true},"yucun-zhongqiu":{"题":"中秋對月寓懷（時逢三五）","作者":"jiayucun","名":"贾雨村","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["時逢三五便團圓，滿把晴光護玉欄。","天上一輪才捧出，人間萬姓仰頭看。"],"白话":"时逢十五便团圆，满把清光护着白玉栏杆。天上这一轮才捧出来，人间万姓都抬头看。","串讲2":"第一回中秋，士隐邀雨村至家赏月，雨村席上吟此。借月自况，士隐听了便道他飞腾之兆已见，随即赠银助他赴考。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"原无题，拟题","拟题":true,"异文":["「團圓」程乙本作「團圞」","「晴光」程乙本作「清光」（另有校对稿称程甲同，未核）"]},"haoliao-ge":{"题":"好了歌","作者":"bozudaoren","名":"跛足道人","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["世人都曉神仙好，惟有功名忘不了；古今將相在何方，荒冢一堆草沒了。","世人都曉神仙好，只有金銀忘不了；終朝只恨聚無多，及到多時眼閉了。","世人都曉神仙好，只有嬌妻忘不了；君生日日說恩情，君死又隨人去了。","世人都曉神仙好，只有兒孫忘不了；痴心父母古來多，孝順子孫誰見了。"],"白话":"世人都晓神仙好，惟有功名、金银、娇妻、儿孙忘不了：将相已无踪影，只剩荒坟野草；金银终日嫌少，攒够时眼已闭上；娇妻生前说恩情，死后随人去；痴心父母多，孝顺子孙少。","串讲2":"第一回，甄士隐贫病之中拄杖出门，听见跛足道人唱这四段。功名、金银、娇妻、儿孙，世人样样舍不得，歌里随即写出它们终究成空。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"歌","异文":["「嬌妻」程乙本作「姣妻」","疑点（未能核实）：另有校对稿都称庚辰本作「姣妻」「孝順兒孫」；底本及程乙本均作「孝順子孫」"],"待核":"「孝順子孫」「嬌妻」：另有校对稿都称庚辰本作「兒孫」「姣妻」，而底本与程乙本均为「子孫」（程乙「姣妻」），底本该处可能掺入程本写法；无庚辰影印本，无法判断"},"haoliao-zhu":{"题":"好了歌解注","作者":"zhenshiyin","名":"甄士隐","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["陋室空堂、當年笏滿床，衰草枯楊、曾為歌舞場；蛛絲兒結滿雕梁，綠紗今又糊在蓬窗上。","說什麼脂正濃、粉正香，如何兩鬢又成霜；昨日黃土隴頭送白骨，今宵紅燈帳底臥鴛鴦。","金滿箱、銀滿箱，轉眼乞丐人皆謗；正嘆他人命不長，那知自己歸來喪。","訓有方，保不定日後作強梁；擇膏粱，誰承望流落在煙花巷。","因嫌紗帽小，致使鎖枷扛；昨憐破襖寒，今嫌紫蟒長。","亂哄哄你方唱罷我登場，反認他鄉是故鄉；甚荒唐，到頭來都是為他人作嫁衣裳。"],"白话":"陋室空堂，当年却是笏板堆满床；衰草枯杨，也曾是歌舞场。蛛丝结满雕梁，绿纱如今又糊在蓬窗上。说什么脂正浓、粉正香，两鬓怎么就白成了霜；昨日才在黄土陇头送走白骨，今宵红灯帐里又卧着鸳鸯。金满箱，银满箱，转眼成乞丐，落得人人骂；正叹别人命不长，哪知自己回来也丧了命。教训得再有方，保不定日后去做强盗；择了富贵人家，谁料得到会流落烟花巷。嫌乌纱太小，致使锁枷扛；昨日还怜破袄冷，今日又嫌紫蟒长。乱哄哄，你方唱罢我登场，反把他乡认作故乡。荒唐啊，到头来都是为他人作嫁衣裳。","串讲2":"第一回末，甄士隐贫病交攻，遇见跛足道人唱「好了歌」，当即口占此注。通篇盛与衰、聚与散两两相对，是替那首歌作解。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"歌","异文":["「說什麼脂正濃」程乙本作「說甚麼脂正濃」","「隴頭送白骨」程乙本作「隴頭埋白骨」","「紅燈帳底」程乙本作「紅綃帳底」","「亂哄哄」程乙本作「亂烘烘」","疑点（未能核实）：另有校对稿疑庚辰本作「展眼乞丐人皆謗」；底本及程乙本均作「轉眼」"],"待核":"「轉眼乞丐人皆謗」：另有校对稿疑庚辰本作「展眼」，底本与程乙本均作「轉眼」；无庚辰影印本，无法判断"},"seng-jie":{"题":"癩頭僧誡英蓮偈（慣養嬌生笑你痴）","作者":"yiseng","名":"一僧（癞头和尚）","回":1,"回目":"甄士隱夢幻識通靈 賈雨村風塵懷閨秀","句":["慣養嬌生笑你痴，菱花空對雪澌澌。","好防佳節元宵後，便是煙消火滅時！"],"白话":"娇生惯养，可笑你这个做父亲的太痴；菱花空对着澌澌的雪。要提防元宵佳节一过，便是烟消火灭之时。","串讲2":"癞头僧到士隐门前，见他抱着英莲，便指着他念了这四句。前两句笑父母娇养之痴，菱花指日后的香菱，雪谐薛蟠。元宵英莲走失，三月十五庙火又烧了甄家。","出处":"第1回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"偈","备注":"原无题，拟题","拟题":true},"keqing-lingbie":{"题":"秦可卿臨別贈鳳姐語（三春過後）","作者":"qinkeqing","名":"秦可卿","回":13,"回目":"秦可卿死封龍禁尉 王熙鳳協理寧國府","句":["三春過後諸芳盡，各自須尋各自門。"],"白话":"春光过去，众花都将凋尽；到那时，各人都须各自寻找归宿。","串讲2":"秦可卿在凤姐梦中临别赠此二句，以春尽花残预示盛景消散、众人离散，承接她劝凤姐及早筹划家族退路的话。","出处":"第13回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，拟题；托梦所念两句","拟题":true},"baoyu-qinfang-lian":{"题":"沁芳亭聯","作者":"baoyu","名":"宝玉","回":17,"回目":"會芳園試才題對額 賈寶玉機敏動諸賓","句":["繞堤柳借三篙翠，隔岸花分一脈香。"],"白话":"绕堤的柳树，把翠色映入深深的水中；隔岸的鲜花，把芳香分给这一脉流水。","串讲2":"这是宝玉随贾政游新园时，为沁芳亭所题的对联。他借柳与花、翠与香写亭子四周的水色花香，紧扣「沁芳」二字，见其才思敏捷。","出处":"第17回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，据上文「沁芳」亭联拟题","拟题":true,"组":"賈政試才題對額"},"baoyu-xiaoxiang-lian":{"题":"瀟湘館聯","作者":"baoyu","名":"宝玉","回":17,"回目":"會芳園試才題對額 賈寶玉機敏動諸賓","句":["寶鼎茶閒煙尚綠，幽窗棋罷指猶涼。"],"白话":"饮茶歇下，鼎形香炉里仍有带着绿意的轻烟；幽静窗下，棋局虽已结束，指尖还留着清凉。","串讲2":"这是宝玉为后来名为潇湘馆的住处所题的对联。茶闲烟绿，棋罢指凉，以视觉和触觉写出竹院的清幽闲雅。","出处":"第17回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，拟题","拟题":true,"组":"賈政試才題對額"},"baoyu-daoxiang-lian":{"题":"稻香村聯","作者":"baoyu","名":"宝玉","回":17,"回目":"會芳園試才題對額 賈寶玉機敏動諸賓","句":["新漲綠添浣葛處，好雲香護採芹人。"],"白话":"新涨的水给洗葛布的地方添上绿意；美好的云气仿佛带着芳香，笼罩着采芹求学的人。","串讲2":"这是宝玉为稻香村题的对联。浣葛、采芹都从《诗经》取意，写水绿云香、农家耕读之乐，正合村名。","出处":"第17回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，拟题","拟题":true,"组":"賈政試才題對額"},"baoyu-hengwu-lian":{"题":"蘅蕪院聯","作者":"baoyu","名":"宝玉","回":17,"回目":"會芳園試才題對額 賈寶玉機敏動諸賓","句":["吟成荳蔻才猶艷，睡足酴醾夢也香。"],"白话":"吟成咏豆蔻的诗篇，文才仍显得绮丽；在荼蘼花香中睡足，连梦也带着芳香。","串讲2":"第17回宝玉随父游园题对，为蘅蕪院拟此联。上句夸才思艳丽，下句写花下酣眠，暗合院中香草繁盛、清幽宜人之境。","出处":"第17回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"原无题，拟题","拟题":true,"组":"賈政試才題對額"},"yuanchun-yinglian":{"题":"省親別墅聯（天地啟宏慈）","作者":"yuanchun","名":"元春","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["天地啟宏慈，赤子蒼頭同感戴，","古今垂曠典，九州萬國被恩榮。"],"白话":"皇恩如天地般广大，开启宏大的仁慈，百姓与仆役都感恩戴德；朝廷颁下古今罕见的盛大恩典，天下各地都蒙受恩泽与荣耀。","串讲2":"元春省亲时为正殿题此联，借天地的广大赞颂皇恩，以各色人等和天下各地共同蒙恩，颂扬准许省亲的盛典。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"元春命题的正殿联；原无题，拟题","拟题":true,"组":"省親別墅題詠"},"yuanchun-ti-daguanyuan":{"题":"題大觀園","作者":"yuanchun","名":"元春","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["銜山抱水建來精，多少工夫築始成。","天上人間諸景備，芳園應錫大觀名。"],"白话":"这园子衔着山、抱着水，建造得十分精巧，不知花了多少工夫才建成。天上人间的种种景致都齐备了，这美好的园子理应赐名「大观」。","串讲2":"第18回元春归省，题罢匾联又题此绝。首二句赞园景精巧、工程浩大，后二句以「天上人間」总收，点出「大观」之名，是皇妃为省亲别墅定名之笔。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"原文「先題一絕」，无题名，「題大觀園」为通行叫法","组":"省親別墅題詠"},"yingchun-kuangxing":{"题":"曠性怡情","作者":"yingchun","名":"迎春","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["園成景備特精奇，奉命羞題額曠怡。","誰信世間有此境，游來寧不暢神思？"],"白话":"园子建成，景致齐备，格外精妙奇特；奉命题匾，我惭愧地写下「旷性怡情」。谁能相信世间竟有这样的境地，来游赏怎不令人神思畅快？","串讲2":"第18回元春命众人各题一匾一诗，迎春题「旷性怡情」。前两句赞园景精奇，并以「羞题」表示谦退；后两句连用反问，写游赏时的惊叹与畅快。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「曠性怡情」","异文":["「景備特精奇」程乙本作「景物特精奇」"],"组":"省親別墅題詠"},"tanchun-wanxiang":{"题":"萬象爭輝","作者":"tanchun","名":"探春","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["名園築出勢巍巍，奉命何慚學淺微。","精妙一時言不出，果然萬物生光輝。"],"白话":"名园建成，气势雄伟；奉命题咏，我自谦学识浅薄。园中的精妙一时难以说尽，眼前万物果然都焕发着光辉。","串讲2":"第18回元春命众人各题一匾一诗，探春题「万象争辉」。首句赞园势雄伟，次句自谦学识浅薄，末两句写精妙难以尽言、万物焕发光辉，照应匾额。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「萬象爭輝」","异文":["「築出勢巍巍」程乙本作「築就勢巍巍」","「何慚學淺微」程乙本作「多慚學淺微」","「言不出」程乙本作「言不盡」","「萬物生光輝」程乙本作「萬物有光輝」"],"组":"省親別墅題詠"},"xichun-wenzhang":{"题":"文章造化","作者":"xichun","名":"惜春","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["山水橫拖千里外，樓臺高起五雲中。","園修日月光輝里，景奪文章造化功。"],"白话":"山水横展，仿佛延伸到千里之外；楼台高耸，仿佛直入五色祥云之中。园林建在日月光辉照耀之下，景致之美仿佛胜过天地造化的天然文采。","串讲2":"第18回元春省亲，惜春奉命题「文章造化」。前两句夸写山水辽阔、楼台高耸，后两句以日月光辉和天地造化赞园景，带有颂扬意味。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「文章造化」","组":"省親別墅題詠"},"liwan-wencai":{"题":"文采風流","作者":"liwan","名":"李纨","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["秀水明山抱復回，風流文采勝蓬萊。","綠裁歌扇迷芳草，紅襯湘裙舞落梅。","珠玉自應傳盛世，神仙何幸下瑤臺。","名園一自邀游賞，未許凡人到此來。"],"白话":"秀美的山水环抱回绕，园林的风采胜过蓬莱仙山。绿扇与芳草相映，令人眼花；红花映衬着华美的裙子，舞动时仿佛落梅纷飞。精美的题咏自当传颂盛世，我们多么有幸，迎来神仙般的贵妃从瑶台降临。自从名园迎来贵妃游赏，这里便仿佛成了凡人难以到达的仙境。","串讲2":"第18回李纨奉命题「文采风流」。诗以山水与歌舞意象铺写园景，以珠玉比题咏、神仙比元春，末联将名园写成凡人难至的仙境，表达赞颂。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「文采風流」","组":"省親別墅題詠"},"baochai-ningxi":{"题":"凝暉鍾瑞","作者":"baochai","名":"宝钗","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["芳園築向帝城西，華日祥雲籠罩奇。","高柳喜遷鶯出谷，修篁時待鳳來儀。","文風已著宸游夕，孝化應隆歸省時。","睿藻仙才盈彩筆，自慚何敢再為辭。"],"白话":"美好的园林建在帝都西边，灿烂的日光与祥瑞云气笼罩着奇丽的景致。高柳喜迎黄莺飞出幽谷，修长的翠竹时时等待凤凰来临。元春省亲的这一夜，崇尚文学的风气已经彰显；她归家探亲，也当使孝道教化更加兴盛。元春的聪慧文辞与非凡才华尽显于笔端，我自觉才学不足，哪里还敢再作诗文。","串讲2":"第18回宝钗题「凝晖钟瑞」。诗借莺迁、凤至的意象颂扬元春的尊荣与省亲，又赞文风、孝化；末联称美元春才华，自谦不敢再作诗文。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「凝暉鐘瑞」，书中「鐘」，通行本或作「鍾」","异文":["「仙才盈彩筆」程乙本作「仙才瞻仰處」"],"组":"省親別墅題詠"},"daiyu-shiwai":{"题":"世外仙源","作者":"daiyu","名":"黛玉","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["名園築何處，仙境別紅塵。","借得山川秀，添來景物新。","香融金谷酒，花媚玉堂人。","何幸邀恩寵，宮車過往頻。"],"白话":"名园建在何处？这里宛如远离尘世的仙境。借来山川的秀美，又添上新巧的景物。花香与金谷园般的宴饮酒香交融，花色映衬着华堂中人的风采。何其有幸得到皇恩眷顾，愿宫车常来临幸。","串讲2":"第十八回黛玉题「世外仙源」。她本欲大展奇才压众，却只得胡乱作一首应景；「仙境别红尘」写园之清幽，「金谷」「玉堂」颂省亲之盛，语简而意足。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"匾额题名「世外仙源」","异文":["「添來景物新」程乙本作「添來氣象新」"],"组":"省親別墅題詠"},"baoyu-youfeng":{"题":"有鳳來儀","作者":"baoyu","名":"宝玉","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["秀玉初成實，堪宜待鳳凰。","竿竿青欲滴，個個綠生涼。","迸砌妨階水，穿簾礙鼎香。","莫搖清碎影，好夢晝初長。"],"白话":"秀美的竹子刚结出竹实，正适合等待凤凰来栖。根根竹竿青翠欲滴，片片竹叶绿得令人感到清凉。竹笋冲出台阶，阻碍阶边的流水；竹枝伸进帘内，挡住香炉飘出的烟气。不要摇动清疏细碎的竹影，白日里的好梦才渐渐悠长。","串讲2":"第十八回宝玉题「有凤来仪」。诗以竹实待凤凰呼应匾额，并寄寓迎接元春的颂意；继写竹色、凉意与枝笋，末联转入惜梦，意境清幽。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「妨階水」程乙本作「防階水」","「清碎影」程乙本作「分碎影」","「好夢晝初長」程乙本作「好夢正初長」"],"组":"省親別墅題詠"},"baoyu-hengzhi":{"题":"蘅芷清芬","作者":"baoyu","名":"宝玉","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["蘅蕪滿淨苑，蘿薜助芬芳。","軟襯三春草，柔拖一縷香。","輕煙迷曲徑，冷翠滴迴廊。","誰謂池塘曲，謝家幽夢長。"],"白话":"蘅芜香草长满清幽的园苑，女萝、薜荔相伴，更添芳意。香草柔软地衬着春天的绿草，藤蔓轻柔地拖曳，散出一缕清香。轻烟笼罩曲折的小径，清冷的翠色浓得仿佛要滴落回廊。眼前景色令人想起咏池塘春草的诗句，也想起谢家那悠长的幽梦。","串讲2":"第十八回元春省亲，命众人题咏大观园。宝玉为蘅芜苑作此五律，以香草、轻烟、冷翠写清幽景色，末联借谢灵运梦中得句的典故收束。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「滿淨苑」程乙本作「滿靜苑」","「冷翠滴迴廊」程乙本作「冷翠溼衣裳」"],"组":"省親別墅題詠"},"baoyu-yihong":{"题":"怡紅快綠","作者":"baoyu","名":"宝玉","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["深庭長日靜，兩兩出嬋娟。","綠蠟春猶卷，紅妝夜未眠。","憑欄垂絳袖，倚石護青煙。","對立東風里，主人應解憐。"],"白话":"深深的庭院里，漫长的白日一片宁静，芭蕉与海棠像两位美人相对而立。绿蜡般的芭蕉叶在春日仍然卷着，红妆般的海棠夜里还未入眠。海棠仿佛凭着栏杆垂下深红衣袖，芭蕉仿佛倚着山石护住青烟般的绿意。它们迎着东风相对而立，主人应当懂得怜爱。","串讲2":"第十八回题咏大观园，宝玉为怡红院作此诗。原句「绿玉春犹卷」，宝钗提醒贵人已改「红香绿玉」之题，遂改「绿玉」为「绿蜡」。芭蕉海棠一对，正是院中本色。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"宝钗提点「綠蠟」不「紅香綠玉」之典","组":"省親別墅題詠"},"daiyu-xinglian":{"题":"杏簾在望","作者":"daiyu","名":"黛玉","回":18,"回目":"林黛玉誤剪香囊袋 賈元春歸省慶元宵","句":["杏簾招客飲，在望有山莊。","菱荇鵝兒水，桑榆燕子梁。","一畦春韭綠，十里稻花香。","盛世無饑餒，何須耕織忙。"],"白话":"杏黄色的酒旗招引客人来饮酒，远远望去，山庄就在眼前。长着菱和荇菜的水中有鹅儿游动，桑树、榆树掩映的屋舍梁间有燕子栖息。一畦春韭碧绿，十里稻花飘香。诗中称颂盛世没有饥饿之忧，何须再为生计忙于耕织。","串讲2":"第十八回题咏大观园，此首署宝玉之名，实出黛玉代作，由宝玉誊上。写稻香村田家景致，末联颂圣。元春看后，独指此首为四诗之冠。","出处":"第18回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"书中为黛玉代宝玉所作，由宝玉誊上；作者记黛玉","组":"省親別墅題詠"},"baoyu-xu-zhuangzi":{"题":"續《南華經·胠篋》","作者":"baoyu","名":"宝玉","回":21,"回目":"賢襲人嬌嗔箴寶玉 俏平兒軟語救賈璉","句":["焚花散麝，而閨閣始人含其勸矣，戕寶釵之仙姿，灰黛玉之靈竅，喪減情意，而閨閣之美惡始相類矣。彼含其勸，則無參商之虞矣，戕其仙姿，無戀愛之心矣，灰其靈竅，無才思之情矣。彼釵，玉，花，麝者，皆張其羅而穴其隧，所以迷眩纏陷天下者也。"],"白话":"毁去袭人，遣散麝月，闺阁中的人才会把规劝的话收住；摧毁宝钗的美貌，泯灭黛玉的聪慧，消减情意，闺阁中人的美丑才会变得一样。收住规劝，就没有彼此不和的忧虑；摧毁美貌，就不会生出爱恋之心；泯灭聪慧，就不会因才思而动情。宝钗、黛玉、袭人、麝月这些人，都像张开罗网、挖出诱人的洞穴通道，用来迷惑、缠住天下人的。","串讲2":"第二十一回，宝玉与袭人、麝月等闹了别扭，心绪烦乱，便取《南华经·胠篋》来读，提笔续了一段。他把花、麝、钗、玉都看作缠陷人的罗网，是少年一时负气之语，并非真悟。","出处":"第21回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"文","备注":"宝玉醉后续庄子的骈文，文体不是诗，按「作品」收；原无题，拟题","拟题":true,"异文":["「喪減情意」程乙本作「喪滅情意」","「穴其隧」程乙本作「邃其穴」","「迷眩纏陷」程乙本作「迷惑纏陷」"]},"daiyu-ti-xuzhuang":{"题":"題續《莊子》","作者":"daiyu","名":"黛玉","回":21,"回目":"賢襲人嬌嗔箴寶玉 俏平兒軟語救賈璉","句":["無端弄筆是何人？作踐南華《莊子因》。","不悔自己無見識，卻將丑語怪他人！"],"白话":"是谁无缘无故地提笔乱写，糟蹋了《南华经》和《庄子因》？不反省自己没有见识，反倒用难听的话责怪别人！","串讲2":"第二十一回，黛玉趁宝玉不在时翻看案上书，读到他续写的《庄子》，又气又笑，便题诗讥讽他不反省自己，反而怪罪别人。","出处":"第21回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"黛玉看到宝玉续书后所题绝句；原无题，拟题","拟题":true,"异文":["「作踐南華《莊子因》」程乙本作「剿襲南華莊子文」","「自己無見識」程乙本作「自家無見識」","「丑語怪他人」程乙本作「醜語詆他人」"]},"baoyu-ji":{"题":"寶玉參禪偈","作者":"baoyu","名":"宝玉","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["你證我證，心證意證。","是無有證，斯可雲證。","無可雲證，是立足境。"],"白话":"你参证，我也参证，心在参证，意也在参证。到了没有什么可参证的境界，这才能称作参证。既然没有什么可参证，那便是安身立命的境界了。","串讲2":"第二十二回，宝玉调解黛玉与湘云的矛盾不成，反受双方责备，回房感忿写偈，借禅语求解脱。次日黛玉续上「无立足境，是方干净」，指出他仍有执着。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"偈","备注":"原无题，拟题","拟题":true},"baoyu-jishengcao":{"题":"寄生草","作者":"baoyu","名":"宝玉","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["無我原非你，從他不解伊。","肆行無礙憑來去。","茫茫著甚悲愁喜，紛紛說甚親疏密。","從前碌碌卻因何，到如今回頭試想真無趣！"],"白话":"没有我，也就无所谓与你相对的你；任凭别人不理解，又何必管呢。随心而行，无牵无碍，任凭来去。人生茫茫，何必悲伤、忧愁、欢喜；人事纷纷，还讲什么亲近疏远。从前忙忙碌碌究竟为了什么？到如今回头细想，真是无趣！","串讲2":"二十二回，宝玉写罢参禅偈，又填此曲。曲中「肆行无碍」是他向往的自在，「真无趣」却是实情。夹在黛玉、湘云间受了委屈，借禅语自宽，到底还是少年心事。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲"},"dengmi-yuanchun":{"题":"燈謎（爆竹）","作者":"yuanchun","名":"元春","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["能使妖魔膽盡摧，身如束帛氣如雷。","一聲震得人方恐，回首相看已化灰。"],"白话":"能让妖魔都吓破了胆，身子像捆紧的绢帛，气势却响如雷霆。一声爆响，震得人正在惊怕，回头再看时，它早已化作了一堆灰烬。","串讲2":"二十二回元宵，元春自宫中传出灯谜与众姊妹同乐。爆竹一声震响旋即成灰，写物之中藏着盛极而衰的意味，读来令人心惊。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","组":"燈謎"},"dengmi-jiahuan":{"题":"燈謎（枕頭與獸頭）","作者":"jiahuan","名":"贾环","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["大哥有角只八個，二哥有角只兩根。","大哥只在床上坐，二哥愛在房上蹲。"],"白话":"大哥头上只有八个角，二哥头上只有两根角。大哥只肯在床上坐着，二哥却爱蹲在房顶上。","串讲2":"第二十二回，贾环所作灯谜送入宫中，元春未猜出，命太监带回询问。众人看后大笑，贾环只得说明谜底是枕头和兽头。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","组":"燈謎"},"dengmi-jiazheng-lizhi":{"题":"燈謎（荔枝）","作者":"jiazheng","名":"贾政","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["猴子身輕站樹梢。","——打一果名。"],"白话":"猴子身子轻巧，稳稳站在树的梢头。——打一种果子的名字。","串讲2":"第二十二回，贾母说此谜让贾政猜。猴子站在枝上，可说「立枝」，「立」与「荔」谐音，扣「荔枝」。贾政早已猜中，却故意猜错几次，逗贾母高兴。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","组":"燈謎"},"dengmi-jiazheng-yan":{"题":"燈謎（硯臺）","作者":"jiazheng","名":"贾政","回":22,"回目":"聽曲文寶玉悟禪機 製燈迷賈政悲讖語","句":["身自端方，體自堅硬。","雖不能言，有言必應。","——打一用物。"],"白话":"这件器物形体端正，质地坚硬；虽然不能说话，却能供墨给笔，让人把要说的话写出来。谜底是砚台。","串讲2":"第二十二回贾府猜灯谜，贾政出此谜让贾母猜。前句写砚台的形质，后句借供墨助笔的用途设谜；宝玉暗中传达谜底，贾母猜中。","出处":"第22回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","组":"燈謎"},"laitou-shi-1":{"题":"僧誦通靈寶玉詩（天不拘兮）","作者":"laitouheshang","名":"癞头和尚","回":25,"回目":"魘魔法姊弟逢五鬼 紅樓夢通靈遇雙真","句":["天不拘兮地不羈，心頭無喜亦無悲，","卻因鍛煉通靈後，便向人間覓是非。"],"白话":"你本不受天地的拘管束缚，心里既没有欢喜也没有悲伤；只因经过锻炼、通了灵性之后，便要到人间去寻是非、惹牵挂。","串讲2":"第二十五回宝玉、凤姐遭魇魔法，癞头和尚接过通灵宝玉，念诗追说它昔日的自在与后来的入世经历，以无喜无悲对照尘世纷扰。","出处":"第25回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"原无题，拟题","拟题":true,"异文":["「卻因鍛煉通靈後」程乙本作「只因鍛鍊通靈後」","「覓是非」程乙本作「惹是非」"]},"laitou-shi-2":{"题":"僧誦通靈寶玉詩（粉漬脂痕）","作者":"laitouheshang","名":"癞头和尚","回":25,"回目":"魘魔法姊弟逢五鬼 紅樓夢通靈遇雙真","句":["粉漬脂痕污寶光，綺櫳晝夜困鴛鴦。","沉酣一夢終須醒，冤孽償清好散場！"],"白话":"香粉胭脂的痕迹污损了宝玉的光华；华美的闺阁里，鸳鸯般的有情者日夜受着拘困。沉醉的梦终究要醒，等冤孽之债偿清，也就该散场了！","串讲2":"第二十五回癞头和尚对通灵宝玉念此诗。前两句借脂粉与闺阁写情爱牵缠，后两句以梦醒、偿债、散场，警示尘缘终有尽时。","出处":"第25回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"原无题，拟题","拟题":true,"异文":["「綺櫳晝夜困鴛鴦」程乙本作「房櫳日夜困鴛鴦」","「冤孽償清」程乙本作「冤債償清」"]},"jiuling-baoyu":{"题":"女兒悲愁喜樂（寶玉酒令）","作者":"baoyu","名":"宝玉","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["女兒悲，青春已大守空閨。","女兒愁，悔教夫婿覓封侯。","女兒喜，對鏡晨妝顏色美。","女兒樂，鞦韆架上春衫薄。"],"白话":"女儿悲伤，是年岁渐长，仍独守空闺；女儿发愁，是后悔让丈夫去求取功名；女儿欢喜，是清晨对镜梳妆，容颜美丽；女儿快乐，是穿着轻薄的春衫荡秋千。","串讲2":"第28回冯紫英席上行女儿酒令，宝玉按悲愁喜乐各作一句。前2句写闺中女子的寂寞与悔怨，后2句写晨妆之美、秋千之乐，一悲一乐，正是他平日体贴女儿、怜惜女儿的心肠。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"酒令","组":"女兒酒令"},"hongdou-qu":{"题":"紅豆曲","作者":"baoyu","名":"宝玉","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["滴不盡相思血淚拋紅豆，開不完春柳春花滿畫樓。","睡不穩紗窗風雨黃昏後，忘不了新愁與舊愁。","咽不下玉粒金蓴噎滿喉，照不見菱花鏡裡形容瘦。","展不開的眉頭，捱不明的更漏。","呀，恰便似遮不住的青山隱隱，流不斷的綠水悠悠。"],"白话":"相思的血泪像红豆般抛落，怎么也滴不尽；春柳春花铺满华美的楼阁，春花仿佛总也开不完。黄昏后风雨阵阵，在纱窗内怎么也睡不安稳；新愁旧愁，怎么也忘不掉。精美的饭菜咽不下，像堵满了喉咙；对着菱花镜，却照不见自己消瘦的模样。眉头怎么也舒展不开，长夜怎么也熬不到天亮。呀，这相思正像遮不住的隐隐青山、流不断的悠悠绿水。","串讲2":"第二十八回宝玉在冯紫英席上行令，以此曲作酒面。「滴不尽」「忘不了」等句式反复铺陈相思之苦，最后借青山绿水写愁绪绵延。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「玉粒金蓴」程乙本作「玉粒金波」","「照不見菱花」程乙本作「照不盡菱花」"],"组":"女兒酒令"},"jiuling-fengziying":{"题":"女兒悲愁喜樂（馮紫英酒令）","作者":"fengziying","名":"冯紫英","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["女兒悲，兒夫染病在垂危。","女兒愁，大風吹倒梳妝樓。","女兒喜，頭胎養了雙生子。","女兒樂，私向花園掏蟋蟀。"],"白话":"女儿悲伤，是丈夫染病，命在垂危。女儿发愁，是大风吹倒了梳妆楼。女儿欢喜，是头胎生下了一对双胞胎。女儿快乐，是偷偷溜进花园里去掏蟋蟀。","串讲2":"第二十八回冯紫英设席，众人行令取乐。四句各说女儿一悲一愁一喜一乐，直白粗率，是武家子弟席上的凑趣，末句掏蟋蟀更添顽笑。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"酒令","组":"女兒酒令"},"qu-fengziying":{"题":"酒曲（你是個可人）","作者":"fengziying","名":"冯紫英","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["你是個可人，你是個多情，你是個刁鑽古怪鬼靈精，你是個神仙也不靈。","我說的話兒你全不信，只叫你去背地裡細打聽，才知道我疼你不疼！"],"白话":"你是个可心的人，你是个多情的人，你是个刁钻古怪的鬼灵精，就连神仙也拿你没法子。我说的话你全不信，只管叫你背地里细细打听去，那时才知道我疼你不疼你！","串讲2":"第二十八回冯紫英席上唱的时新曲子，连用四个「你是个」夸那女儿，末句赌气叫她背地里打听，是席上凑趣的情歌，唱得直白热辣。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","备注":"原无题，拟题","拟题":true,"组":"女兒酒令"},"jiuling-yuner":{"题":"女兒悲愁喜樂（雲兒酒令）","作者":"yuner","名":"云儿","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["女兒悲，將來終身指靠誰？","女兒愁，媽媽打罵何時休！","女兒喜，情郎不舍還家裡。女兒樂，住了簫管弄弦索。"],"白话":"女儿悲伤，是将来终身依靠谁呢？女儿发愁，是妈妈的打骂何时才有个完！女儿欢喜，是情郎舍不得她，不肯回家去。女儿快乐，是放下了箫管，又拨弄起弦索来。","串讲2":"第二十八回云儿在冯紫英席上行令。前两句忧终身无靠、受妈妈打骂，后两句写情郎留恋、停管弄弦；悲欢的内容贴合她的行院身份。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"酒令","异文":["「終身指靠誰」程乙本作「終身倚靠誰」"],"组":"女兒酒令"},"qu-yuner":{"题":"酒曲（荳蔻開花）","作者":"yuner","名":"云儿","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["荳蔻開花三月三，一個蟲兒往裡鑽。","鑽了半日不得進去，爬到花兒上打鞦韆。","肉兒小心肝，我不開了你怎麼鑽？"],"白话":"豆蔻花在三月三这天开了，一个虫儿直往花心里钻。钻了半天也钻不进去，便爬到花上打起秋千来。心肝肉儿呀，我不把花瓣儿张开，你可怎么钻得进去？","串讲2":"第二十八回云儿席上行令时所唱的小曲。借豆蔻开花、虫儿钻花暗指男女情事，末句以亲昵的反问点明双关，口吻直露而带调笑。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","备注":"原无题，拟题","拟题":true,"异文":["「荳蔻開花三月三」程乙本作「荳蔻花開三月三」","「鑽了半日不得進去」程乙本作「鑽了半日，鑽不進去」"],"组":"女兒酒令"},"qu-yuner-2":{"题":"酒曲（兩個冤家）","作者":"yuner","名":"云儿","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["兩個冤家，都難丟下，想著你來又記掛著他。","兩個人形容俊俏，都難描畫。","想昨宵幽期私訂在荼縻架，一個偷情，一個尋拿，拿住了三曹對案，我也無回話。"],"白话":"两个冤家，哪一个都舍不得丢下，想着你又惦记着他。这两个人都生得俊俏，模样儿实在描画不出来。想起昨夜在荼蘼架下偷偷约好相会，一个来偷情，一个来捉拿，把我拿住了要三曹对案，我也无话可说。","串讲2":"第二十八回，薛蟠索唱新曲，云儿弹琵琶唱此曲。曲中人难舍两个情人，又叙花架下私会被撞破、三方面对质时无言辩解的窘态。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","备注":"原无题，拟题","拟题":true,"异文":["「又記掛著他」程乙本作「又惦記著他」"],"组":"女兒酒令"},"jiuling-jiangyuhan":{"题":"女兒悲愁喜樂（蔣玉菡酒令）","作者":"jiangyuhan","名":"蒋玉菡","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["女兒悲，丈夫一去不回歸。","女兒愁，無錢去打桂花油。","女兒喜，燈花並頭結雙蕊。","女兒樂，夫唱婦隨真和合。"],"白话":"女儿悲伤，是丈夫一去不回来；女儿忧愁，是没钱去买桂花油；女儿欢喜，是灯花结成并头双蕊；女儿快乐，是夫唱妇随，真正和美。","串讲2":"第二十八回蒋玉菡在冯紫英席上行令。四句分别写丈夫不归、无钱买发油的悲愁，以及灯花报喜、夫妻和合的喜乐，语言浅白，取材家常。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"酒令","组":"女兒酒令"},"qu-jiangyuhan":{"题":"酒曲（可喜你天生成百媚嬌）","作者":"jiangyuhan","名":"蒋玉菡","回":28,"回目":"蔣玉菡情贈茜香羅 薛寶釵羞籠紅麝串","句":["可喜你天生成百媚嬌，恰便似活神仙離碧霄。","度青春，年正小；配鸞鳳，真也著。","呀！","看天河正高，聽譙樓鼓敲，剔銀燈同入鴛幃悄。"],"白话":"可喜你天生千娇百媚，恰像神仙离开碧空来到人间。正值青春年少，结成夫妻，真是相配。呀！看银河高悬，听城楼上报时的鼓声敲响，挑亮银灯，一同悄悄走入鸳鸯帐。","串讲2":"第二十八回蒋玉菡席上所唱小曲。先赞女子娇媚如仙、青春年少，继写鸾凤相配，末以银河、谯鼓、银灯铺写夜间同入鸳帏的情景。","出处":"第28回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","备注":"原无题，拟题","拟题":true,"异文":["「百媚嬌」程乙本作「百媚姣」","「真也著」程乙本作「真也巧呀」"],"组":"女兒酒令"},"pangxie-baoyu":{"题":"螃蟹詠（寶玉）","作者":"baoyu","名":"宝玉","回":38,"回目":"林瀟湘魁奪菊花詩 薛蘅蕪諷和螃蟹詠","句":["持螯更喜桂陰涼，潑醋擂薑興欲狂。","饕餮王孫應有酒，橫行公子卻無腸。","臍間積冷饞忘忌，指上沾腥洗尚香。","原為世人美口腹，坡仙曾笑一生忙。"],"白话":"手持蟹螯，更爱桂花树下的阴凉；泼醋擂姜，兴致几乎发狂。贪吃的王孙该有酒相伴，横行的公子却没有肚肠。蟹脐积冷，贪馋也忘了禁忌；手指沾腥，洗过还留着香。它原是为世人满足口腹，苏东坡曾笑自己一生为嘴忙。","串讲2":"第38回藕香榭螃蟹宴，宝玉先吟这一首。持螯泼醋，写尽席上馋相；末借东坡「为口忙」自嘲，正合他富贵闲人贪玩贪吃的心性。","出处":"第38回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"题「螃蟹詠」，原文各人同题；注明作者","异文":["「公子卻無腸」程乙本作「公子竟無腸」"],"组":"螃蟹詠"},"pangxie-daiyu":{"题":"螃蟹詠（黛玉）","作者":"daiyu","名":"黛玉","回":38,"回目":"林瀟湘魁奪菊花詩 薛蘅蕪諷和螃蟹詠","句":["鐵甲長戈死未忘，堆盤色相喜先嘗。","螯封嫩玉雙雙滿，殼凸紅脂塊塊香。","多肉更憐卿八足，助情誰勸我千觴。","對斯佳品酬佳節，桂拂清風菊帶霜。"],"白话":"蟹虽已死，仍保持着披铁甲、执长戈的模样；堆放盘中，诱人的色泽让人想先尝一口。双螯里封着白嫩如玉的蟹肉，饱满充实；蟹壳中隆起红润的蟹黄，块块喷香。你的八足肉多，更叫我喜爱；谁来劝我畅饮，让酒助兴？面对这样的美味，欢度佳节，清风拂过桂花，菊花带着秋霜。","串讲2":"第38回，黛玉在宝玉之后写下此诗。先以铁甲长戈写蟹形，再写蟹肉蟹黄的丰美与饮酒助兴的情趣，末以桂花、清风、霜菊收束。","出处":"第38回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「對斯佳品」程乙本作「對茲佳品」"],"组":"螃蟹詠"},"xiangling-yongyue-1":{"题":"詠月（其一）","作者":"xiangling","名":"香菱","回":48,"回目":"濫情人情誤思游藝 慕雅女雅集苦吟詩","句":["月掛中天夜色寒，清光皎皎影團團。","詩人助興常思玩，野客添愁不忍觀。","翡翠樓邊懸玉鏡，珍珠簾外掛冰盤。","良宵何用燒銀燭，晴彩輝煌映畫欄。"],"白话":"月挂中天，夜色清寒，清光皎洁，月影圆圆。诗人助兴，常想赏玩；野客添愁，不忍去看。翡翠楼边悬着一面玉镜，珍珠帘外挂着一只冰盘。良宵何必点银烛，晴明的月彩辉煌，已映亮画栏。","串讲2":"第48回香菱学诗的第一首咏月诗。她写月形、月光及赏月者的不同感受，多用玉镜、冰盘等熟悉比喻。黛玉认为有意思，但措词不雅，须多读诗再作。","出处":"第48回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"香菱学诗第一首，黛玉说「意思却有，只是措词不雅」","异文":["「月掛中天」程乙本作「月桂中天」（疑为程乙录文误）"],"组":"香菱學詩"},"xiangling-yongyue-2":{"题":"詠月（其二）","作者":"xiangling","名":"香菱","回":48,"回目":"濫情人情誤思游藝 慕雅女雅集苦吟詩","句":["非銀非水映窗寒，拭看晴空護玉盤。","淡淡梅花香欲染，絲絲柳帶露初乾。","只疑殘粉塗金砌，恍若輕霜抹玉欄。","夢醒西樓人跡絕，餘容猶可隔簾看。"],"白话":"月光既不像银，也不是水，却映得窗前一片清寒；擦亮眼睛望去，晴空环拥着玉盘般的月亮。淡淡的梅花香仿佛要染上月亮，丝丝柳条上的露水刚刚干去。月光洒在华美的台阶上，仿佛涂了一层残粉；照着栏杆，又像抹了一层薄霜。梦醒时西楼已无人迹，隔着帘子还可以看见月亮留下的身影。","串讲2":"第48回香菱学诗第二首。黛玉评其「还不好」，认为过于穿凿。诗中以银、水、粉、霜等描摹月色，又添入梅香柳露，但用意刻意，尚未自然。","出处":"第48回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"香菱学诗第二首，宝钗评「还不好」","异文":["「拭看晴空」程乙本作「試看睛空」（「睛」疑为程乙录文误）"],"组":"香菱學詩"},"xiangling-yongyue-3":{"题":"詠月（其三）","作者":"xiangling","名":"香菱","回":49,"回目":"琉璃世界白雪紅梅 脂粉香娃割腥啖膻","句":["精華欲掩料應難，影自娟娟魄自寒。","一片砧敲千裏白，半輪雞唱五更殘。","綠蓑江上秋聞笛，紅袖樓頭夜倚欄。","博得嫦蛾應借問，緣何不使永團圓！"],"白话":"月的光华想遮掩大概也难，影子自秀美，月魄自清寒。一片捣衣声敲打着千里月色，半轮残月里鸡叫报五更。江上绿蓑人秋夜听笛，楼头红袖女夜里倚栏。引得嫦娥也要借问一句：为何不让人永远团圆！","串讲2":"第49回展示香菱第三首咏月诗，众人称好。诗以砧声、鸡唱及江上楼头的身影写月下离情，末想象嫦娥也为人间离别发问，寄托长久团圆的愿望。","出处":"第49回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"香菱学诗第三首，社中众人称好","异文":["「嫦蛾應借問」程乙本作「嫦娥應自問」","「緣何不使永團圓」程乙本作「何緣不使永團圞」"],"组":"香菱學詩"},"hongmei-xiuyan":{"题":"詠紅梅花得「紅」字","作者":"xiuyan","名":"岫烟","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["桃未芳菲杏未紅，沖寒先已笑東風。","魂飛庾嶺春難辨，霞隔羅浮夢未通。","綠萼添妝融寶炬，縞仙扶醉跨殘虹。","看來豈是尋常色，濃淡由他冰雪中。"],"白话":"桃花还未盛开，杏花还未染红，红梅已冒着寒气，先向东风展露笑颜。神思飞到梅花遍布的大庾岭，眼前红艳的花色使人难辨冬春；红梅如霞，仿佛隔开了罗浮山的梦境，难与梦中素服的梅花美人相通。它像绿萼仙子添了红妆，又似红烛消融生辉；也像白衣仙子带着醉意，跨过一道残虹。这样的花色哪里寻常！无论浓淡，都任它在冰雪中自在开放。","串讲2":"第50回芦雪庵联句后，岫烟得「红」字咏红梅。首联写冒寒先开，继以庾岭、罗浮及仙女意象点染红色，末写冰雪中自在开放，可读出清高自守的意味。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「先已笑東風」程乙本作「先喜笑東風」"],"组":"詠紅梅花"},"hongmei-liwen":{"题":"詠紅梅花得「梅」字","作者":"liwen","名":"李纹","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["白梅懶賦賦紅梅，逞艷先迎醉眼開。","凍臉有痕皆是血，醉心無恨亦成灰。","誤吞丹藥移真骨，偷下瑤池脫舊胎。","江北江南春燦爛，寄言蜂蝶漫疑猜。"],"白话":"懒得咏白梅，偏来咏红梅；它逞着艳丽，先迎着醉眼开放。冻红的脸颊上有痕，都是血；醉透的心即使无恨，也成了灰。误吞丹药换了真骨，偷下瑶池脱去旧胎。江北江南春色灿烂，寄语蜂蝶不要胡乱猜疑。","串讲2":"芦雪庵咏红梅，李纹分得「梅」字韵。诗先撇开白梅，以血痕、心灰写红梅，再借丹药、瑶池想象其换骨脱胎，末劝蜂蝶莫疑，突出红梅色艳而品格不俗。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「醉心無恨」程乙本作「酸心無恨」"],"组":"詠紅梅花"},"hongmei-baoqin":{"题":"詠紅梅花得「花」字","作者":"baoqin","名":"宝琴","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["疏是枝條艷是花，春妝兒女競奢華。","閒庭曲檻無餘雪，流水空山有落霞。","幽夢冷隨紅袖笛，遊仙香泛絳河槎。","前身定是瑤臺種，無復相疑色相差。"],"白话":"枝条疏朗，花朵鲜艳，像春日盛妆的少女争相比美。闲静庭院、曲折栏杆旁，红梅不像残雪，倒像流水空山间的一片落霞。清冷的幽梦随着红袖女子的笛声飘去；又仿佛乘着木筏游于天河，梅香一路浮动。它前身一定是瑶台的仙种，不必因它与白梅颜色不同，就怀疑它的来历。","串讲2":"芦雪庵咏红梅，宝琴分得「花」字韵。诗以春妆少女比花，用白雪、落霞映衬其色，再写笛声与乘槎游仙的想象，末以瑶台仙种作结，申明红白虽异，来历不俗。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","组":"詠紅梅花"},"dengmi-xiangyun":{"题":"燈謎（耍的猴兒）","作者":"xiangyun","名":"湘云","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["溪壑分離，紅塵游戲，真何趣？名利猶虛，後事終難繼。"],"白话":"离开山溪沟壑，在尘世间供人戏耍，究竟有什么趣味？名利仍是虚幻的，后面的事终究接续不上。末句还暗扣猴尾被剁去，不能再接续。","串讲2":"湘云用《点绛唇》作谜，谜底是供人戏耍的猴儿。前写离开山林、入世献戏，末句借「后事难继」扣断尾；宝玉猜中后，湘云亲口解释了这一关窍。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","备注":"原文有「打一…」提示，此谜无提示，谜底出现在随后对话","组":"燈謎"},"dengmi-baochai-50":{"题":"燈謎（梵鈴聲）","作者":"baochai","名":"宝钗","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["鏤檀鍥梓一層層，豈系良工堆砌成？","雖是半天風雨過，何曾聞得梵鈴聲！","打一物。"],"白话":"层层叠叠，仿佛用檀木、梓木雕刻出来，难道真是巧匠堆砌成的吗？虽在高处经受风雨，却何曾听见它发出寺塔檐铃般的声音！猜一件东西。","串讲2":"第五十回宝钗所作灯谜。谜面写一物层叠如雕刻，却非人工制成；高处经风雨，也无塔铃声。原著未揭底，旧评有猜松球的说法。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","异文":["「鏤檀鍥梓」程乙本作「鏤檀鐫梓」","程乙本无「打一物」提示行"],"组":"燈謎"},"dengmi-baoyu-50":{"题":"燈謎（寶玉）","作者":"baoyu","名":"宝玉","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["天上人間兩渺茫，琅玕節過謹提防。","鸞音鶴信須凝睇，好把唏噓答上蒼。"],"白话":"天上与人间都显得渺远茫茫；说到竹的节候已过，便须谨慎提防。鸾鹤般的声息、消息，要凝神留意，好用声声叹息回应上天。「琅玕节过」的具体谜意有不同解释，这里只译其表面意思。","串讲2":"宝玉的灯谜以天上人间、竹、声息与凝望设谜。原著未揭底，旧评有猜风筝琴的说法。诗中虽有怅惘语气，仍须结合物谜理解，不宜坐实为等待情信。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","备注":"原无题，拟题","拟题":true,"异文":["「好把唏噓」程乙本作「好把欷歔」（同词异体字）"],"组":"燈謎"},"dengmi-daiyu":{"题":"燈謎（黛玉）","作者":"daiyu","名":"黛玉","回":50,"回目":"蘆雪广爭聯即景詩 暖香塢創製春燈謎","句":["騄駬何勞縛紫繩？馳城逐塹勢猙獰。","主人指示風雷動，鰲背三山獨立名。"],"白话":"骏马绿耳，何须用紫色绳索拴住？它驰过城郭、奔逐壕沟，气势威猛。主人一指示，便如风雷发动；在鳌背三山之间独自显名。这里借骏马与神山等形象设谜，不宜当成真实赛马或登山的叙事。","串讲2":"黛玉以骏马奔驰、听从主人指示及鳌背三山等形象设谜。原著未揭底，旧评有猜走马灯的说法，可联系灯上转动的马影及元宵灯山理解。","出处":"第50回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"谜诗","备注":"原无题，拟题","拟题":true,"异文":["「主人指示風雷動」程乙本作「主人指示風雲動」"],"组":"燈謎"},"huaigu-01":{"题":"赤壁懷古其一","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["赤壁沉埋水不流，徒留名姓載空舟。","喧闐一炬悲風冷，無限英魂在內游。"],"白话":"赤壁沉埋，江水仿佛也停止了流动，只留下姓名载在空船上。一把大火喧腾过后，悲风凄冷，无数英魂还在其中游荡。","串讲2":"第51回宝琴作十首怀古绝句，此为其一。咏赤壁之战，写战火沉埋、英魂游荡，苍凉而含悲慨。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"宝琴十首怀古绝句之一，各隐一物为谜","组":"懷古十絕"},"huaigu-02":{"题":"交趾懷古其二","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["銅鑄金鏞振紀綱，聲傳海外播戎羌。","馬援自是功勞大，鐵笛無煩說子房。"],"白话":"铜铸的大钟振响，宣扬朝廷的法度和威严，声威远传海外，播及戎羌。马援自然功劳卓著；说到笛曲所传的事迹，也无须只提张良。","串讲2":"第五十一回宝琴出示十首怀古绝句，此其二。借马援定交趾、声威播于海外，写汉家扬威的豪气，明咏史而暗藏谜意。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「銅鑄金鏞」程乙本作「銅柱金城」"],"组":"懷古十絕"},"huaigu-03":{"题":"鍾山懷古其三","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["名利何曾伴汝身，無端被詔出凡塵。","牽連大抵難休絕，莫怨他人嘲笑頻。"],"白话":"名利何曾与你相伴，你却偏偏奉诏出山做官。人事和名利的牵绊大概难以彻底断绝，也就别埋怨旁人屡屡嘲笑了。","串讲2":"第五十一回宝琴怀古绝句之三。借钟山隐者出山的故事，讥讽隐居与求仕之间的反复，指出名利牵绊难断，并非诗人的自省。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","组":"懷古十絕"},"huaigu-04":{"题":"淮陰懷古其四","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["壯士須防惡犬欺，三齊位定蓋棺時。","寄言世俗休輕鄙，一飯之恩死也知。"],"白话":"壮士也要提防恶人欺凌；韩信齐王之位确定之时，也已埋下日后丧身的祸根。奉劝世人不要轻视贫困中的人，给他一顿饭的恩情，他至死也会记得。","串讲2":"此其四咏淮阴侯韩信。第五十一回宝琴怀古之四，写他受辱、封王、报漂母一饭之恩，寄慨功名成败难料，末句尤见其知恩。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","组":"懷古十絕"},"huaigu-05":{"题":"廣陵懷古其五","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["蟬噪鴉棲轉眼過，隋堤風景近如何。","只緣占得風流號，惹得紛紛口舌多。"],"白话":"蝉鸣鸦栖，转眼就过去了，隋堤的风景如今又怎样呢。只因为占了个「风流」的名号，才惹得众人纷纷议论、口舌是非多。","串讲2":"第五十一回宝琴怀古绝句之五。由蝉鸣鸦栖写时光流转，询问隋堤近况，再以「风流」招来议论收束，语含讽意。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「只緣占得風流號」程乙本作「只緣佔盡風流號」"],"组":"懷古十絕"},"huaigu-06":{"题":"桃葉渡懷古其六","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["衰草閒花映淺池，桃枝桃葉總分離。","六朝梁棟多如許，小照空懸壁上題。"],"白话":"枯草野花倒映在浅池中，桃枝与桃叶终究要分离。六朝那些栋梁人物，也多半有这样的离别之憾，只能对着壁上空悬的小像题写文字。","串讲2":"第五十一回宝琴怀古绝句之六。借桃枝桃叶分离写离别之憾，再由六朝人物写到壁上小像，寄托人去像留的惆怅。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「多如許」程乙本作「多少許」"],"组":"懷古十絕"},"huaigu-07":{"题":"青冢懷古其七","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["黑水茫茫咽不流，冰弦撥盡曲中愁。","漢家制度誠堪歎，樗櫟應慚萬古羞。"],"白话":"茫茫黑水仿佛悲伤得哽咽，停止了流动；琵琶声弹尽了曲中的愁怨。汉朝的制度实在令人叹息，那些无用之人应为这万古的耻辱感到羞愧。","串讲2":"第七首借昭君出塞写悲怨，以黑水、琵琶声起兴，末两句转为讥叹。它也是一首隐物诗谜，小说没有揭明谜底。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「誠堪歎」程乙本作「誠堪笑」"],"组":"懷古十絕"},"huaigu-08":{"题":"馬嵬懷古其八","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["寂寞脂痕漬汗光，溫柔一旦付東洋。","只因遺得風流跡，此日衣衾尚有香。"],"白话":"寂寞地留下胭脂的痕迹和汗水的光泽，往日的温柔一朝消散得无影无踪。只因还留有她的风流遗迹，如今衣服和被褥上仍有余香。","串讲2":"第八首借马嵬杨贵妃之事，以脂痕、汗光和衣衾余香写人亡而遗迹尚存。宝钗所说「前八首都是史鉴上有据的」，包括此首。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「脂痕漬汗光」程乙本作「脂痕積汗光」","「衣衾尚有香」程乙本作「衣裳尚有香」"],"组":"懷古十絕"},"huaigu-09":{"题":"蒲東寺懷古其九","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["小紅骨踐最身輕，私掖偷攜強撮成。","雖被夫人時吊起，已經勾引彼同行。"],"白话":"红娘这小丫鬟被说成身份轻贱，却暗中扶持、偷偷帮助，极力把张生和莺莺撮合在一起。虽被夫人吊起责问，她早已使两人相好。","串讲2":"第九首咏《西厢记》红娘，写她偷传书简、强撮姻缘，虽遭夫人拷问，木已成舟。此首出戏文，非史鉴所载，故宝钗疑之，黛玉为之辩解。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","异文":["「小紅骨踐最身輕」程乙本作「小紅骨賤一身輕」","疑点：另有校对稿都称庚辰本作「骨賤」，「骨踐」文义不通，疑底本形近误录；但无庚辰影印本可对"],"待核":"「小紅骨踐最身輕」：「骨踐」文义不通，另有校对稿均称庚辰本作「骨賤」，程乙本作「骨賤一身輕」；疑底本形近误录，无庚辰影印本，无法判断","组":"懷古十絕"},"huaigu-10":{"题":"梅花觀懷古其十","作者":"baoqin","名":"宝琴","回":51,"回目":"薛小妹新編懷古詩 胡庸醫亂用虎狼藥","句":["不在梅邊在柳邊，個中誰拾畫嬋娟。","團圓莫憶春香到，一別西風又一年。"],"白话":"不在梅树旁，却在柳树旁；这里是谁拾得了那幅美人的画像？莫再回想春香到来时的团圆情景；一别之后，秋风又起，又过去了一年。","串讲2":"第十首借《牡丹亭》杜丽娘题画、柳梦梅拾画等事入诗，末写团圆与别离。宝钗认为它与蒲东寺一首史鉴无考，黛玉则以戏曲广为人知作辩。","出处":"第51回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","组":"懷古十絕"},"zhenzhen-shi":{"题":"外國女孩詩（昨夜朱樓夢）","作者":"zhenzhenguo","名":"真真国女孩（宝琴诵）","回":52,"回目":"俏平兒情掩蝦鬚鐲 勇晴雯病補雀金裘","句":["昨夜朱樓夢，今宵水國吟。","島雲蒸大海，嵐氣接叢林。","月本無今古，情緣自淺深。","漢南春歷歷，焉得不關心。"],"白话":"昨夜梦见朱红的楼阁，今夜在水乡吟唱。岛上的云气蒸腾于大海，山间的岚雾连着丛林。月亮本无古今之分，人的情缘却自有浅深。汉南的春色历历在目，叫人怎能不牵挂？","串讲2":"第五十二回宝琴讲述幼时遇见真真国女孩的经历，并诵读她的五律。诗由朱楼之梦、水国之吟写到海岛景象，再以月色与情缘相对，末句表达牵挂。","出处":"第52回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"宝琴诵的真真国女孩汉诗；原无题，拟题","拟题":true},"liuxu-baoqin":{"题":"西江月·柳絮","作者":"baoqin","名":"宝琴","回":70,"回目":"林黛玉重建桃花社 史湘雲偶填柳絮詞","句":["漢苑零星有限，隋堤點綴無窮。三春事業付東風，明月梅花一夢。","幾處落紅庭院，誰家香雪簾櫳？江南江北一般同，偏是離人恨重！"],"白话":"汉代宫苑里的柳絮零星有限，隋堤上的柳絮却点缀不尽。整个春天的繁华都随东风消逝，明月下的梅花也如一场梦。几处庭院中落花纷纷，谁家的帘窗前飞着白雪般的柳絮？江南江北都是这样的景象，偏偏离别之人的愁恨格外深重。","串讲2":"第七十回众人填柳絮词，宝琴作《西江月》。上片由汉苑、隋堤写春光消逝，下片转入庭院帘窗，再由江南江北相同的景象，落到离人的深重愁恨。","出处":"第70回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"词","备注":"原文题「西江月」，同社作柳絮词","异文":["「明月梅花一夢」程乙本作「明月梨花一夢」"]},"gui-jialan":{"题":"姽嫿詞（賈蘭）","作者":"jialan","名":"贾兰","回":78,"回目":"老學士閒徵姽嫿詞 痴公子杜撰芙蓉誄","句":["姽嫿將軍林四娘，玉為肌骨鐵為腸，","捐軀自報恆王後，此日青州土亦香。"],"白话":"姽婳将军林四娘，肌骨如玉，意志如铁。她为报答恒王的恩遇而捐躯；从她牺牲的那一天起，青州的泥土也因她而芬芳。","串讲2":"第七十八回，贾政命宝玉、贾环、贾兰各作诗吊林四娘。贾兰以七绝赞她外柔内刚、捐躯报恩，末句以青州土香寄托对忠烈的赞美。","出处":"第78回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"七言绝句","异文":["「土亦香」程乙本作「土尚香」"],"组":"姽嫿詞"},"gui-jiahuan":{"题":"姽嫿詞（賈環）","作者":"jiahuan","名":"贾环","回":78,"回目":"老學士閒徵姽嫿詞 痴公子杜撰芙蓉誄","句":["紅粉不知愁，將軍意未休。","掩啼離繡幕，抱恨出青州。","自謂酬王德，詎能復寇讎。","誰題忠義墓，千古獨風流。"],"白话":"她原是无忧无愁的红粉女子，如今身为将军，心中的悲愤仍不能平息。她掩泪离开绣幕，怀恨走出青州。只想着报答恒王的恩德，却怎能向仇敌报仇？谁来为她的忠义之墓题字？她的风骨将独传千古。","串讲2":"第七十八回，贾环与宝玉、贾兰同题吊林四娘。此诗写她由无愁女子转为含恨出战的将军，既叹报仇难成，又赞其忠义长存。","出处":"第78回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"诗","备注":"五言律诗","异文":["「詎能復寇讎」程乙本作「誰能復寇仇」","「誰題忠義墓」程乙本作「好題忠義墓」"],"组":"姽嫿詞"},"zilingzhou-ge":{"题":"紫菱洲歌","作者":"baoyu","名":"宝玉","回":79,"回目":"薛文龍悔娶河東獅 賈迎春誤嫁中山狼","句":["池塘一夜秋風冷，吹散芰荷紅玉影。","蓼花菱葉不勝愁，重露繁霜壓纖梗。","不聞永晝敲棋聲，燕泥點點污棋枰。","古人惜別憐朋友，況我今當手足情！"],"白话":"一夜秋风使池塘变得寒冷，吹散了菱荷间红玉般的花影。蓼花和菱叶仿佛也承受不住愁苦，浓露严霜压着细弱的茎梗。再听不到漫长白日里落子下棋的声音，只有点点燕泥弄脏了棋盘。古人尚且为朋友离别而伤心，何况我如今面对的是亲如手足的姐姐离去！","串讲2":"第七十九回宝玉见迎春迁出大观园待嫁，独到紫菱洲一带徘徊，见轩窗寂寞、岸上蓼花苇叶零落，因吟此歌。由秋景衰败写到棋声断绝，末句点出「手足情」，是替二姐姐伤，也是替自己伤。","出处":"第79回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"歌行","备注":"原无题，「紫菱洲歌」为通行叫法","异文":["「不勝愁」程乙本作「不勝悲」"]},"panci-01":{"题":"又副冊判詞：晴雯","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["霽月難逢，彩雲易散。心比天高，身為下賤。風流靈巧招人怨，壽夭多因毀謗生，多情公子空牽念。"],"白话":"雨后明月难逢，彩云易散。她心比天高，出身却低贱。风流灵巧反招人怨，短命多因毁谤而起，多情公子只落得空自牵挂。","串讲2":"这是宝玉梦游太虚幻境时，在又副册里看到的第一首判词，写的是晴雯。册中只有画与诗，宝玉当时并不解其意。词里一「空」字，最见牵挂落空的怅惘。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"又副冊","组":"太虛幻境"},"panci-02":{"题":"又副冊判詞：襲人","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["枉自溫柔和順，空雲似桂如蘭。","堪羨優伶有福，誰知公子無緣。"],"白话":"白白地温柔和顺，空说像桂花兰花一样。可羡那唱戏的人有福气，谁知公子却没有缘分。","串讲2":"又副册第二首，指袭人。开篇以「枉自」「空云」写温柔芳洁也留不住与宝玉的缘分；后两句以优伶蒋玉菡有福、公子宝玉无缘相对，预示她的归宿。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"又副冊","组":"太虛幻境"},"panci-03":{"题":"副冊判詞：香菱","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["根並荷花一莖香，平生遭際實堪傷。","自從兩地生孤木，致使香魂返故鄉。"],"白话":"菱与荷花相伴生长，一茎带着清香，一生的遭遇实在令人悲伤。自从那由两「土」和一「木」合成的「桂」出现，她便走向香魂归去的悲惨结局。","串讲2":"副册判词，写香菱。首句以菱、荷花暗合「香菱」与原名「英莲」，次句叹其身世；末两句拆出「桂」字，暗指夏金桂，并预示香菱的死亡。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"副冊","组":"太虛幻境"},"panci-04":{"题":"正冊判詞：寶釵黛玉（合一首）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["可歎停機德，誰憐詠絮才。","玉帶林中掛，金簪雪裏埋。"],"白话":"可叹那停机劝夫的贤德，谁怜惜那咏絮般的诗才。玉带悬挂在树林中，金簪埋没在雪里。","串讲2":"正册中宝钗、黛玉合写的判词。「停机德」指宝钗，「咏絮才」指黛玉；末两句以字形、谐音暗藏二人姓名，并以悬挂、埋没的意象预示悲剧命运。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-05":{"题":"正冊判詞：元春","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["二十年來辨是非，榴花開處照宮闈。","三春爭及初春景，虎兔相逢大夢歸。"],"白话":"二十年来辨别是非，石榴花盛开，映照着深宫。迎春、探春、惜春三姐妹，怎及得上元春的荣华；到了「虎兔相逢」之时，她便结束人生大梦，魂归而去。","串讲2":"元春判词先写辨别是非与宫中荣华，再以「三春」「初春」暗指四姐妹，突出元春的显贵；末句以「虎兔相逢」设下隐语，「大梦归」预示其死亡。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-06":{"题":"正冊判詞：探春","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["才自精明志自高，生於末世運偏淆。","清明涕送江邊望，千里東風一夢遙。"],"白话":"她才干出众，为人精明，志向高远，却生在衰败的时代，命运偏偏不顺。清明时节，人们在江边含泪送别、望着远去的身影；相隔千里，春风中只能寄托遥远的梦与思念。","串讲2":"此首列太虚幻境薄命司正册，是宝玉梦游时所见的判词，专写探春。她精明有志，偏生在末世，江边泪送、东风梦遥，一腔抱负终成远别之痛，字里全是可惜。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","异文":["「運偏淆」程乙本作「運偏消」","疑点：另有校对稿也都称庚辰本作「消」；「運偏淆」文义不顺，疑底本形近误录；无庚辰影印本可对"],"待核":"「運偏淆」：另有校对稿与程乙本都作「運偏消」，「淆」文义不顺，疑底本形近误录；无庚辰影印本，无法判断","组":"太虛幻境"},"panci-07":{"题":"正冊判詞：湘雲","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["富貴又何為，襁褓之間父母違。","展眼吊斜暉，湘江水逝楚雲飛。"],"白话":"富贵又有什么用呢，还在襁褓之中就与父母分离。转眼之间，已是凭吊夕阳晚照，湘江的水流去了，楚地的云也飘散了。","串讲2":"太虚幻境正册又一首，写史湘云。她襁褓中便失去父母，纵有富贵出身也换不来亲缘。末句以「湘江」「楚雲」暗嵌其名，水逝云飞，正是繁华易散、身世飘零的写照。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-08":{"题":"正冊判詞：妙玉","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["欲潔何曾潔，雲空未必空。","可憐金玉質，終陷淖泥中。"],"白话":"想保持洁净，却哪里能始终洁净；说要看空一切，却未必真能放下尘世牵挂。可怜她有金玉般美好的资质，最终却陷入污泥之中。","串讲2":"妙玉判词写求洁而难保洁、言空而未能尽空。「金玉质」与「淖泥中」相对，以美玉陷入污泥的意象，预示她清高自守却终遭污浊命运的悲剧。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-09":{"题":"正冊判詞：迎春","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["子係中山狼，得志便猖狂。","金閨花柳質，一載赴黃粱。"],"白话":"那人像中山狼一样忘恩负义，一得势便猖狂起来。出身富贵、如花似柳的迎春，出嫁不过一年便丧了命，美好年华如梦般消散。","串讲2":"太虚幻境正册写迎春。判词以「中山狼」喻凶恶负心之人，「得志便猖狂」写其嘴脸。后二句转写迎春柔弱，金闺花柳之质，一载便赴黄粱，柔与暴相撞，最见惨痛。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-10":{"题":"正冊判詞：惜春","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["勘破三春景不長，緇衣頓改昔年妝。","可憐繡戶侯門女，獨臥青燈古佛旁。"],"白话":"看破了三春的好景不能长久，便换上黑色僧衣，顿时改了当年的妆扮。可怜这绣户侯门出身的女儿，独自卧在青灯古佛的旁边。","串讲2":"太虚幻境正册写惜春。她看破春光易逝，换下罗绮、披上缁衣，落得青灯古佛相伴。「繡戶侯門女」与「青燈古佛」一贵一寂，繁华到头竟是一场空。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-11":{"题":"正冊判詞：王熙鳳","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["凡鳥偏從末世來，都知愛慕此生才。","一從二令三人木，哭向金陵事更哀。"],"白话":"这位凤一般的女子，偏偏生在衰败的时代，人人都赞赏她的才干。「一从二令三人木」含有隐语，具体含义有争议；结句写她哭向金陵，遭遇更加悲哀。","串讲2":"这是宝玉在太虚幻境翻阅的正册判词，写王熙凤。「凡鸟」拆字藏名，前两句赞才而叹生不逢时，末两句预示悲局；第三句的具体含义有争议。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-12":{"题":"正冊判詞：巧姐","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["勢敗休雲貴，家亡莫論親。","偶因濟村婦，巧得遇恩人。"],"白话":"家势衰败，就别再夸说尊贵；家族败亡，也别指望亲属一定肯相助。只因母亲王熙凤曾偶然周济刘姥姥，巧姐后来才有幸遇到这位恩人搭救。","串讲2":"这是宝玉在太虚幻境翻阅的巧姐判词。前两句写家败之后富贵与亲缘不足依靠；后两句写凤姐曾周济刘姥姥，使巧姐后来得遇恩人相救。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","异文":["「偶因濟村婦」程乙本作「偶因濟劉氏」"],"组":"太虛幻境"},"panci-13":{"题":"正冊判詞：李紈","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["桃李春風結子完，到頭誰似一盆蘭。","如冰水好空相妒，枉與他人作笑談。"],"白话":"桃李在春风中结成了果实，到最后，谁能比得上那一盆兰花？后两句通常可理解为：即使品行像冰水一样清洁美好，惹人羡妒也终归徒然，白白成为别人的谈资；具体含义仍有争议。","串讲2":"这是宝玉在太虚幻境翻阅的李纨判词。「李」与「完」暗点姓名，「兰」指其子贾兰。后两句含义有争议，宜保留其徒劳与悲凉之意，不坐实羡妒的对象。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"panci-14":{"题":"正冊判詞：秦可卿","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["情天情海幻情身，情既相逢必主淫。","漫言不肖皆榮出，造釁開端實在寧。"],"白话":"情天情海幻化出这具情身，情与情一旦相逢，必归于淫。别说那些不肖子弟都是荣国府出来的，真正惹祸开端的，其实在宁国府。","串讲2":"这是宝玉在太虚幻境翻阅的秦可卿判词。前两句反复写「情」，引出对淫欲的警示；后两句以荣、宁对举，指出祸乱的开端在宁国府。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"判词","册":"正冊","组":"太虛幻境"},"qu-00":{"题":"紅樓夢曲：紅樓夢引子","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["開闢鴻蒙，誰為情種？","都只為風月情濃；趁著這奈何天，傷懷日，寂寥時，試遣愚衷，因此上演出這悲金悼玉的「紅樓夢」。"],"白话":"自开天辟地以来，谁才是那情种？都只为风月之情太浓；趁着这无可奈何的天、伤怀的日子、寂寥的时节，姑且排遣我一片愚衷，因此上才演出这部悲金悼玉的《红楼梦》。","串讲2":"《红楼梦》曲组的引子，第五回由警幻命舞女唱给宝玉听。以「谁为情种」发问，以「悲金悼玉」点明悲悼之意，为诸曲定下伤怀的基调。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["疑点（未能核实）：另有校对稿称庚辰本作「懷金悼玉」；底本及程乙本均作「悲金悼玉」"],"待核":"「悲金悼玉」：另有校对稿称庚辰本作「懷金悼玉」，底本与程乙本均作「悲」，底本第五回该处疑与程本同源；无庚辰影印本，无法判断","组":"太虛幻境"},"qu-01":{"题":"紅樓夢曲：終身誤","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["都道是金玉良緣，俺只念木石前盟。","空對著，山中高士晶瑩雪；終不忘，世外仙姝寂寞林。","歎人間，美中不足今方信。","縱然是齊眉舉案，到底意難平。"],"白话":"人们都说金玉相配是好姻缘，我却只惦念木石的前缘。即使面对像山中高洁隐士一般的薛宝钗，心里仍忘不了像世外仙女一般寂寞的林黛玉。如今才相信，人间的美好总有缺憾。纵然夫妻彼此敬重，心中的遗憾终究难以平息。","串讲2":"此曲出太虚幻境，为十二支曲之一，写一段姻缘错配。金玉良缘与木石前盟相对，山中高士、世外仙姝各指一人。纵得举案齐眉，心中终究难平。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["疑点（未能核实）：另有校对稿称庚辰本作「金玉良姻」；底本及程乙本均作「金玉良緣」"],"待核":"「金玉良緣」：另有校对稿称庚辰本作「金玉良姻」，底本与程乙本均作「緣」，底本第五回该处疑与程本同源；无庚辰影印本，无法判断","组":"太虛幻境"},"qu-02":{"题":"紅樓夢曲：枉凝眉","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["一個是閬苑仙葩，一個是美玉無瑕。","若說沒奇緣，今生偏又遇著他；若說有奇緣，如何心事終虛化？","一個枉自嗟呀，一個空勞牽掛；一個是水中月，一個是鏡中花。","想眼中能有多少淚珠兒，怎經得秋流到冬，春流到夏？"],"白话":"一个像仙境里的花朵，一个像毫无瑕疵的美玉。若说没有奇妙的缘分，今生偏偏又遇见了他；若说有这样的缘分，为什么心中的愿望最终落空？一个徒然叹息，一个白白牵挂；所盼的美好如水中的月亮、镜中的花影，无法真正得到。眼里能有多少泪水，哪里经得起从秋天流到冬天、从春天流到夏天？","串讲2":"此曲写宝玉与黛玉有缘相遇而心愿难成。仙花与美玉相对，水中月、镜中花比喻难以实现的美好，四季不断的泪水写出无尽悲愁。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「怎經得」程乙本作「怎禁得」","「秋流到冬」程乙本作「秋流到冬盡」"],"组":"太虛幻境"},"qu-03":{"题":"紅樓夢曲：恨無常","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["喜榮華正好，恨無常又到。","眼睜睜，把萬事全拋；蕩悠悠，把芳魂消耗。","望家鄉，路遠山高。","故向爹娘夢裏相尋告：兒命已入黃泉，天倫呵，須要退步抽身早。"],"白话":"正为眼前的荣华欢喜，却恨死亡忽然来临。只能眼睁睁地抛下世间一切，魂魄飘飘荡荡，渐渐消散。遥望家乡，却隔着高山远路。因此到父母梦中寻找他们，告诉他们：女儿已经死去，爹娘啊，要及早从眼前的荣华中退身。","串讲2":"此曲出太虚幻境，写荣华骤断、芳魂将逝之人。万事全抛，家乡路远，只能梦中告爹娘：儿已入黄泉，须及早退步抽身。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-04":{"题":"紅樓夢曲：分骨肉","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["一帆風雨路三千，把骨肉家園齊來拋閃。","恐哭損殘年，告爹娘，休把兒懸念。","自古窮通皆有定，離合豈無緣？","從今分兩地，各自保平安。","奴去也，莫牽連。"],"白话":"乘船冒着风雨，远行三千里，把亲人和家园都留在身后。怕父母因悲伤哭泣损害晚年的身体，便劝他们：不要挂念女儿。自古境遇的困厄与顺遂都有定数，分离与团聚又怎会没有缘由？从今以后相隔两地，愿彼此都平安。女儿这就走了，请不要再为我牵挂。","串讲2":"此曲出太虚幻境，写骨肉分离。一帆风雨，远路三千，抛下家园骨肉。怕爹娘哭损残年，劝他们休要挂念，离合有定，各自保平安。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-05":{"题":"紅樓夢曲：樂中悲","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["襁褓中，父母歎雙亡，縱居那綺羅叢，誰知嬌養？","幸生來，英豪闊大寬宏量，從未將兒女私情略縈心上，好一似，霽月光風耀玉堂。","廝配得才貌仙郎，博得個地久天長，凖折得幼年時坎坷形狀。","終久是雲散高唐，水涸湘江。","這是塵寰中消長數應當，何必枉悲傷。"],"白话":"还在襁褓中时，父母便双双去世，令人叹息。即使生活在富贵之家，又有谁像父母一样疼爱她？幸而她生来豪爽大度，从不把儿女私情放在心上，胸襟像雨过天晴后的明月清风一样明朗。与才貌出众的丈夫结为夫妻，原以为能长久相守，补偿幼年的坎坷；到头来却夫妻情缘消散，仿佛高唐的云散去、湘江的水干涸。这是人世间盛衰变化的命数，又何必徒然悲伤。","串讲2":"此曲出太虚幻境，写一位襁褓失亲、性情豪阔的女子。虽配得才貌仙郎，终归云散水涸，好景难长，故以何必枉悲伤作结。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-06":{"题":"紅樓夢曲：世難容","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["氣質美如蘭，才華阜比仙，天生成孤癖人皆罕。","你道是啖肉食腥膻，視綺羅俗厭；卻不知太高人愈妒，過潔世同嫌。","可歎這，青燈古殿人將老；辜負了，紅粉朱樓春色闌；到頭來，依舊是風塵骯髒違心願。","好一似，無瑕白玉遭泥陷；又何須，王孫公子歎無緣。"],"白话":"气质美如兰花，才华丰盛可比神仙，天生性情孤僻，世人都觉得奇异。你说吃肉嫌腥膻，穿绫罗嫌俗气；却不知道，越清高越招人妒忌，过于洁净也遭世人嫌弃。可叹在青灯古殿中渐渐老去，辜负了青春与闺阁中的美好年华；到头来仍身陷尘世污浊，违背自己的心愿。好比无瑕白玉陷进泥里，王孙公子又何必叹息与她无缘。","串讲2":"此曲咏妙玉。她气质高洁、才华出众，却因孤僻清高遭世人妒嫌。青灯古殿未能保全她的清净，白玉陷泥的比喻预示了违背心愿的悲剧。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「才華阜比仙」程乙本作「才華馥比仙」"],"组":"太虛幻境"},"qu-07":{"题":"紅樓夢曲：喜冤家","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["中山狼，無情獸，全不念當日根由，一味的驕奢淫蕩貪還構。","覷著那，侯門艷質同蒲柳；作踐的，公府千金似下流。","歎芳魂艷魄，一載蕩悠悠。"],"白话":"那像中山狼一样无情的恶人，全不顾念往日所受的恩惠，只顾骄横奢侈、荒淫放荡，既贪婪又构陷人。他把侯门出身的美貌女子看得如蒲柳般低贱，把公府千金肆意糟蹋，视同卑贱之人。可叹她婚后不过一年便死去，只剩魂魄飘荡无依。","串讲2":"此曲咏迎春，斥责孙绍祖忘恩负义、残酷作践妻子。侯门千金被视同低贱之人，结句预示她婚后一年便死去，写出婚姻悲剧的惨痛。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「驕奢淫蕩貪還構」程乙本作「驕奢淫蕩貪歡媾」"],"组":"太虛幻境"},"qu-08":{"题":"紅樓夢曲：虛花悟","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["將那三春看破，桃紅柳綠待如何？","把這韶華打滅，覓那清淡天和。","說什麼，天上夭桃盛，雲中杏蕊多；到頭來，誰把秋捱過？","則看那，白楊村裏人嗚咽，青楓林下鬼吟哦；更兼著，連天衰草遮墳墓。","這的是，昨貧今富人勞碌，春榮秋謝花折磨。","似這般，生關死劫誰能躲？","聞說道，西方寶樹喚婆娑，上結著長生果。"],"白话":"看破了三春的繁华，桃红柳绿又有什么可留恋？舍弃对青春繁华的留恋，寻求清净淡泊、自然平和的生活。说什么天上的桃花盛开、云中的杏花繁多，到头来谁能熬过秋天？只见白杨掩映的墓地里有人哭泣，青枫林下有鬼魂低吟，还有无边衰草遮住坟墓。人为了贫富的变化不停劳碌，花也在春荣秋谢中受尽折磨。这样的生死关头与劫难，谁能躲开？听说西方有一棵叫婆娑的宝树，上面结着长生果。","串讲2":"《红楼梦曲》一支，咏一位看破繁华、心向清净的女子。她勘破三春荣谢，以白杨衰草写尽坟茔冷落，末转西方宝树长生果，寄意于佛门清净。冷中带悟，是曲中最近禅的一支。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「誰把秋捱過」程乙本作「誰見把秋捱過」"],"组":"太虛幻境"},"qu-09":{"题":"紅樓夢曲：聰明累","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["機關算盡太聰明，反算了卿卿性命。","生前心已碎，死後性空靈。","家富人寧，終有個家亡人散各奔騰。","枉費了，意懸懸半世心；好一似，蕩悠悠三更夢。","忽喇喇似大廈傾，昏慘慘似燈將盡。","呀，一場歡喜忽悲辛；歎人世，終難定。"],"白话":"费尽心机，聪明过了头，反而害了自己的性命。活着时已经操碎了心，死后即使魂灵仍有知觉，也无济于事。原想家业富足、家人安宁，最终却落得家业败亡、亲人离散，各自奔逃。半辈子的牵挂操劳全都白费，好比半夜一场虚幻的梦。家业崩败如大厦轰然倾倒，生命衰竭如灯火昏暗将熄。啊，一场欢喜忽然变成悲苦，可叹人世的变化终究难以预料。","串讲2":"《红楼梦曲》一支，咏一位精明能干、执掌家务的女子。机关算尽却反算自身，半世心悬，终成三更一梦。大厦倾、灯将尽两喻，把盛极而衰写得惊心，是曲中最见警世意味的一支。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-10":{"题":"紅樓夢曲：留餘慶","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["留餘慶，留餘慶，忽遇恩人；幸娘親，幸娘親，積得陰功。","勸人生，濟困扶窮，休似俺那愛銀錢忘骨肉的狠舅奸兄。","正是乘除加減，上有蒼穹。"],"白话":"留下余庆，留下余庆，忽然遇见恩人；幸亏娘亲，幸亏娘亲，积下了阴功。劝人活在世上，要济困扶穷，别学我那爱银钱、忘骨肉的狠舅奸兄。这正是加减乘除的报应，头上有苍天看着。","串讲2":"《红楼梦曲》一支，以一个蒙难女儿的口吻自述。她因娘亲积下阴功，忽逢恩人得救；回头痛骂爱钱忘亲的狠舅奸兄。全曲借报应劝人济困扶穷，是十二支中最见因果、也最带暖意的一支。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-11":{"题":"紅樓夢曲：晚韶華","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["鏡裏恩情，更那堪夢裏功名；那美韶華去之何迅，再休提繡帳鴛衾。","只這帶珠冠，披鳳襖，也抵不了無常性命。","雖說是，人生莫受老來貧，也須要陰騭積兒孫。","氣昂昂頭戴簪纓，光燦燦胸懸金印；威赫赫爵祿高登，昏慘慘黃泉路近。","問古來將相可還存？","也只是虛名兒與後人欽敬。"],"白话":"夫妻恩情如镜中影，功名又如梦里事，美好年华去得真快，再莫提那绣帐鸳衾。纵然戴珠冠、披凤袄，也抵不过生死无常。虽说人生莫老来受贫，也须为儿孙积些阴德。看他头戴官簪、胸悬金印，威风凛凛高登爵禄，却已昏惨惨临近黄泉。试问古来将相可还存？不过是虚名供后人钦敬。","串讲2":"第5回太虚幻境中，《红楼梦》曲第11支，咏李纨。曲中写她晚岁因子得贵、戴珠冠披凤袄，却已黄泉路近，把镜里恩情、梦里功名一笔叹尽。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","异文":["「只這帶珠冠」程乙本作「只這戴珠冠」"],"组":"太虛幻境"},"qu-12":{"题":"紅樓夢曲：好事終","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["畫梁春盡落香塵，擅風情，秉月貌，便是敗家的根本；箕裘頹墮皆從敬，家事消亡首罪寧，宿孽總因情。"],"白话":"青春凋谢，美人如香尘般陨落；画梁的意象暗示悬梁。她富于风情，具有如月的美貌，却被曲中说成败家的根由。祖业的衰败都从贾敬开始，家事消亡的首要罪责在宁国府；积下的罪孽，总因情而起。","串讲2":"第5回太虚幻境，《红楼梦》曲末支之一，咏秦可卿。曲把「擅风情、秉月貌」认作败家根本，又归罪宁国府，末句「宿孽总因情」点出情字为祸根。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"qu-13":{"题":"紅樓夢曲：飛鳥各投林（收尾）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["為官的、家業凋零，富貴的、金銀散盡，有恩的、死裏逃生，無情的、分明報應，欠命的、命已還，欠淚的、淚已盡。","冤冤相報實非輕，分離聚合皆前定；欲知命短問前生，老來富貴也真僥幸。","看破的、遁入空門，痴迷的、枉送了性命；好一似食盡鳥投林，落了片白茫茫大地真乾淨。"],"白话":"为官的人家业凋零，富贵的人金银散尽；施过恩的人得以死里逃生，无情的人受到应有的报应；欠下性命的，已经以命偿还，欠下眼泪的，已经流尽了泪。冤仇相互报偿，后果实在不轻；分离与团聚，都被说成命中早已注定。要问为何短命，便要追问前生；到了老年还能享有富贵，也实在是侥幸。看破的人遁入佛门，痴迷的人白白送了性命。就像食物耗尽后，群鸟各自飞入树林，只留下一片白茫茫的大地，一切都消散干净了。","串讲2":"第5回《红楼梦》曲的收尾，总束十二支曲。为官、富贵、有恩、无情、欠命、欠泪，一一还报，末以「食尽鸟投林」「白茫茫大地」作结，繁华散尽归于空无。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"曲","组":"太虛幻境"},"jinghuan-qu":{"题":"警幻仙曲（春夢隨雲散）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["春夢隨雲散，飛花逐水流。","寄言眾兒女，何必覓閒愁。"],"白话":"春梦随着云彩散去，飞花追逐流水飘走。寄语世间众儿女，何必自寻那些无谓的闲愁。","串讲2":"第5回宝玉梦入太虚幻境，先闻警幻仙姑作歌，随后仙姑现身。歌中劝众儿女莫寻闲愁，为全篇梦境的缥缈定调。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"歌","组":"太虛幻境"},"jinghuan-fu":{"题":"警幻賦（方離柳塢）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["方離柳塢，乍出花房。","但行處，鳥驚庭樹，將到時，影度迴廊。","仙袂乍飄兮，聞麝蘭之馥郁，荷衣欲動兮，聽環佩之鏗鏘。","靨笑春桃兮，雲堆翠髻，唇綻櫻顆兮，榴齒含香。","纖腰之楚楚兮，迴風舞雪，珠翠之輝輝兮，滿額鵝黃。","出沒花間兮，宜嗔宜喜，徘徊池上兮，若飛若揚。","蛾眉顰笑兮，將言而未語，蓮步乍移兮，待止而欲行。","羨彼之良質兮，冰清玉潤，慕彼之華服兮，閃灼文章。","愛彼之貌容兮，香培玉琢，美彼之態度兮，鳳翥龍翔。","其素若何，春梅綻雪。","其潔若何，秋菊被霜。","其靜若何，松生空谷。","其艷若何，霞映澄塘。","其文若何，龍游曲沼。","其神若何，月射寒江。","應慚西子，實愧王嬙。","奇矣哉，生於孰地，來自何方，信矣乎，瑤池不二，紫府無雙。","果何人哉？","如斯之美也！"],"白话":"她刚离开柳树环绕的地方，才从花房走出。行走时惊动庭树上的鸟儿，将到时身影掠过回廊。仙衣的袖子轻轻飘起，散发出麝香与兰草的浓香；荷叶般的衣裳将动，玉佩便发出清脆的碰撞声。笑脸如春日桃花，乌发如云堆成秀美的发髻；双唇像樱桃般绽开，牙齿如石榴籽般整齐，口中含香。纤腰秀美，身姿如回旋的风、飞舞的雪；珠翠首饰光彩闪耀，额上饰着鹅黄。她出没花间，生气与欢喜的样子都美；徘徊池边，仿佛随时会轻盈飞起。秀眉时蹙时展，想说话却还未开口；脚步刚刚移动，似要停下却又想前行。令人羡慕的是她如冰般清洁、如玉般温润的美好资质；令人倾慕的是她华服上闪耀的纹彩；令人喜爱的是她仿佛由香气滋养、美玉雕成的容貌；令人赞美的是她如凤飞龙翔般的仪态。她的素雅，如雪中绽放的春梅；她的高洁，如经霜的秋菊；她的娴静，如空谷中的青松；她的艳丽，如映照清塘的彩霞；她的风采，如游于曲折池沼的龙；她的神韵，如照射寒江的月光。西施见了也该惭愧，王昭君也会自愧不如。真奇妙啊，她生在何处，来自何方？的确，即使在瑶池、紫府这样的仙境，也找不到第二个能与她相比的人。她究竟是谁，竟有这样的美貌！","串讲2":"第五回警幻仙姑在歌声中出场，此赋随之铺写她的容貌、服饰与神态，借花木、霞月和龙凤设喻，又以西施、昭君作衬，最后以问句和赞叹收束。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"赋","异文":["「雲堆翠髻」程乙本作「雲髻堆翠」","「迴風舞雪」程乙本作「風迴雪舞」","「珠翠之輝輝兮，滿額鵝黃」程乙本作「耀珠翠之的的兮，鴨綠鵝黃」","「蛾眉顰笑兮」程乙本作「蛾眉欲顰兮」","「待止而欲行」程乙本作「欲止而仍行」","「羨彼之良質」程乙本作「羨美人之良質」","「慕彼之華服」程乙本作「慕美人之華服」","「閃灼文章」程乙本作「熌爍文章」","「愛彼之貌容」程乙本作「愛美人之容貌」","「香培玉琢」程乙本作「香培玉篆」","「美彼之態度」程乙本作「比美人之態度」","「其潔若何，秋菊被霜」程乙本作「其潔若何？秋蕙披霜（且前多「其素若何？春梅綻雪」一問）」","「應慚西子，實愧王嬙」程乙本作「遠慚西子，近愧王嬙」","「如斯之美也」程乙本作「果何人哉若斯之美也」","另：程乙本「脣、豔、鬆、遊」等字形差异不逐条记"],"组":"太虛幻境"},"lian-taixu-1":{"题":"太虛幻境聯（假作真時真亦假）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["假作真時真亦假，無為有處有還無。"],"白话":"把假的当作真的时，真的也会被当作假的；把没有的当作有的时候，有的也会被当作没有。这副对联写出真假、有无被颠倒看待的情形。","串讲2":"此联见于第一回和第五回的太虚幻境牌坊。十四字以真假、有无相互翻转，提醒读者留意表象与真实的错置，也呼应全书真事隐去、假语存留的叙述方式。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","备注":"同联见第一回 1.14","组":"太虛幻境"},"lian-taixu-2":{"题":"孽海情天聯（厚地高天）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["厚地高天，堪歎古今情不盡。","癡男怨女，可憐風月債難償。"],"白话":"大地深厚，天空高远，可叹古往今来的情缘绵延不尽；痴情的男子、幽怨的女子，可怜他们欠下的男女情债难以偿还。","串讲2":"此联悬于太虚幻境题有「孽海情天」的宫门。上联叹古今情缘不尽，下联怜痴男怨女情债难偿，以天地古今的广阔映衬情事的绵延。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","异文":["「可憐風月債難償」程乙本作「可憐風月債難酬」"],"组":"太虛幻境"},"lian-bomingsi":{"题":"薄命司聯（春恨秋悲）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["春恨秋悲皆自惹，花容月貌為誰妍。"],"白话":"春日的怨恨、秋天的悲愁，都是自己招惹出来的；如花似月的容颜，究竟是为谁而娇艳？","串讲2":"此联题在太虚幻境薄命司门旁。上句写春秋感伤，称愁恨皆由自身招来；下句追问美好容颜为谁而妍。联语与司名相照应，为册中女子的薄命遭际笼上悲凉色彩。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","组":"太虛幻境"},"lian-qiongfang":{"题":"警幻仙閨聯（幽微靈秀地）","作者":"taixu","名":"太虚幻境","回":5,"回目":"開生面夢演紅樓夢 立新場情傳幻境情","句":["幽微靈秀地，無可奈何天。"],"白话":"这里是幽深微妙、灵气汇聚的所在；却也是令人无可奈何的地方。","串讲2":"此联见于太虚幻境后宫房内。上句写境地幽深微妙、灵秀清美，下句却点出无可奈何之意。清美与怅惘相映，使仙境也带上难以排遣的悲凉。","出处":"第5回（维基文库庚辰本为底本；草稿逐行机械核对 + 程乙本对照）","体":"联","组":"太虛幻境"}}')},tn={作品:JSON.parse('{"haitang-tanchun":{"题":"詠白海棠","串讲":"海棠社头一首是探春的。斜阳、苔盆、三更月影，把白海棠写得又洁又娇；收尾不许它羽化成仙，要它留下陪人吟到黄昏——开社的人就是这股兴头。","典故":[{"原词":"縞仙","解":"穿白绢衣的仙子，借指白海棠"},{"原词":"羽化","解":"化出羽翼飞升成仙，苏轼《赤壁赋》有「羽化而登仙」"},{"原词":"重門","解":"书里第三十七回小丫头随口说个「门」字，就定了韵，几首都押门盆魂痕昏"}],"情绪":["闲适","雅趣"],"情绪组":"闲适","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"haitang-baochai":{"题":"詠白海棠","串讲":"宝钗写花不写艳，写它淡、写它洁：白天掩门自己浇苔，洗尽胭脂，淡到极处反倒更艳。李纨说论含蓄浑厚终让她，压过黛玉拿了头名，像她这个人。","典故":[{"原词":"白帝","解":"秋天的神，五行里秋属白；这里说花以清洁报答秋神"},{"原词":"淡極始知花更艷","解":"书里第三十七回李纨评：「若論含蓄渾厚，終讓蘅稿」"}],"情绪":["孤高","清冷","雅趣"],"情绪组":"幽静","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"haitang-baoyu":{"题":"詠白海棠","串讲":"宝玉拿美人比花：出浴的杨太真、捧心的西施；又把晓风宿雨写成千点愁、一痕泪，末了独倚画栏听砧声笛声到黄昏。李纨判他压尾，他自己也说评得公道。","典故":[{"原词":"出浴太真","解":"杨贵妃号太真，白居易《长恨歌》写她华清池赐浴"},{"原词":"捧心西子","解":"西施心口疼捧心皱眉，反更好看，见《庄子》东施效颦"},{"原词":"清砧","解":"秋夜捣衣的砧声，古诗里常用来写离愁"}],"情绪":["旖旎","怅惘"],"情绪组":"哀婉","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"haitang-daiyu":{"题":"詠白海棠","串讲":"黛玉最后才动笔，一挥而就：碾冰作土、玉作盆，白借梨花、魂借梅花，又添月中仙人缝白袖、闺中人拭泪痕。众人都说这首为上，评下来却屈居第二。","典故":[{"原词":"湘簾","解":"湘妃竹编的帘子；书里第三十七回探春因她住潇湘馆又爱哭，号她潇湘妃子"},{"原词":"月窟仙人","解":"月宫里的仙人，想来指嫦娥一类，衬海棠的白与冷"},{"原词":"梅花一縷魂","解":"借梅花的魂，取梅的清寒孤洁"}],"情绪":["孤高","自伤","清冷"],"情绪组":"夜","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"jishi-chun":{"题":"春夜即事","串讲":"宝玉刚搬进园子，日子快活，随手记下四季夜景。春夜这首：帐子铺开，更鼓听不真，窗外雨、枕上寒，梦里是人；丫头们拥着被子笑闹个不停。","典故":[{"原词":"蟆更","解":"一说「虾蟆更」，旧时夜里报更的鼓声"},{"原词":"霞綃雲幄","解":"彩霞似的纱、云一样的帐；书里第二十三回说这几首「真情真景」"}],"情绪":["闲适","旖旎"],"情绪组":"夜","诗笺":"桃红笺","诗笺依据":"推断"},"jishi-xia":{"题":"夏夜即事","串讲":"夏夜又懒又富贵：人绣倦了睡去，鹦鹉在金笼里喊茶。句里悄悄嵌进麝月、檀云两个丫鬟的名字，琥珀杯、玻璃槛、团扇轻摇，一屋子闲情。","典故":[{"原词":"麝月","解":"宝玉屋里丫鬟的名字，字面又指月亮、镜子"},{"原词":"檀雲","解":"也是宝玉屋里的丫鬟，书里第二十四回说她被母亲生日接了出去"},{"原词":"齊紈","解":"齐地产的白细绢，做团扇；班婕妤《怨歌行》「新裂齊紈素」"}],"情绪":["闲适","旖旎","雅趣"],"情绪组":"闲适","诗笺":"月白笺","诗笺依据":"推断"},"jishi-qiu":{"题":"秋夜即事","串讲":"秋夜的绛芸轩静下来，月光浸着茜纱窗，鹤睡苔石，鸦栖井桐。丫鬟抱被来铺，人倚栏回屋；酒后口渴睡不着，又拨香炉要煮茶。","典故":[{"原词":"絳芸軒","解":"宝玉屋子的名字，书里第八回回目「賈寶玉大醉絳芸軒」"},{"原词":"桂魄","解":"月亮；传说月中有桂树，故称"},{"原词":"茜紗","解":"红纱糊的窗；书里第七十九回黛玉改诔文作「茜紗窗下」"}],"情绪":["闲适","清冷"],"情绪组":"夜","诗笺":"素白竹纸","诗笺依据":"推断"},"jishi-dong":{"题":"冬夜即事","串讲":"冬夜三更还睡不着：一院松影只见鹤，雪落满地像梨花，听不到莺声。诗也冷、酒也薄，幸好丫头懂茶，扫了新雪就煮——园里的日子连冷都是雅的。","典故":[{"原词":"梨花滿地","解":"以梨花比雪，岑参有「千樹萬樹梨花開」"},{"原词":"翠袖","解":"杜甫《佳人》「天寒翠袖薄」，写女子衣单身冷"},{"原词":"金貂","解":"晋人阮孚曾解金貂换酒，这里写公子饮酒"},{"原词":"掃將新雪","解":"雪水煮茶是雅事；书里第四十一回妙玉也用收的梅花雪烹茶"}],"情绪":["清冷","雅趣"],"情绪组":"幽静","诗笺":"雪浪笺","诗笺依据":"推断"},"zanghua-yin":{"题":"葬花吟","串讲":"芒种饯花那天，黛玉独自荷锄把落花埋了，一边哭一边念：风刀霜剑，花落人亡。今天我葬花，人笑我痴，将来谁来葬我？宝玉在山坡上听得恸倒。","典故":[{"原词":"杜鵑","解":"传说蜀帝杜宇死后化杜鹃，啼到口中出血"},{"原词":"香丘","解":"埋花的香坟；第二十七回回目叫「埋香冢」"},{"原词":"一抔淨土","解":"一捧土，旧指坟土，骆宾王檄文有「一抔之土未乾」"},{"原词":"儂今葬花人笑痴","解":"书里第二十八回宝玉在山坡上听到这几句，恸倒在地"}],"情绪":["哀婉","自伤"],"情绪组":"哀婉","诗笺":"素白竹纸·水渍","诗笺依据":"指导§18"},"qiuchuang":{"题":"秋窗風雨夕","串讲":"秋雨夜，黛玉翻了几页乐府，心有所感，仿《春江花月夜》写下这首：一句一个秋字，风雨穿窗、泪烛摇摇，越写越冷，最后连窗纱都被泪打湿。","典故":[{"原词":"秋花慘淡秋草黃","解":"书里第四十五回说这首「擬《春江花月夜》之格」，原名《代别离》"},{"原词":"羅衾不奈","解":"李煜《浪淘沙》「羅衾不耐五更寒」"},{"原词":"疏竹虛窗","解":"潇湘馆窗外的竹，书里第十七回写那里「千百竿翠竹遮映」"}],"情绪":["哀婉","清冷","自伤"],"情绪组":"夜","诗笺":"素白竹纸","诗笺依据":"推断"},"taohua-xing":{"题":"桃花行","串讲":"帘外桃花开得热闹，帘里人比花瘦。拿眼泪比桃花，泪流不止、花自妩媚，泪干时春也尽了。宝玉看了不夸，先落泪；宝琴说是她作的，他不信。","典故":[{"原词":"人比桃花瘦","解":"化用李清照《醉花阴》「人比黃花瘦」"},{"原词":"杜宇","解":"杜鹃鸟，传说蜀帝杜宇所化，啼声凄切，春尽时叫得最勤"},{"原词":"天機","解":"天上织女的织机，这里说满树桃花红得像烧破的锦"}],"情绪":["哀婉","自伤","怅惘"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"ju-yong":{"题":"詠菊","串讲":"诗瘾缠了一整天，她绕着篱笆、靠着石头低声吟。笔下带霜、齿间含香，可满纸都是自怜，谁懂这点秋心？末句一转：菊的高风，陶渊明说过就一直传到今天。","典故":[{"原词":"陶令","解":"陶渊明做过彭泽县令，爱菊成名，有「采菊东篱下」"},{"原词":"詩魔","解":"白居易诗「酒狂又引诗魔发」，指作诗的瘾头"},{"原词":"口齒噙香對月吟","解":"书里第38回李纨评诗，说这句「也敌的过了」，宝玉也服"}],"情绪":["孤高","自伤","清冷"],"情绪组":"幽静","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-wen":{"题":"問菊","串讲":"她背着手去敲东篱，一连串追问菊花：你这样孤高，跟谁一块隐着？为何偏偏开得晚？霜露里寂寞不寂寞？最后软下来：花若能说话，跟我说一句也好。","典故":[{"原词":"東籬","解":"陶渊明「采菊东篱下」，东篱从此就是种菊的地方"},{"原词":"解語","解":"唐玄宗指杨贵妃说「争如我解语花」，这里盼菊花开口"},{"原词":"孤標傲世偕誰隱","解":"书里第38回湘云说「偕谁隐」「为底迟」把菊花问得无言可对"}],"情绪":["孤高","清冷","思念"],"情绪组":"幽静","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-meng":{"题":"菊夢","串讲":"菊花在篱边睡了一觉，梦里和云伴月看不分明。它不学庄子化蝶，只想去找陶渊明的旧约。雁声断了梦，蟋蟀吵醒它，醒来满心幽怨，只剩衰草寒烟。","典故":[{"原词":"莊生蝶","解":"《庄子·齐物论》庄周梦为蝴蝶，醒来不知谁梦谁"},{"原词":"陶令盟","解":"陶渊明爱菊，菊与他像有旧约，梦里还去寻"},{"原词":"蛩鳴","解":"蛩是蟋蟀，秋夜虫声，古诗里常写愁"}],"情绪":["怅惘","清冷","自伤"],"情绪组":"夜","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-hua":{"题":"畫菊","串讲":"作完诗随手玩笔墨，泼几点墨当叶、染几痕白当霜，浓淡全凭手感，画出风里的影、腕底的香。别当是东篱采来的真花，贴在屏上，聊当过个重阳。","典故":[{"原词":"東籬","解":"陶渊明「采菊东篱下」，这里说画上的菊不是真采来的"},{"原词":"重陽","解":"九月初九重阳节，旧俗赏菊饮菊花酒"},{"原词":"丹青","解":"丹砂与青雘两种颜料，借指绘画"}],"情绪":["雅趣","闲适"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-yi":{"题":"憶菊","串讲":"西风里怅望，蓼花红、芦苇白，篱笆空着，菊还没来。只有瘦月清霜知道她梦里在等。心随雁飞远，坐听晚砧发呆。谁懂这是为菊花犯的病？好在重阳总会到。","典故":[{"原词":"黃花","解":"菊的别称，《礼记·月令》「鞠有黄华」"},{"原词":"晚砧","解":"秋夜捣衣的砧声，古诗里常是思人的声音"},{"原词":"秋無跡","解":"书里第38回探春夸「秋无迹」「梦有知」把忆字烘染出来了"}],"情绪":["思念","怅惘"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-fang":{"题":"訪菊","串讲":"趁霜后晴天出门找菊，酒杯药碗都撂下。霜前月下是谁家种的？篱边又愁着什么？穿着木屐一路兴冲冲，边走边吟。菊花要是懂诗人，别辜负我杖头挂的酒钱。","典故":[{"原词":"蠟屐","解":"《世说新语》阮孚爱屐，亲手给木屐上蜡，指雅人出游"},{"原词":"掛杖頭","解":"《世说新语》阮修出门把百钱挂杖头，到酒店独饮"},{"原词":"黃花","解":"菊的别称，《礼记·月令》「鞠有黄华」"}],"情绪":["闲适","明快","雅趣"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-zhong":{"题":"種菊","串讲":"扛着锄头从别处移菊来，篱边庭前一棵棵栽好。没想到一夜雨就活了，今早还顶着霜开花。对着它吟诗喝酒，浇水封泥勤照看，小路从此不染尘。","典故":[{"原词":"醉酹寒香","解":"酹是洒酒敬奠，对菊洒酒；菊与酒相伴，自陶渊明起"},{"原词":"昨夜不期經雨活","解":"书里第38回宝玉自辩「昨夜雨」「今朝霜」，怨自己又落第"}],"情绪":["闲适","明快"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-dui":{"题":"對菊","串讲":"移来的菊比金子还贵，一丛浅一丛深。她光着头坐在篱边，抱膝在冷香里吟诗。数来数去，比你更傲的没有，懂你的只有我。秋光快，对着它要珍惜每一刻。","典故":[{"原词":"科頭","解":"不戴冠帽、露着发髻，形容随意不拘礼"},{"原词":"惜寸陰","解":"《晋书·陶侃传》「大禹圣者，乃惜寸阴」"},{"原词":"抱膝吟","解":"书里第38回李纨笑湘云「科头坐」「抱膝吟」，菊花也要腻烦"}],"情绪":["孤高","明快","雅趣"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-gong":{"题":"供菊","串讲":"弹琴喝酒有菊作伴，案上一枝亭亭的。隔座闻到三径的露香，放下书对着这一枝秋。纸帐里做新梦，又想起冷园斜阳下的旧游。它傲世，是跟我气味相投。","典故":[{"原词":"三徑","解":"陶渊明《归去来兮辞》「三径就荒，松菊犹存」，指隐者园中小路"},{"原词":"彈琴酌酒","解":"陶渊明蓄一张无弦琴，酒后抚弄寄意，见《宋书》"},{"原词":"拋書人對一枝秋","解":"书里第38回黛玉夸这句「已经妙绝」"}],"情绪":["雅趣","孤高","闲适"],"情绪组":"幽静","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-ying":{"题":"菊影","串讲":"菊影一层层，悄悄在小径上挪动。窗外疏灯描出远近，篱缝筛下碎月光。影子留得住魂，霜印却像一场空梦。小心别踩碎这暗香，醉眼里谁还认得清。","典故":[{"原词":"三徑","解":"陶渊明「三径就荒，松菊犹存」，指种菊的小路"},{"原词":"暗香","解":"借林逋咏梅「暗香浮动月黄昏」，挪来写菊影"}],"情绪":["清冷","旖旎","怅惘"],"情绪组":"夜","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-zan":{"题":"簪菊","串讲":"天天忙着养菊，今儿折一枝插头上，别当是照镜子梳妆。古人爱花爱成癖、爱酒成狂，鬓边沾露、头巾染霜。这份清高俗人看不懂，由他们在路边拍手笑去。","典故":[{"原词":"長安公子","解":"一般认为指杜牧，长安人，有「菊花须插满头归」"},{"原词":"彭澤先生","解":"陶渊明做过彭泽令，爱菊嗜酒"},{"原词":"葛巾","解":"陶渊明曾用头上葛巾滤酒，滤完照旧戴上，见《宋书》"}],"情绪":["豪迈","孤高","诙谐"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"指导§18"},"ju-can":{"题":"殘菊","串讲":"露浓霜重，菊枝慢慢歪倒，赏花的日子刚过小雪。花蒂还有余香，叶子已稀稀落落。月落床头虫声病，寒云万里雁来迟。末了反来安慰：明年秋风再见，别想。","典故":[{"原词":"小雪","解":"二十四节气之一，在立冬后，菊到这时已残"},{"原词":"金淡泊","解":"书里第38回宝玉把「金淡泊」「翠离披」列进自己比不上的好句"}],"情绪":["怅惘","清冷","哀婉"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"指导§18"},"wumei-xi":{"题":"西施","串讲":"倾国倾城的西施随浪花去了，吴宫里空留回忆。别笑那学她皱眉的东村丑女，人家白了头还在溪边安安稳稳洗纱。反着写：美人命短，不如平凡人。","典故":[{"原词":"效顰","解":"《庄子·天运》东施学西施捧心皱眉，越学越丑"},{"原词":"浣紗","解":"西施本是越国苎萝村女子，在溪边洗纱"},{"原词":"吳宮","解":"越国把西施献给吴王夫差，住在吴宫"}],"情绪":["哀婉","自伤"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"wumei-yu":{"题":"虞姬","串讲":"乌骓在夜风里嘶鸣，虞姬含恨对着项羽。黥布彭越降汉，后来照样被剁成肉酱；还不如她在楚营帐中一剑了断，干干净净。痛在这份刚烈。","典故":[{"原词":"烏騅","解":"项羽的骏马，垓下歌「时不利兮骓不逝」"},{"原词":"重瞳","解":"《史记》说项羽眼有双瞳，这里指项羽"},{"原词":"黥彭","解":"黥布、彭越背楚投汉，后被刘邦所杀，彭越被醢成肉酱"},{"原词":"飲劍","解":"相传垓下被围，虞姬在帐中自刎"}],"情绪":["悲愤","坚贞","哀婉"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"wumei-ming":{"题":"明妃","串讲":"王昭君美得惊人，走出汉宫远嫁，红颜薄命自古一样。她不骂画工，偏问皇帝：你就算不看重美色，生杀予夺的大权，怎能交给一个画匠？矛头直指君王。","典故":[{"原词":"漢宮","解":"王昭君本是汉元帝宫人，后出塞嫁匈奴呼韩邪单于"},{"原词":"畫工","解":"《西京杂记》宫人贿画工毛延寿，昭君不肯，被画丑"},{"原词":"君王縱使輕顏色","解":"书里第64回宝钗引王安石「当时枉杀毛延寿」，赞这首别开生面"}],"情绪":["悲愤","哀婉"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"wumei-lu":{"题":"綠珠","串讲":"石崇把明珠瓦砾一样随手乱抛，哪里真珍重过绿珠？他不过前生修来傻福气，临死还有绿珠跳楼相随，替他解了寂寞。替绿珠不值。","典故":[{"原词":"石尉","解":"石崇，西晋巨富，做过卫尉，绿珠是他的宠妾"},{"原词":"明珠","解":"相传石崇用三斛珍珠买下绿珠"},{"原词":"同歸","解":"石崇被捕，绿珠说「当效死于官前」，坠楼而死，见《晋书》"}],"情绪":["悲愤","哀婉"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"wumei-hong":{"题":"紅拂","串讲":"李靖见杨素只作个长揖，侃侃而谈，红拂一眼认出这落魄人是英雄，连夜投奔。杨素府里不过一具还剩口气的尸首，哪拴得住这位女丈夫。五首里最扬眉的一首。","典故":[{"原词":"楊公","解":"隋朝权臣杨素，红拂原是他府中执拂的侍女"},{"原词":"屍居餘氣","解":"《虬髯客传》红拂说「杨司空尸居余气，不足畏也」"},{"原词":"長揖","解":"李靖以布衣见杨素，只拱手长揖不下拜"}],"情绪":["豪迈","孤高"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"tipa":{"题":"題帕三絕","串讲":"宝玉挨打后让晴雯送去两条旧帕子，黛玉懂了他的意思，又喜又悲，掌灯就在帕上写了三首：泪为谁流，擦也擦不干，问窗前竹子认不认这泪痕。","典故":[{"原词":"鮫鮹","解":"传说海中鲛人织的薄绡，这里指宝玉送的手帕"},{"原词":"拋珠滾玉","解":"传说鲛人哭泣，眼泪化成珍珠"},{"原词":"湘江舊跡","解":"娥皇女英哭舜，泪洒湘竹成斑；探春因此号她潇湘妃子"},{"原词":"千竿竹","解":"潇湘馆的竹子，书里第十七回写「千百竿翠竹遮映」"}],"情绪":["哀婉","思念","自伤"],"情绪组":"哀婉","诗笺":"旧绢帕","诗笺依据":"原著：第34回「便向那兩塊舊帕子上走筆寫道」"},"liuxu-dai":{"题":"唐多令·柳絮","串讲":"柳絮一团团飘着，她看成了自己：漂泊、命薄、没人收，青春白了头。末两句最狠，嫁给东风，春也不管，只能由它去。难怪众人说太作悲。","典故":[{"原词":"百花州","解":"姑苏有百花洲，黛玉老家正是苏州，起笔就落在故乡。"},{"原词":"燕子樓","解":"唐代关盼盼在徐州燕子楼独守十余年，借来写人去楼空。"},{"原词":"嫁與東風","解":"化自李贺「嫁与春风不用媒」，落花随风去，没人做主。"}],"情绪":["哀婉","自伤"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"指导§18"},"liuxu-chai":{"题":"臨江仙·柳絮","串讲":"人人写柳絮都写飘零，她偏要说好：东风里舞得匀，不随水去不落尘，就算无根，借一阵好风也能上青云。翻得有气力，众人推为第一。","典故":[{"原词":"白玉堂","解":"古乐府有「白玉为君堂」，指富贵人家的厅堂。"},{"原词":"本無根","解":"书里第七十回她自己说柳絮「輕薄無根無絆」，这句当面翻案。"},{"原词":"委芳塵","解":"委身尘土，古诗写落花常用，她偏说柳絮不必如此。"}],"情绪":["明快","豪迈"],"情绪组":"闲适","诗笺":"淡青薛涛笺","诗笺依据":"指导§18"},"pangxie":{"题":"螃蟹詠","串讲":"桂荫下举杯吃蟹，京城的馋嘴盼着重阳。表面咏蟹，句句骂人：横着走不认正道，壳里一肚子黑黄。下锅了还有什么用？只剩月下稻香。众人都说讽世太毒。","典故":[{"原词":"皮裡春秋","解":"《世说新语》评褚裒「皮里阳秋」，嘴上不说心里有褒贬"},{"原词":"無經緯","解":"蟹横行不走正道，讽为人不循规矩；书里第38回众人说讽世太毒"},{"原词":"重陽","解":"九月初九重阳节，正是持螯赏菊、蟹肥的时候"}],"情绪":["诙谐","悲愤","热闹"],"情绪组":"热闹","诗笺":"秋香笺","诗笺依据":"推断"},"haitang-xiangyun-1":{"题":"詠白海棠（其一）","串讲":"湘云来迟被罚和诗，嘴里说着话心里早和好了两首。头一首起得最响：神仙昨天才降到京城，种下一盆蓝田玉；偏爱冷，带着雨痕，幸有诗人吟个不倦。","典故":[{"原词":"藍田玉","解":"陕西蓝田出美玉，李商隐有「藍田日暖玉生煙」，这里比白海棠"},{"原词":"霜娥","解":"霜神青女与月中素娥，李商隐《霜月》「青女素娥俱耐冷」"},{"原词":"倩女亦離魂","解":"唐传奇《离魂记》倩娘魂随情人而去，元杂剧有《倩女离魂》"}],"情绪":["明快","雅趣"],"情绪组":"闲适","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"haitang-xiangyun-2":{"题":"詠白海棠（其二）","串讲":"第二首转了调：花太爱洁找不着伴，人一悲秋就断魂；烛泪滴干，帘子隔破月痕，心事想对嫦娥说，回廊空空，夜已昏了。爽快的湘云也写出了寂寞。","典故":[{"原词":"蘿薜","解":"女萝和薜荔，《楚辞·山鬼》「被薜荔兮帶女羅」"},{"原词":"悲秋","解":"宋玉《九辩》「悲哉秋之為氣也」，后来文人悲秋都从这里来"},{"原词":"嫦娥","解":"偷吃仙药奔月的仙子，独居广寒宫，借来说无人可诉"}],"情绪":["孤高","怅惘","清冷"],"情绪组":"夜","诗笺":"洒金粉笺","诗笺依据":"指导§18"},"liuxu-yun":{"题":"如夢令·柳絮","串讲":"暮春闲着没事，看柳花乱飞，随口填的小令。说柳絮像绣绒、像半帘香雾，惹得杜鹃啼、燕子妒；末了连喊两声且住，想把春天留下来。","典故":[{"原词":"鵑啼","解":"望帝魂化杜鹃，暮春啼到出血，向来是伤春的声音。"},{"原词":"繡絨殘吐","解":"书里第七十回她正是「因見柳花飄舞」才写这首，引出柳絮社。"}],"情绪":["明快","怅惘"],"情绪组":"闲适","诗笺":"淡青薛涛笺","诗笺依据":"指导§18"},"qimei-shi":{"题":"訪妙玉乞紅梅","串讲":"罚去栊翠庵讨梅回来，被姐妹催着一联联念。不要观音瓶里的露，只要月宫栏外那枝梅；挑着红雪出庵，衣上还沾着佛院的苔，又俏又带点禅气。","典故":[{"原词":"大士瓶中露","解":"观音大士净瓶里的杨枝甘露，扣着尼庵。"},{"原词":"嫦娥檻外梅","解":"嫦娥暗指妙玉；她自称「檻外人」，见书里第六十三回。"},{"原词":"蓬萊","解":"海上仙山，把栊翠庵说成仙境。"}],"情绪":["雅趣","诙谐"],"情绪组":"幽静","诗笺":"桃红笺","诗笺依据":"推断"},"liuxu-tan":{"题":"南柯子·柳絮","串讲":"探春只写了半首：柳丝空垂，绾不住，任它东西南北各分离。宝玉接下半：落了别惜，明春再见也隔着一年。一个说散，一个说等，都留不住。","典故":[{"原词":"也難綰繫也難羈","解":"古人折柳绾结送别，想留人；这里说柳丝连自己也系不住。"},{"原词":"一任東西南北各分離","解":"书里第五回探春判词「千里東風一夢遙」，后来远嫁，这句像预言。"}],"情绪":["怅惘","思念"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"指导§18"},"guihua-ci":{"题":"姽嫿詞","串讲":"替林四娘作的长歌：恒王爱武又爱色，教美女骑射；流寇一来王战死，满城将士保命，倒是她带姬妾上阵殉了。末了一问：满朝文武，不如闺中一个女子。","典故":[{"原词":"姽嫿","解":"宋玉《神女赋》「既姽婳于幽静兮」，形容女子娴静美好。"},{"原词":"林四娘","解":"清初传说人物，王士禛《池北偶谈》、蒲松龄《聊斋》都写过她。"},{"原词":"青州","解":"明代衡王封在青州，恒王的影子大约由此来。"},{"原词":"鮫鮹","解":"传说鲛人在水底织的绡，这里指她的手帕。"}],"情绪":["悲愤","豪迈"],"情绪组":"哀婉","诗笺":"冷金笺","诗笺依据":"推断"},"furong-lei":{"题":"芙蓉女兒誄","串讲":"第七十八回宝玉祭晴雯而作。先赞其品格、痛诉遭谗之冤，再写物在人亡的悲哀，继而以楚辞笔意招魂，终以怅望悲泣结束祭礼。","典故":[{"原词":"白帝宮中","解":"神话中主秋之神白帝的宫阙，诔文以之安顿晴雯之魂。"},{"原词":"葉法善","解":"唐代道士。传说他摄取李邕的魂魄，请其为自己的祖父书写碑文。"},{"原词":"李長吉","解":"唐代诗人李贺，字长吉。传说他临终时，有天上使者来召他，为天帝新建的白玉楼作记。"},{"原词":"長沙","解":"西汉贾谊被贬为长沙王太傅，此处借其遭遇比拟晴雯高洁而受屈。"}],"情绪":["哀婉","思念","悲愤"],"情绪组":"哀婉","诗笺":"月白笺","诗笺依据":"推断"},"dengmi-yingchun":{"题":"燈謎（算盤）","串讲":"谜底是算盘。有功没运也难逢，整天噼里啪啦乱响，只因阴阳数不同。贾政看了心里一沉：这是「打動亂如麻」，跟她后来的命一样拨不清。","典故":[{"原词":"陰陽數不同","解":"算盘梁上珠、梁下珠计数不同，旧说一阳一阴。"},{"原词":"紛紛亂","解":"书里第二十二回贾政暗想「迎春所作算盤，是打動亂如麻」。"}],"情绪":["怅惘","雅趣"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"dengmi-xichun":{"题":"燈謎（海燈）","串讲":"谜底是佛前海灯。不听菱歌听佛经，沉在黑海里，心里自有一点光。小小年纪写这个，贾政只觉一发清净孤独，后来她果然青灯古佛。","典故":[{"原词":"菱歌","解":"江南采菱女唱的歌，南朝乐府常写，指世俗欢乐。"},{"原词":"色相","解":"佛家语，指一切看得见的形貌，终归是空。"},{"原词":"大光明","解":"书里第五回她的判词「獨臥青燈古佛旁」，海灯就是那盏灯。"}],"情绪":["禅寂","清冷"],"情绪组":"幽静","诗笺":"洒金红笺","诗笺依据":"推断"},"dengmi-tanchun":{"题":"燈謎（風箏）","串讲":"谜底是风筝。清明孩子仰头看它飞，线一断就没了力气，可别对着东风怨别离。贾政嫌它飘飘浮荡，后来探春远嫁，正像断线的风筝。","典故":[{"原词":"清明","解":"清明前后放风筝，放到高处剪断线，叫放晦气。"},{"原词":"莫向東風怨別離","解":"书里第五回她的判词「清明涕送江邊望，千里東風一夢遙」。"},{"原词":"游絲一斷","解":"书里第七十回众人放风筝剪线，探春正要剪她的大凤凰。"}],"情绪":["怅惘","思念"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"dengmi-baochai":{"题":"燈謎（更香）","串讲":"谜底是更香，一寸寸烧着报时辰。不靠鸡人报晓，不用侍女添，日日焦首煎心。写得稳，可贾政越看越觉得不祥，不是长久福寿的样子。","典故":[{"原词":"朝罷誰攜兩袖煙","解":"化自杜甫「朝罢香烟携满袖」，写早朝归来衣上带香。"},{"原词":"雞人","解":"《周礼》里掌报晓的官，宫中靠他喊时辰。"},{"原词":"五夜","解":"一夜分五更，更香就是按更燃的香。"}],"情绪":["清冷","怅惘"],"情绪组":"夜","诗笺":"洒金红笺","诗笺依据":"推断"},"zhongqiu-lian":{"题":"中秋夜大觀園即景聯句（湘雲黛玉二十二韻）","串讲":"中秋夜，两个人躲到凹晶馆水边联诗。从满园灯火酒令一路联到更残人散，水里飞过一只白鹤，湘云得了鹤影，黛玉对出冷月葬花魂，冷到骨头里。","典故":[{"原词":"射覆","解":"古酒令，藏物让人猜，书里第六十二回宝玉生日也行过。"},{"原词":"藥經靈兔搗","解":"月中玉兔捣药的传说，下句接嫦娥奔广寒宫。"},{"原词":"乘槎待帝孫","解":"传说有人乘木筏上天河见织女，帝孙就是织女。"},{"原词":"寒塘渡鶴影","解":"书里第七十六回池里飞起一只白鹤，湘云借景得句。"}],"情绪":["清冷","哀婉","孤高"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"zhongqiu-miaoyu":{"题":"中秋聯句續（妙玉十三韻）","串讲":"妙玉嫌她俩联得太颓败，领回栊翠庵，一挥而就续完。从香炉、空帐写到天亮鸟啼、钟鸣鸡唱，把凄凉拉回来，末了说别喊累，烹茶再细论。","典故":[{"原词":"嫠婦泣","解":"化自苏轼《赤壁赋》「泣孤舟之嫠妇」，箫声惹寡妇哭。"},{"原词":"贔屭","解":"传说龙生九子之一，常驮石碑，这里指园中石刻。"},{"原词":"鐘鳴櫳翠寺","解":"栊翠庵是她自己修行的地方，钟声从那里来。"}],"情绪":["孤高","禅寂","清冷"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"luxue-lianju":{"题":"蘆雪广即景聯句（雪）","串讲":"雪天一群人围着火联句，凤姐一句一夜北风紧开头，往后你一句我一句抢着接，湘云抢得最凶。从村酒、梅笛写到扫雪烹茶，满纸是热闹的冷。","典故":[{"原词":"葭動灰飛管","解":"古人把芦苇灰放进律管，冬至一到灰便飞动，用来候节气。"},{"原词":"灞橋","解":"孟浩然雪天骑驴过灞桥寻梅，说诗思在风雪驴背上。"},{"原词":"撒鹽是舊謠","解":"谢家咏雪，谢朗说「撒盐空中差可拟」，不如谢道韫柳絮之比。"},{"原词":"簞瓢","解":"《论语》颜回一箪食一瓢饮，安贫乐道。"}],"情绪":["热闹","雅趣","明快"],"情绪组":"热闹","诗笺":"雪浪笺","诗笺依据":"推断"},"yucun-wulv":{"题":"中秋有懷（未卜三生願）","串讲":"第一回中秋，雨村念娇杏回顾，对月口占此律，写孤身未遇、相思难遣之情。","典故":[{"原词":"三生願","解":"佛教谓前生、今生、来生；此处指姻缘前定之愿"},{"原词":"蟾光","解":"月光。传说月中有蟾蜍，故以蟾代月"},{"原词":"玉人樓","解":"美人所居之楼；玉人指心中所慕的女子"}],"情绪":["思念","怅惘"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"yucun-yilian":{"题":"雨村吟對聯（玉在匵中）","串讲":"第一回雨村借玉钗自比：藏器待时，盼识者来求，一心只望腾达。","典故":[{"原词":"玉在匵中","解":"美玉藏于匣中，喻怀才待售"},{"原词":"釵於奩內","解":"金钗藏于妆奁，喻静待时机"},{"原词":"待時飛","解":"等待时机飞腾，喻求取功名"}],"情绪":["豪迈","孤高"],"情绪组":"幽静","诗笺":"素白竹纸","诗笺依据":"推断"},"yucun-zhongqiu":{"题":"中秋對月寓懷（時逢三五）","串讲":"第一回中秋，雨村借月自况：今朝清光护栏，来日高悬天际，万人仰看。","典故":[{"原词":"三五","解":"指农历十五，月圆之夜"},{"原词":"玉欄","解":"白玉栏杆，指华美楼台"},{"原词":"一輪","解":"一轮圆月，此指天上明月"}],"情绪":["豪迈","明快"],"情绪组":"夜","诗笺":"冷金笺","诗笺依据":"推断"},"haoliao-ge":{"题":"好了歌","串讲":"第一回跛足道人唱此，点化落魄的甄士隐：功名、金银、娇妻、儿孙，世人皆舍不下，终是一场空。","典故":[{"原词":"荒冢一堆","解":"荒坟一座，喻身后萧条冷落"},{"原词":"終朝","解":"整日，从早到晚"},{"原词":"神仙","解":"道教所称超脱生死、长生不死之人"}],"情绪":["禅寂","诙谐"],"情绪组":"哀婉","诗笺":"旧绢帕","诗笺依据":"推断"},"haoliao-zhu":{"题":"好了歌解注","串讲":"第一回末，甄士隐贫病落魄，听跛足道人唱「好了歌」，当场作注，用盛衰聚散把歌里的意思说透。","典故":[{"原词":"笏滿床","解":"笏板堆满床，指家中做官者众多"},{"原词":"強梁","解":"强横不法之人，此指做强盗"},{"原词":"膏粱","解":"肥肉精米，代指富贵人家"},{"原词":"作嫁衣裳","解":"替人做嫁衣，喻白白为他人辛苦"}],"情绪":["哀婉","怅惘","禅寂"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"seng-jie":{"题":"癩頭僧誡英蓮偈（慣養嬌生笑你痴）","串讲":"癞头僧见士隐抱着英莲，指他念这四句，笑的是父母娇养之痴，并预告元宵走失、家业成空。","典故":[{"原词":"菱花","解":"字面可指菱花镜；此处双关英莲，她后来名叫香菱。空对，谓这头姻缘落空。"},{"原词":"雪澌澌","解":"雪盛或雪落之声。雪谐「薛」，指薛蟠。香菱空对薛蟠，是遇人非偶。"},{"原词":"烟消火灭","解":"烟散火熄，指一家繁华败尽；也照应后来葫芦庙起火，延烧甄家。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"keqing-lingbie":{"题":"秦可卿臨別贈鳳姐語（三春過後）","串讲":"秦可卿托梦凤姐，临别赠此二句。春尽芳残，各寻门路，是劝凤姐早为贾府后事打算。","典故":[{"原词":"三春","解":"本可指春季三个月，也可指三个春天；此处兼有谶语意味，具体所指有不同解释，不宜坐实为三年。"},{"原词":"諸芳","解":"众花，借喻书中众多女子。"},{"原词":"各自門","解":"各自的归宿、门路。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"旧绢帕","诗笺依据":"推断"},"baoyu-qinfang-lian":{"题":"沁芳亭聯","串讲":"宝玉随贾政游园，为沁芳亭题此联。柳色映水，花香随流，紧扣亭名「沁芳」，写出临水景致。","典故":[{"原词":"三篙","解":"篙是撑船的长竿；这里借以形容水深，并非实指测得三根篙的深度。"},{"原词":"一脈","解":"一股相连的水流；这里写流水带着花香，连绵而来。"},{"原词":"繞堤","解":"环绕着堤岸。"}],"情绪":["闲适","雅趣"],"情绪组":"闲适","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"baoyu-xiaoxiang-lian":{"题":"瀟湘館聯","串讲":"宝玉题写竹院联语。茶闲烟绿，棋罢指凉，以烟色与指尖的凉意，写出环境的清幽闲雅。","典故":[{"原词":"寶鼎","解":"珍贵的鼎形香炉。"},{"原词":"茶閒","解":"饮茶之事暂歇，呈现闲静的情境。"},{"原词":"棋罷","解":"棋局已经结束。"}],"情绪":["清冷","闲适"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"},"baoyu-daoxiang-lian":{"题":"稻香村聯","串讲":"宝玉为稻香村题此联。浣葛、采芹取自《诗经》，写水绿云香、耕读之乐，正合村名。","典故":[{"原词":"浣葛","解":"洗葛布，用《诗经·葛覃》浣衣之意，指乡野劳作。"},{"原词":"採芹","解":"采水芹，用《诗经·泮水》「薄采其芹」，后指读书人。"},{"原词":"新漲","解":"新涨起来的水。"}],"情绪":["闲适","雅趣"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"推断"},"baoyu-hengwu-lian":{"题":"蘅蕪院聯","串讲":"宝玉题蘅蕪院之联，上句赞才思艳丽，下句写花下梦香，应和院中香草清幽。","典故":[{"原词":"荳蔻","解":"即豆蔻，一种芳香植物。杜牧《赠别》以「豆蔻梢头二月初」比喻少女年华；本联写吟咏豆蔻，并以花的绮丽映衬文才。"},{"原词":"酴醾","解":"即荼蘼，春末开花，有香气；本联借其花香写梦境。"}],"情绪":["雅趣","闲适"],"情绪组":"闲适","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"yuanchun-yinglian":{"题":"省親別墅聯（天地啟宏慈）","串讲":"元春省亲时为正殿题此联，赞颂皇恩广大、省亲恩典隆重，是庄重堂皇的颂圣联语。","典故":[{"原词":"赤子蒼頭","解":"赤子指百姓，蒼頭指仆役，合言各色人等。"},{"原词":"曠典","解":"罕见盛大的恩典，指省亲之典。"},{"原词":"九州萬國","解":"泛指普天之下、天下各国。"}],"情绪":["豪迈","明快"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"yuanchun-ti-daguanyuan":{"题":"題大觀園","串讲":"元春省亲题此绝句，前两句赞园景精巧、工程浩大，后两句总收诸景，点出「大观」园名。","典故":[{"原词":"銜山抱水","解":"以口衔山、以臂抱水，形容园林依山傍水之势。"},{"原词":"天上人間","解":"天上与人间，极言景致之美、无所不备。"},{"原词":"應錫","解":"锡，赐予；理应赐予。"}],"情绪":["明快","雅趣"],"情绪组":"热闹","诗笺":"冷金笺","诗笺依据":"推断"},"yingchun-kuangxing":{"题":"曠性怡情","串讲":"迎春奉元春之命题匾作诗，赞园景精奇，以「羞题」表示谦退，末两句反问写出游赏的惊叹与畅快。","典故":[{"原词":"曠怡","解":"即匾额「曠性怡情」，谓使心性开阔、情致愉悦。"},{"原词":"寧不","解":"岂不，反诘语气，加强肯定。"},{"原词":"奉命","解":"接受元春之命而题咏。"}],"情绪":["闲适","明快"],"情绪组":"闲适","诗笺":"素白竹纸","诗笺依据":"推断"},"tanchun-wanxiang":{"题":"萬象爭輝","串讲":"探春奉命题「万象争辉」，先赞园势雄伟，再自谦学识浅薄，末写精妙难以尽言、万物生辉，照应题意。","典故":[{"原词":"巍巍","解":"高大雄伟的样子。"},{"原词":"何慚","解":"此处有「可惭」「多惭」等异文，释义存在分歧；结合「学浅微」，宜保留自谦之意，不宜直接断言为「何必惭愧」。"},{"原词":"生光輝","解":"焕发光彩，照应匾额「万象争辉」。"}],"情绪":["明快","豪迈"],"情绪组":"热闹","诗笺":"洒金粉笺","诗笺依据":"推断"},"xichun-wenzhang":{"题":"文章造化","串讲":"惜春奉命题「文章造化」，以山水辽阔、楼台高耸写园势，再借日月光辉与天地造化赞美园景。","典故":[{"原词":"五雲中","解":"五色祥云，古人以为帝王或仙家气象。"},{"原词":"造化","解":"天地创造化育万物的力量。"},{"原词":"文章","解":"此处指错杂的色彩花纹，非文字篇章。"}],"情绪":["明快","雅趣"],"情绪组":"热闹","诗笺":"洒金粉笺","诗笺依据":"推断"},"liwan-wencai":{"题":"文采風流","串讲":"李纨题「文采风流」，铺写山水与歌舞意象，以珠玉比题咏、神仙比元春，末将名园写成凡人难至的仙境。","典故":[{"原词":"蓬萊","解":"传说中的海上仙山，用来衬托园林之美。"},{"原词":"湘裙","解":"此处指华美的裙子，不宜仅凭「湘」字断定其产地。"},{"原词":"瑤臺","解":"传说中神仙的居处。「下瑶台」写元春如仙人从仙境降临省亲。"},{"原词":"珠玉","解":"比喻精美的诗文，此处指园中题咏。"}],"情绪":["明快","热闹","雅趣"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"baochai-ningxi":{"题":"凝暉鍾瑞","串讲":"宝钗题「凝晖钟瑞」，借莺迁、凤至颂扬元春，继写文风与孝化，末赞元春才华，自谦不敢再作诗文。","典故":[{"原词":"遷鶯出谷","解":"化用《诗经·小雅·伐木》中鸟出幽谷、迁于乔木的意象，后常用来比喻地位上升。此处以黄莺出谷写元春的尊荣。"},{"原词":"鳳來儀","解":"语本《尚书·益稷》「凤凰来仪」，指凤凰来临而呈祥瑞之态；此处借指元春归省。"},{"原词":"宸游","解":"本指帝王巡游，此处借用尊贵称谓，指元春省亲。"},{"原词":"睿藻","解":"对帝王、后妃诗文的尊称，此处赞美元春的题咏。"}],"情绪":["明快","雅趣"],"情绪组":"热闹","诗笺":"冷金笺","诗笺依据":"推断"},"daiyu-shiwai":{"题":"世外仙源","串讲":"第十八回黛玉题「世外仙源」。她本欲大展奇才压众，却只得胡乱作一首应景；「仙境别红尘」写清幽，「金谷」「玉堂」颂省亲之盛。","典故":[{"原词":"紅塵","解":"佛道谓尘世、凡俗世间。"},{"原词":"金谷","解":"晋石崇金谷园，喻豪奢名园。"},{"原词":"玉堂","解":"华美殿堂，泛指富贵之所。"},{"原词":"恩寵","解":"帝王的恩遇宠爱。"}],"情绪":["明快","雅趣"],"情绪组":"闲适","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"baoyu-youfeng":{"题":"有鳳來儀","串讲":"第十八回宝玉题「有凤来仪」。以竹实待凤凰呼应匾额，继写青竹的色泽、凉意与枝笋，末联由竹影转入白日好梦。","典故":[{"原词":"鳳凰","解":"凤凰，祥瑞之鸟，此喻元春归省。"},{"原词":"秀玉","解":"秀美的竹，竹的美称。"},{"原词":"鼎香","解":"香炉中升起的熏香之气。"}],"情绪":["闲适","清冷","雅趣"],"情绪组":"幽静","诗笺":"素白竹纸","诗笺依据":"推断"},"baoyu-hengzhi":{"题":"蘅芷清芬","串讲":"第十八回宝玉题「蘅芷清芬」。诗写满苑香草与曲径回廊的幽翠，末联用谢灵运梦中得句的典故，将园景与诗思相连。","典故":[{"原词":"蘅蕪","解":"香草名；蘅芜苑的名称与园中所植香草相应，后来为宝钗居所。"},{"原词":"蘿薜","解":"女萝与薜荔，古诗中常并举的植物名称，常用来描写幽静的山林环境；女萝不宜直接等同于藤萝。"},{"原词":"池塘曲","解":"指咏池塘春草的诗句，用谢灵运「池塘生春草」的典故。"},{"原词":"謝家幽夢","解":"相传谢灵运梦见族弟谢惠连，得到「池塘生春草」的佳句，此处借用这一故事。"}],"情绪":["清冷","闲适","雅趣"],"情绪组":"幽静","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"baoyu-yihong":{"题":"怡紅快綠","串讲":"第十八回题咏大观园，宝玉为怡红院作诗。宝钗提醒他「绿玉」犯元春所改之题，遂改作「绿蜡」。芭蕉海棠一对，正合院中本色。","典故":[{"原词":"嬋娟","解":"姿态美好，此处以美人喻花木。"},{"原词":"綠蠟","解":"喻芭蕉，本唐钱珝「冷烛无烟绿蜡干」句。"},{"原词":"紅妝","解":"指海棠，以浓妆美人比拟。"},{"原词":"絳袖","解":"深红色衣袖，喻花叶低垂之态。"}],"情绪":["旖旎","闲适","雅趣"],"情绪组":"闲适","诗笺":"洒金红笺","诗笺依据":"推断"},"daiyu-xinglian":{"题":"杏簾在望","串讲":"第十八回题咏大观园，此首署宝玉之名，实黛玉代作。写稻香村田家风光，末联颂圣，元春独指为四诗之冠。","典故":[{"原词":"杏簾","解":"杏黄色的酒旗，用来招引饮酒的客人。「杏帘在望」是此处题额；元春读诗后将浣葛山庄改名稻香村。"},{"原词":"菱荇","解":"菱与荇菜，都是水生植物；菱角是菱的果实。"},{"原词":"桑榆","解":"桑树与榆树，此处写田家屋舍周围的树木。"},{"原词":"盛世無饑餒","解":"应制诗中的颂圣之辞，称颂太平年景没有饥饿之忧。"}],"情绪":["明快","闲适","雅趣"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"推断"},"baoyu-xu-zhuangzi":{"题":"續《南華經·胠篋》","串讲":"第二十一回，宝玉与袭人等闹了别扭，心绪烦乱，取《南华经·胠篋》来读，提笔续了一段。他把花、麝、钗、玉都看作缠陷人的罗网，只是一时负气。","典故":[{"原词":"焚花散麝","解":"花指袭人，麝指麝月，皆宝玉身边丫鬟。"},{"原词":"參商之虞","解":"参商二星此出彼没，喻彼此隔阂的忧患。"},{"原词":"張其羅","解":"张开罗网，喻设局缠陷人。"},{"原词":"靈竅","解":"灵性心窍，指人的聪明灵慧。"}],"情绪":["禅寂","悲愤","怅惘"],"情绪组":"夜","诗笺":"素白竹纸","诗笺依据":"推断"},"daiyu-ti-xuzhuang":{"题":"題續《莊子》","串讲":"第二十一回，黛玉读到宝玉续写的《庄子》，又气又笑，提笔题诗，讥讽他自己没有见识，却反过来怪罪别人。","典故":[{"原词":"南華","解":"《南华经》，即《庄子》，唐时封庄子为南华真人。"},{"原词":"莊子因","解":"书名，注解《庄子》之作，此代指《庄子》。"},{"原词":"弄筆","解":"提笔写字，此指宝玉续写文章。"},{"原词":"丑語","解":"难听的话，此指宝玉怪罪旁人的话。"}],"情绪":["诙谐","清冷"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"},"baoyu-ji":{"题":"寶玉參禪偈","串讲":"第二十二回，宝玉调解黛玉与湘云的矛盾不成，回房感忿写偈。黛玉续「无立足境，是方干净」，指出他仍有执着。","典故":[{"原词":"你證我證","解":"禅门参证之语，指彼此印证、互相勘验。"},{"原词":"斯可雲證","解":"斯，这；云，说。这样才称得上证悟。"},{"原词":"立足境","解":"立脚安身之处，此处指修行所依的境界。"}],"情绪":["禅寂","怅惘","自伤"],"情绪组":"幽静","诗笺":"素白竹纸","诗笺依据":"推断"},"baoyu-jishengcao":{"题":"寄生草","串讲":"二十二回，宝玉写罢偈子又填此曲。「肆行无碍」是他向往，「真无趣」是实情。受气之余借禅自宽，终是少年心事。","典故":[{"原词":"無我原非你","解":"可联系《庄子·齐物论》「非彼无我，非我无所取」理解，借你我相互依存的关系说人情纠葛。"},{"原词":"從他不解伊","解":"从，任凭；解，理解；伊，人称代词。这里表示任凭别人不理解，不再为此操心。"},{"原词":"肆行無礙","解":"随心而行，没有牵碍。"},{"原词":"親疏密","解":"指人与人之间亲近、疏远、密切的关系。"}],"情绪":["禅寂","怅惘","自伤"],"情绪组":"幽静","诗笺":"冷金笺","诗笺依据":"推断"},"dengmi-yuanchun":{"题":"燈謎（爆竹）","串讲":"二十二回元宵，元春自宫中传灯谜。爆竹一响即化灰，写物而藏谶意，读来心惊。","典故":[{"原词":"束帛","解":"捆扎成束的绢帛，形容爆竹的外形。"},{"原词":"妖魔","解":"传说中害人的鬼怪，此处泛指邪祟。"},{"原词":"化灰","解":"烧成灰烬，喻声势过后一场空。"}],"情绪":["热闹","怅惘"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"dengmi-jiahuan":{"题":"燈謎（枕頭與獸頭）","串讲":"第二十二回，元春未猜出贾环的灯谜，命太监带回询问。众人看后大笑，贾环说明谜底是枕头和兽头。","典故":[{"原词":"房上蹲","解":"指安在屋顶上的兽头装饰。"},{"原词":"床上坐","解":"指放在床上的枕头。"},{"原词":"有角","解":"枕头两端各有四角，合为八角；屋顶兽头有两根角，分别扣合谜面。"}],"情绪":["诙谐","热闹"],"情绪组":"热闹","诗笺":"秋香笺","诗笺依据":"推断"},"dengmi-jiazheng-lizhi":{"题":"燈謎（荔枝）","串讲":"第二十二回，贾母出谜，贾政猜谜。「立枝」的「立」谐「荔」，扣「荔枝」。贾政故意先猜错，逗贾母高兴。","典故":[{"原词":"站樹梢","解":"站在树枝上，可说「立枝」；「立」与「荔」谐音，扣谜底「荔枝」。"},{"原词":"身輕","解":"身体轻捷灵便。"},{"原词":"打一果名","解":"灯谜用语，提示谜底是一种果实的名称。"}],"情绪":["闲适","诙谐"],"情绪组":"闲适","诗笺":"月白笺","诗笺依据":"推断"},"dengmi-jiazheng-yan":{"题":"燈謎（硯臺）","串讲":"贾政出谜让贾母猜，以端正坚硬写砚台形质，以供墨助笔暗扣「有言必应」，谜底是砚台。","典故":[{"原词":"端方","解":"端正、方正，这里写砚台的形体，也可使人联想到端方的品性。"},{"原词":"堅硬","解":"质地坚实，这里写砚台的材质。"},{"原词":"有言必應","解":"表面说有话便回应，谜中「必」字隐「笔」字，借砚台供墨给笔、帮助书写的用途扣住谜底。"}],"情绪":["孤高","清冷"],"情绪组":"幽静","诗笺":"素白竹纸","诗笺依据":"推断"},"laitou-shi-1":{"题":"僧誦通靈寶玉詩（天不拘兮）","串讲":"第二十五回癞头和尚对通灵宝玉念此诗，追说石头昔日无喜无悲，通灵入世后却卷入尘世纷扰。","典故":[{"原词":"不羈","解":"不受约束羁绊，写石头本来的自在无碍。"},{"原词":"鍛煉通靈","解":"指石头经锻炼而通灵性，即通灵宝玉之由来。"},{"原词":"覓是非","解":"寻求是非，指石头入世招惹尘世纷扰。"}],"情绪":["禅寂","怅惘"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"},"laitou-shi-2":{"题":"僧誦通靈寶玉詩（粉漬脂痕）","串讲":"和尚借脂粉、闺阁与鸳鸯写情爱牵缠，再以梦醒、偿债、散场点出尘缘终有尽时。","典故":[{"原词":"粉漬脂痕","解":"胭脂香粉的渍迹，喻世俗情爱的沾染。"},{"原词":"綺櫳","解":"雕饰华美的窗棂，代指富丽的闺阁。"},{"原词":"冤孽","解":"冤仇罪孽，指前世今生牵缠的因果。"}],"情绪":["旖旎","哀婉"],"情绪组":"哀婉","诗笺":"冷金笺","诗笺依据":"推断"},"jiuling-baoyu":{"题":"女兒悲愁喜樂（寶玉酒令）","串讲":"第28回冯紫英席上行女儿酒令，宝玉按悲愁喜乐各作一句，写闺中寂寞悔怨与晨妆秋千之乐，见其体贴女儿之心。","典故":[{"原词":"守空閨","解":"独守空房，指女子青春虚度、无人相伴。"},{"原词":"覓封侯","解":"求取封侯的功名。唐人闺怨诗有「悔教夫婿觅封侯」之句。"},{"原词":"鞦韆","解":"即秋千，古代女子春日嬉戏的器具。"}],"情绪":["旖旎","哀婉"],"情绪组":"热闹","诗笺":"桃红笺","诗笺依据":"推断"},"hongdou-qu":{"题":"紅豆曲","串讲":"第28回宝玉行酒令后唱此曲，用「滴不尽」「开不完」等叠句排比写相思绵绵，句句儿女情长，见其多情。","典故":[{"原词":"紅豆","解":"相思子，古人以喻相思。唐王维诗有「红豆生南国」。"},{"原词":"玉粒金蓴","解":"精美的饭食。莼即莼菜，玉粒金莼指珍馐。"},{"原词":"菱花鏡","解":"背面铸菱花图案的铜镜，泛指镜子。"},{"原词":"更漏","解":"古代的计时器具，借指夜里的时辰。"}],"情绪":["哀婉","思念","怅惘"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"jiuling-fengziying":{"题":"女兒悲愁喜樂（馮紫英酒令）","串讲":"第二十八回冯紫英席上行令，四句分说女儿悲愁喜乐，直白粗率，末句掏蟋蟀带顽笑，见武家子弟凑趣光景。","典故":[{"原词":"兒夫","解":"妻子称丈夫为儿夫，旧时曲白常用。"},{"原词":"梳妝樓","解":"女子梳妆的楼阁，诗中常指闺房。"},{"原词":"雙生子","解":"一胎所生的两个孩子，即双胞胎。"},{"原词":"蟋蟀","解":"即促织，秋虫，旧时有人斗蟋蟀取乐。"}],"情绪":["诙谐","热闹"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"qu-fengziying":{"题":"酒曲（你是個可人）","串讲":"第二十八回冯紫英席上唱的时新曲，连用四个「你是个」夸人，末句赌气叫她背地里打听，直白热辣，是行令凑趣的情歌。","典故":[{"原词":"可人","解":"称心可爱的人。"},{"原词":"刁鑽古怪","解":"机灵古怪，爱耍花招。"},{"原词":"鬼靈精","解":"机灵刁巧的人，多含爱昵意。"},{"原词":"背地裡","解":"背后，私下里。"}],"情绪":["旖旎","诙谐"],"情绪组":"热闹","诗笺":"桃红笺","诗笺依据":"推断"},"jiuling-yuner":{"题":"女兒悲愁喜樂（雲兒酒令）","串讲":"第二十八回云儿席上行令，写终身归宿与妈妈打骂之忧，又写情郎留恋、停管弄弦之乐，内容贴合她的行院身份。","典故":[{"原词":"終身","解":"指女子一生的婚姻归宿。"},{"原词":"媽媽","解":"行院中称鸨母为妈妈。"},{"原词":"簫管","解":"箫与管，泛指管乐器。"},{"原词":"弦索","解":"弦乐器，如琵琶、三弦。"}],"情绪":["哀婉","自伤"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"qu-yuner":{"题":"酒曲（荳蔻開花）","串讲":"第二十八回云儿席上唱的时新小曲，借豆蔻开花、虫儿钻花打双关，是行院俚曲，俏皮热闹，正合行令取乐。","典故":[{"原词":"荳蔻","解":"即豆蔻，花名，诗词中常喻少女。"},{"原词":"三月三","解":"农历三月初三，旧时上巳节，正当春时。"},{"原词":"打鞦韆","解":"荡秋千，这里指虫儿在花上摇晃。"},{"原词":"小心肝","解":"对心爱之人的昵称。"}],"情绪":["诙谐","旖旎"],"情绪组":"热闹","诗笺":"洒金粉笺","诗笺依据":"推断"},"qu-yuner-2":{"题":"酒曲（兩個冤家）","串讲":"第二十八回云儿应薛蟠要求弹唱此曲。曲中人难舍两个情人，叙私会被撞破、当面对质而无言辩解的窘态。","典故":[{"原词":"冤家","解":"旧时对情人的昵称，爱极反称冤家。"},{"原词":"幽期","解":"男女私下的约会。"},{"原词":"荼縻架","解":"荼蘼花架，荼蘼春末开花。"},{"原词":"三曹對案","解":"原告、被告与证人当面对质。"}],"情绪":["旖旎","诙谐"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"jiuling-jiangyuhan":{"题":"女兒悲愁喜樂（蔣玉菡酒令）","串讲":"第二十八回蒋玉菡席上行令，分别写丈夫不归、无钱买发油的悲愁，以及灯花报喜、夫妻和合的喜乐。","典故":[{"原词":"桂花油","解":"旧时妇女梳头用的香发油。"},{"原词":"燈花","解":"灯芯结花，旧俗以为喜兆。"},{"原词":"夫唱婦隨","解":"成语，谓夫妇和睦相从。"}],"情绪":["明快","旖旎"],"情绪组":"热闹","诗笺":"桃红笺","诗笺依据":"推断"},"qu-jiangyuhan":{"题":"酒曲（可喜你天生成百媚嬌）","串讲":"第二十八回蒋玉菡席上所唱小曲，先赞女子娇媚年少、鸾凤相配，再以银河、谯鼓、银灯写夜间同入鸳帏的情景。","典故":[{"原词":"碧霄","解":"碧空，指天上。"},{"原词":"鸞鳳","解":"鸾鸟与凤凰，喻美满夫妻。"},{"原词":"譙樓","解":"城门上的望楼，其上鼓声报时。"},{"原词":"鴛幃","解":"绣有鸳鸯的帐子，指卧帐。"}],"情绪":["旖旎","明快"],"情绪组":"夜","诗笺":"洒金红笺","诗笺依据":"推断"},"pangxie-baoyu":{"题":"螃蟹詠（寶玉）","串讲":"第38回螃蟹宴上宝玉所作。持螯泼醋写席上馋相，末借东坡「为口忙」自嘲，见其富贵闲人的贪玩心性。","典故":[{"原词":"持螯","解":"晋人毕卓持蟹螯下酒的典故，后指吃蟹。"},{"原词":"無腸","解":"蟹别名「无肠公子」，出《抱朴子》。"},{"原词":"坡仙","解":"指苏轼，号东坡，有「自笑平生为口忙」句。"},{"原词":"饕餮","解":"古代贪食的恶兽，喻贪吃之人。"}],"情绪":["诙谐","闲适"],"情绪组":"热闹","诗笺":"冷金笺","诗笺依据":"推断"},"pangxie-daiyu":{"题":"螃蟹詠（黛玉）","串讲":"第38回黛玉所作。先写蟹的甲戈之形，再写肉嫩黄香、食蟹饮酒之趣，末以桂风菊霜收束，添入清雅秋意。","典故":[{"原词":"鐵甲","解":"蟹壳坚硬如铁甲。"},{"原词":"長戈","解":"蟹的双螯似长戈。"},{"原词":"八足","解":"蟹有八足，句中以「卿」称之，是拟人。"},{"原词":"千觴","解":"觞为古代酒杯，千觞指痛饮。"}],"情绪":["雅趣","清冷"],"情绪组":"闲适","诗笺":"秋香笺","诗笺依据":"推断"},"xiangling-yongyue-1":{"题":"詠月（其一）","串讲":"第48回香菱初作咏月诗，写月色与赏月感受，多用玉镜、冰盘等熟喻。黛玉评其有意思而措词不雅，劝她多读诗后重作。","典故":[{"原词":"玉鏡","解":"喻圆月，皎洁如镜。"},{"原词":"冰盤","解":"喻圆月，清冷如冰盘。"},{"原词":"野客","解":"山野之人，与上句「诗人」对举。"}],"情绪":["清冷","雅趣"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"xiangling-yongyue-2":{"题":"詠月（其二）","串讲":"第48回香菱第二次作咏月诗，以银、水、粉、霜等描摹月色。黛玉认为仍不好，指出其过于穿凿，劝她放开胆子再作。","典故":[{"原词":"玉盤","解":"玉制的盘子，古诗中常用来比喻圆月。"},{"原词":"金砌","解":"华美台阶的美称。砌，这里指台阶。"},{"原词":"玉欄","解":"玉石栏杆，也可用作栏杆的美称。"},{"原词":"西樓","解":"西边的楼阁，这里是梦醒后看月的地点，诗中未交代居住者的身份。"}],"情绪":["清冷","怅惘","雅趣"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"xiangling-yongyue-3":{"题":"詠月（其三）","串讲":"香菱第三首咏月诗，以砧声、鸡唱、江上绿蓑与楼头红袖拓展月夜意境，末借嫦娥之问寄托团圆之愿，获众人称赞。","典故":[{"原词":"砧敲","解":"捣衣石上捶衣，声起秋夜，古人多以之写思妇怀远。"},{"原词":"五更","解":"夜里第五更，天将明之时。"},{"原词":"綠蓑","解":"绿色蓑衣，指江上渔人或行人。"},{"原词":"嫦蛾","解":"即嫦娥，月中仙女。"}],"情绪":["清冷","思念","怅惘"],"情绪组":"夜","诗笺":"秋香笺","诗笺依据":"推断"},"hongmei-xiuyan":{"题":"詠紅梅花得「紅」字","串讲":"岫烟得「红」字咏红梅，先写冲寒早开，再用庾岭、罗浮及仙女意象点染花色，末写冰雪中自在开放，表现其不随俗的风姿。","典故":[{"原词":"庾嶺","解":"大庾岭，又称梅岭，以梅花著称。诗中借此引出梅花，并以春色联想点染红梅。"},{"原词":"羅浮","解":"罗浮山。传说赵师雄在此梦遇淡妆素服的美人，醒后才知身在梅树下，后世常以此咏梅。"},{"原词":"綠萼","解":"绿萼梅，花萼绿色、花瓣洁白；古人又将它比作仙女萼绿华。此处以添红妆的仙女形象比拟红梅。"},{"原词":"縞仙","解":"白衣仙子，常用来比喻白梅。这里借醉后泛红的容颜点染红梅之色；缟是白色生绢。"}],"情绪":["孤高","坚贞","清冷"],"情绪组":"幽静","诗笺":"洒金红笺","诗笺依据":"推断"},"hongmei-liwen":{"题":"詠紅梅花得「梅」字","串讲":"李纹以「梅」字为韵咏红梅，借血痕、心灰及换骨脱胎的想象写其形色，末劝蜂蝶莫疑，意在申明红梅虽艳，仍有梅的品格。","典故":[{"原词":"醉眼","解":"带醉的眼睛，此写红梅先迎人醉眼而开。"},{"原词":"丹藥","解":"道士所炼丹药，此指红梅如仙换骨。"},{"原词":"瑤池","解":"西王母所居仙境，此喻红梅来处非凡。"},{"原词":"蜂蝶","解":"蜂与蝶，古诗中常喻寻芳之人。"}],"情绪":["旖旎","雅趣","坚贞"],"情绪组":"热闹","诗笺":"桃红笺","诗笺依据":"推断"},"hongmei-baoqin":{"题":"詠紅梅花得「花」字","串讲":"宝琴以「花」字为韵咏红梅，用春妆、落霞写艳色，以笛声、仙槎写幽香清韵，末说红梅本是瑶台仙种，不必因红白之别而疑其品格。","典故":[{"原词":"曲檻","解":"曲折的栏杆。槛，栏杆。"},{"原词":"遊仙","解":"游历仙境。此句把红梅想象成乘木筏游于天河的仙人，并非专指游仙诗这一诗体。"},{"原词":"絳河","解":"银河、天河。「绛」字又与红梅的颜色相映。"},{"原词":"瑤臺","解":"神话中神仙的居处，此喻红梅来历非凡。"}],"情绪":["雅趣","明快","旖旎"],"情绪组":"幽静","诗笺":"洒金粉笺","诗笺依据":"推断"},"dengmi-xiangyun":{"题":"燈謎（耍的猴兒）","串讲":"湘云以《点绛唇》咏供人戏耍的猴儿，末句借「后事难继」暗扣断尾。宝玉猜中，湘云随后解释谜底。","典故":[{"原词":"溪壑","解":"山溪与沟壑，指猴子原本栖居的山林。"},{"原词":"紅塵","解":"尘世、繁华人间。"},{"原词":"名利猶虛","解":"名利终归虚幻。"}],"情绪":["自伤","怅惘"],"情绪组":"哀婉","诗笺":"洒金粉笺","诗笺依据":"推断"},"dengmi-baochai-50":{"题":"燈謎（梵鈴聲）","串讲":"此谜作者是宝钗。所咏之物层叠如雕刻，却出于天然，又似塔而无铃声。原著未揭底，旧评有猜松球的说法。","典故":[{"原词":"鏤檀鍥梓","解":"雕刻檀木与梓木；檀、梓皆美材。"},{"原词":"良工","解":"技艺高超的工匠。"},{"原词":"梵鈴","解":"佛寺塔檐所悬风铃；梵指佛门。"}],"情绪":["清冷","禅寂"],"情绪组":"幽静","诗笺":"冷金笺","诗笺依据":"推断"},"dengmi-baoyu-50":{"题":"燈謎（寶玉）","串讲":"宝玉以天上人间、竹与声息设谜，末以叹息回应上天。原著未揭底，旧评有猜风筝琴的说法，具体扣法仍有歧解。","典故":[{"原词":"琅玕","解":"本指美石，也可借指美竹；此处通常释为竹。「琅玕节过」的具体谜意有不同解释。"},{"原词":"鸞音鶴信","解":"字面指鸾鹤的声息、消息，在谜面中构成来自空中的音讯意象，不宜直接认定为鸾鹤传书的固定典故。"},{"原词":"凝睇","解":"凝神注视。睇，读 dì。"},{"原词":"上蒼","解":"上天、苍天。"}],"情绪":["怅惘","思念"],"情绪组":"夜","诗笺":"月白笺","诗笺依据":"推断"},"dengmi-daiyu":{"题":"燈謎（黛玉）","串讲":"黛玉的物谜借骏马奔驰与鳌背三山设线索。原著未揭底，旧评有猜走马灯的说法，不宜径认作黛玉以良马自况。","典故":[{"原词":"騄駬","解":"读 lù ěr，骏马名，也写作「绿耳」，相传为周穆王八骏之一。"},{"原词":"紫繩","解":"紫色绳索，此处用于系马的设问。"},{"原词":"鰲背三山","解":"用巨鳌负载海上神山的传说。元宵堆叠彩灯而成的灯山也称鳌山，因此在此谜中还可联系灯山理解。"}],"情绪":["孤高","豪迈"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"huaigu-01":{"题":"赤壁懷古其一","串讲":"第51回宝琴怀古绝句之一，咏赤壁战事。写沉埋空舟、悲风英魂，苍凉悲慨。","典故":[{"原词":"赤壁","解":"地名，三国时周瑜破曹操处。"},{"原词":"喧闐","解":"喧闹、声响嘈杂。阗，读 tián。"},{"原词":"一炬","解":"一把火，指赤壁火攻。"},{"原词":"英魂","解":"英雄的魂魄。"}],"情绪":["悲愤","怅惘"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"huaigu-02":{"题":"交趾懷古其二","串讲":"宝琴《交趾怀古》，咏马援平定交趾、声威播于海外。第五十一回她拿出十首怀古绝句，此其二，笔下有汉代扬威的豪气。","典故":[{"原词":"金鏞","解":"大钟，古乐器，此处喻振起纲纪的军威。"},{"原词":"戎羌","解":"古代西北少数民族，泛指边地异族。"},{"原词":"馬援","解":"东汉伏波将军，曾平定交趾、立铜柱。"},{"原词":"子房","解":"张良的字，汉初谋臣。"}],"情绪":["豪迈","明快"],"情绪组":"热闹","诗笺":"洒金红笺","诗笺依据":"推断"},"huaigu-03":{"题":"鍾山懷古其三","串讲":"宝琴怀古绝句之三，借钟山隐者出山的故事，讥讽隐仕反复、名利难断，末句以劝诫口吻收束。","典故":[{"原词":"名利","解":"名誉与利益。"},{"原词":"被詔","解":"接到诏书，指应召出仕。"},{"原词":"凡塵","解":"尘世、人间，含佛道意味。"},{"原词":"牽連","解":"牵连纠葛，指人事牵绊。"}],"情绪":["诙谐","怅惘"],"情绪组":"幽静","诗笺":"素白竹纸","诗笺依据":"推断"},"huaigu-04":{"题":"淮陰懷古其四","串讲":"宝琴《淮阴怀古》咏韩信受辱、封齐、报漂母一饭之恩。第五十一回怀古之四，寄慨功名难料，末句见其知恩。","典故":[{"原词":"三齊","解":"指齐地。项羽曾将齐地分为齐、济北、胶东三国，故有此称；诗中「三齐位」指韩信的齐王之位。"},{"原词":"一飯之恩","解":"指漂母给贫困中的韩信饭食，韩信后来报答她的故事。"},{"原词":"惡犬","解":"凶恶的狗，诗中借指欺凌壮士的恶人。"},{"原词":"蓋棺","解":"盖上棺盖，指死亡。本句把封齐与最终身死联系起来，意在说显赫之时已埋下祸根。"}],"情绪":["哀婉","悲愤"],"情绪组":"哀婉","诗笺":"旧绢帕","诗笺依据":"推断"},"huaigu-05":{"题":"廣陵懷古其五","串讲":"宝琴怀古绝句之五，以蝉鸣鸦栖起笔，问隋堤近况，继而写「风流」名号招来纷纷议论，语带讥讽。","典故":[{"原词":"隋堤","解":"隋炀帝开运河所筑长堤，植柳成景。"},{"原词":"風流","解":"此处指风流韵事、风月名声。"},{"原词":"口舌","解":"口舌是非，指纷纷议论。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"huaigu-06":{"题":"桃葉渡懷古其六","串讲":"宝琴怀古绝句之六，借桃枝桃叶分离写离别，感叹六朝人物也多有此憾，以壁上空悬的小像收束。","典故":[{"原词":"桃葉","解":"指王献之爱妾桃叶，桃叶渡因此得名。"},{"原词":"六朝","解":"指建都金陵的东吴、东晋、宋、齐、梁、陈。"},{"原词":"梁棟","解":"房屋大梁，喻栋梁之才。"},{"原词":"小照","解":"人物小像、画像。"}],"情绪":["哀婉","思念"],"情绪组":"幽静","诗笺":"桃红笺","诗笺依据":"推断"},"huaigu-07":{"题":"青冢懷古其七","串讲":"借昭君出塞写悲怨，前两句写黑水与琵琶声，后两句讥叹汉廷制度和无用之人；同时以怀古寄托物谜。","典故":[{"原词":"黑水","解":"指今呼和浩特一带的大黑河，与昭君墓的传说相联系，诗中用来写塞外的悲凉。"},{"原词":"冰弦","解":"丝弦的美称，名称与传说中的冰蚕丝有关；此处借指琵琶弦，用昭君弹琵琶寄托愁怨的传说。"},{"原词":"樗櫟","解":"樗与栎在古代文学中常被称为不材之木，借喻无用之人；此处含有对汉廷无能者的讥刺。"},{"原词":"漢家制度","解":"指诗中所讥叹的汉廷制度，结合昭君出塞的题材，通常联系和亲制度理解。"}],"情绪":["哀婉","悲愤"],"情绪组":"哀婉","诗笺":"冷金笺","诗笺依据":"推断"},"huaigu-08":{"题":"馬嵬懷古其八","串讲":"借马嵬杨贵妃之事，写温柔一朝消散，遗迹与衣衾余香却仍留存，以人亡物存寄托感慨。","典故":[{"原词":"脂痕","解":"胭脂留下的痕迹，与汗光共同写女子留下的痕迹；原诗未说明它附着于汗巾。"},{"原词":"東洋","解":"东洋大海；「付东洋」在这里表示消散净尽、一去不返，并非实写入海。"},{"原词":"風流跡","解":"风流人物留下的痕迹，结合马嵬题材，指与杨贵妃有关的遗迹。"},{"原词":"衣衾","解":"衣服与被褥；诗中以其余香写人亡而痕迹尚存。"}],"情绪":["哀婉","旖旎"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"huaigu-09":{"题":"蒲東寺懷古其九","串讲":"借《西厢记》红娘暗助张生、莺莺相好的故事作诗谜。宝钗认为此首史鉴无考，主张另作，黛玉出言反对。","典故":[{"原词":"小紅","解":"指《西厢记》中崔莺莺的丫鬟红娘。"},{"原词":"撮成","解":"撮合、促成，指红娘从中帮助张生与莺莺相好。"},{"原词":"夫人","解":"指莺莺之母崔夫人。诗句借「拷红」情节写责问红娘，但「吊起」不能直接认作戏中的具体动作。"},{"原词":"私掖偷攜","解":"暗中扶持、偷偷帮助，写红娘为张生和莺莺的恋情牵线撮合。"}],"情绪":["诙谐","旖旎"],"情绪组":"热闹","诗笺":"洒金粉笺","诗笺依据":"推断"},"huaigu-10":{"题":"梅花觀懷古其十","串讲":"借《牡丹亭》题画、拾画等事构成诗谜，以团圆与别离相映。宝钗主张另作，黛玉认为戏曲故事众所熟知。","典故":[{"原词":"在柳邊","解":"《牡丹亭》杜丽娘题画诗句，暗合柳梦梅之姓。"},{"原词":"畫嬋娟","解":"画中的美人，指杜丽娘的自画像。"},{"原词":"春香","解":"《牡丹亭》中杜丽娘的丫鬟。"},{"原词":"西風","解":"秋风，喻离别时节与萧瑟之情。"}],"情绪":["哀婉","思念"],"情绪组":"哀婉","诗笺":"月白笺","诗笺依据":"推断"},"zhenzhen-shi":{"题":"外國女孩詩（昨夜朱樓夢）","串讲":"宝琴诵读真真国女孩所作五律。诗写梦境与海岛风物，以月无今古映衬情缘深浅，末以汉南春色寄托牵挂。","典故":[{"原词":"朱樓","解":"朱红色的楼阁，常见于富贵人家的居处；此处是梦中的楼阁，不能确定为女孩的故乡。"},{"原词":"水國","解":"水乡或四周临水的地域，与下文海岛景物相应；不能据此断言女孩客居异乡。"},{"原词":"嵐氣","解":"山林中的雾气。"},{"原词":"漢南","解":"本指汉水以南，诗中借用庾信《枯树赋》追忆汉南旧日景物的典意，寄托追怀；并非小说明示的女孩家乡。"}],"情绪":["思念","怅惘"],"情绪组":"夜","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"liuxu-baoqin":{"题":"西江月·柳絮","串讲":"第七十回众人填柳絮词，宝琴此作写柳絮飘零，境界开阔。以汉苑隋堤、江南江北铺开，末句仍归到离人恨重，在众作中另成一路。","典故":[{"原词":"漢苑","解":"汉代皇家园林，诗中作为柳絮点缀的宫苑意象。"},{"原词":"隋堤","解":"隋代运河堤岸，以沿堤植柳著称，后常用作咏柳的典故。"},{"原词":"三春","解":"春季三个月，泛指整个春天；「三春事业」在此写春日的繁华。"},{"原词":"明月梅花一夢","解":"用《龙城录》赵师雄梦遇梅花美人的故事；梦醒后月落参横，只余惆怅，借以写美好景象如梦消逝。"},{"原词":"香雪","解":"柳絮的美称，以雪喻其洁白；不宜据「香」字断言柳絮实际带有花香。"}],"情绪":["怅惘","哀婉","思念"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"gui-jialan":{"题":"姽嫿詞（賈蘭）","串讲":"第七十八回贾政命子孙作诗吊林四娘。贾兰以玉与铁对举，赞其美貌与刚烈，再以捐躯报恩、青州土香收束。","典故":[{"原词":"姽嫿","解":"形容女子娴静美好，书中用作林四娘的封号。"},{"原词":"恆王","解":"书中青州的藩王，林四娘为其姬妾。"},{"原词":"捐軀","解":"舍弃生命，指为报恩义而死。"}],"情绪":["坚贞","豪迈"],"情绪组":"哀婉","诗笺":"洒金红笺","诗笺依据":"推断"},"gui-jiahuan":{"题":"姽嫿詞（賈環）","串讲":"贾环以五律吊林四娘，写她掩泪出战、舍身报恩。颈联叹复仇难成，末联以忠义与风骨传世作结。","典故":[{"原词":"紅粉","解":"女子，此指林四娘。"},{"原词":"寇讎","解":"仇敌、敌人。"},{"原词":"風流","解":"此处指风骨标格，非男女情爱。"}],"情绪":["悲愤","怅惘"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"zilingzhou-ge":{"题":"紫菱洲歌","串讲":"第七十九回迎春被接出大观园待嫁，宝玉在紫菱洲徘徊而作。秋池花叶凋零、棋声断绝，末以手足之情点明惜别之痛。","典故":[{"原词":"芰荷","解":"菱与荷，此处写池塘中的花叶。"},{"原词":"棋枰","解":"棋盘。诗中以棋声断绝、燕泥污盘写迎春离去后住处的寂寞。"},{"原词":"手足","解":"比喻兄弟姐妹，此指宝玉与迎春的姐弟情分。"}],"情绪":["哀婉","怅惘","思念"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"panci-01":{"题":"又副冊判詞：晴雯","串讲":"太虚幻境又副册第一首，写晴雯。心高命薄，灵巧招怨，末句「空牵念」写尽牵挂无着。","典故":[{"原词":"霽月","解":"雨过天晴的明月，喻清朗气象，暗取晴雯名中「晴」意"},{"原词":"彩雲","解":"彩色的云，易散难留，暗取晴雯名中「雯」意"},{"原词":"風流","解":"此处指有才华、有风韵，非轻薄之意"},{"原词":"壽夭","解":"寿数与夭折，夭读 yāo，指短命"}],"情绪":["哀婉","自伤","怅惘"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"panci-02":{"题":"又副冊判詞：襲人","串讲":"又副册第二首，写袭人。温柔和顺、似桂如兰皆成空，末二句说她与公子无缘，惋惜之意全在言外。","典故":[{"原词":"枉自","解":"白白地，徒然"},{"原词":"似桂如蘭","解":"像桂花兰花般芬芳，喻品性美好"},{"原词":"優伶","解":"旧时对唱戏艺人的称呼"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"panci-03":{"题":"副冊判詞：香菱","串讲":"香菱判词以菱、荷花暗合今名与原名「英莲」；两土一木合成「桂」，暗指夏金桂，末句预示香菱之死。","典故":[{"原词":"根並荷花","解":"以菱与荷花相伴生长，暗合「香菱」之名；荷花又称莲，联系她的原名「英莲」。"},{"原词":"遭際","解":"遭遇、经历，指一生的境遇。"},{"原词":"兩地生孤木","解":"拆字隐语：两「土」加一「木」合成「桂」，暗指夏金桂。"},{"原词":"香魂返故鄉","解":"女子死亡的婉辞，此处预示香菱之死，并非实指返乡。"}],"情绪":["哀婉","自伤"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"panci-04":{"题":"正冊判詞：寶釵黛玉（合一首）","串讲":"宝钗、黛玉合写的判词，分别以贤德、诗才相称；末两句暗藏二人姓名，以玉带悬挂、金簪埋没预示悲剧。","典故":[{"原词":"停機德","解":"用《后汉书·列女传》中乐羊子妻的故事。她以断织比喻中断学业，劝丈夫坚持求学；此处借指宝钗的贤德。"},{"原词":"詠絮才","解":"用《世说新语·言语》中谢道韫以柳絮随风比拟飞雪的故事，借指黛玉出众的诗才。"},{"原词":"玉帶林中掛","解":"「玉带」谐「玉黛」，倒读联系「黛玉」，与「林」字合起来暗藏林黛玉之名。"},{"原词":"金簪雪裏埋","解":"金簪联系「宝钗」，「雪」与「薛」谐音，暗藏薛宝钗之名；埋没的意象预示其悲剧命运。"}],"情绪":["哀婉","怅惘","清冷"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"},"panci-05":{"题":"正冊判詞：元春","串讲":"元春判词以榴花映宫写荣华，以三春不及初春暗比四姐妹；末句设「虎兔相逢」的隐语，预示元春之死。","典故":[{"原词":"榴花","解":"石榴花，此处以鲜艳的花映照宫闱，写元春一时的显贵。"},{"原词":"宮闈","解":"闱读 wéi，宫廷内院，此处指元春所处的深宫。"},{"原词":"三春爭及初春景","解":"「争」作「怎」解；「三春」通常指迎春、探春、惜春，「初春」暗指元春，意谓三姐妹不及元春显贵。"},{"原词":"虎兔相逢","解":"预示元春命运转折的隐语，具体所指存在争议，不据此断定确切年份或事件。"},{"原词":"大夢歸","解":"以人生如梦、魂归而去的表达，婉指元春死亡。"}],"情绪":["哀婉","怅惘"],"情绪组":"夜","诗笺":"冷金笺","诗笺依据":"推断"},"panci-06":{"题":"正冊判詞：探春","串讲":"正册之一，宝玉太虚幻境所见，写探春。精明有志偏生末世，江边泪送、东风梦遥，抱负终成远别之痛。","典故":[{"原词":"末世","解":"衰败的时代，此处联系贾府走向衰落的处境。"},{"原词":"清明","解":"节气名，此处点出含泪送别的时节，并非指清明有固定的送别习俗。"},{"原词":"東風","解":"春风，与清明时节相应。"},{"原词":"一夢遙","解":"写相隔遥远、思念难达，只能寄托于梦中的怅惘。"}],"情绪":["哀婉","怅惘","自伤"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"panci-07":{"题":"正冊判詞：湘雲","串讲":"正册之一，写史湘云。襁褓中便失父母，富贵出身换不来亲缘；末句「湘江」「楚雲」暗嵌其名，水逝云飞，见身世飘零。","典故":[{"原词":"襁褓","解":"包裹婴儿的布被，借指极幼小的年纪。"},{"原词":"父母違","解":"与父母分离，此指幼年即失父母。"},{"原词":"斜暉","解":"傍晚西斜的阳光，常喻迟暮衰晚。"},{"原词":"湘江水逝","解":"湘江水流去不返，暗嵌「湘」字，喻好景难留。"}],"情绪":["哀婉","怅惘","思念"],"情绪组":"哀婉","诗笺":"月白笺","诗笺依据":"推断"},"panci-08":{"题":"正冊判詞：妙玉","串讲":"妙玉判词以求洁、言空写她的追求与未断的尘念，再以金玉陷入污泥的反差，预示其悲剧命运。","典故":[{"原词":"雲空","解":"此处「云」意为「说」，「云空」即说一切皆空，联系佛家的空观，并非一个固定术语。"},{"原词":"金玉質","解":"金玉般美好的资质，赞其珍贵美好，不专指出身。"},{"原词":"淖泥","解":"烂泥、污泥，比喻污浊的处境，预示妙玉命运的沦落；判词未说明具体经过。"}],"情绪":["清冷","孤高","哀婉"],"情绪组":"幽静","诗笺":"冷金笺","诗笺依据":"推断"},"panci-09":{"题":"正冊判詞：迎春","串讲":"正册写迎春。以「中山狼」喻凶恶负心之人，「得志便猖狂」写其嘴脸；后二句转写迎春柔弱，一载便赴黄粱，柔与暴相撞最惨。","典故":[{"原词":"子係","解":"「子」「係」二字相合可成「孫」字，为拆字隐语。"},{"原词":"中山狼","解":"寓言中忘恩负义的狼，喻凶恶负心之人。"},{"原词":"黃粱","解":"黄粱一梦的省称，喻好景短促；此指一命归阴。"},{"原词":"花柳質","解":"如花柳般柔弱的体质，喻娇弱易折。"}],"情绪":["哀婉","悲愤"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"panci-10":{"题":"正冊判詞：惜春","串讲":"正册写惜春。看破春光易逝，换下罗绮、披上缁衣，只余青灯古佛相伴。「繡戶侯門」与「青燈古佛」一贵一寂，繁华终成一空。","典故":[{"原词":"三春","解":"本指春季的三个月，泛指春光；此处又常被解为暗指元春、迎春、探春三位姐姐，兼含好景不长之意。"},{"原词":"緇衣","解":"黑色的僧衣，此处代指出家为尼。"},{"原词":"青燈古佛","解":"青灯与古佛，指寺院清寂的修行生活。"},{"原词":"繡戶侯門","解":"华美的门户、显贵的家门，指富贵的出身。"}],"情绪":["清冷","禅寂","哀婉"],"情绪组":"夜","诗笺":"素白竹纸","诗笺依据":"推断"},"panci-11":{"题":"正冊判詞：王熙鳳","串讲":"正册判词写王熙凤，以「凡鸟」拆字藏名，先赞才干，再转向悲局。「一从二令三人木」说解不一，不宜据此断定具体结局。","典故":[{"原词":"凡鳥","解":"将繁体「鳳」字拆作「凡」「鳥」，暗指王熙凤。"},{"原词":"一從二令三人木","解":"含有拆字隐语，历来说解不一；「人木」常被合解为「休」，但全句所指不能据此定论。"},{"原词":"金陵","解":"古地名，今南京；此处与凤姐的悲凉归宿相联系，具体情节不宜坐实。"},{"原词":"末世","解":"衰败的时代，此处也映照贾府走向衰败的处境。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"洒金红笺","诗笺依据":"推断"},"panci-12":{"题":"正冊判詞：巧姐","串讲":"正册判词，属巧姐。势败家亡，富贵亲戚皆成虚话；唯当日一点周济之善，换得日后一线生机。","典故":[{"原词":"勢敗","解":"家势衰败，指贾府倾覆。"},{"原词":"村婦","解":"乡下妇人，书中即刘姥姥。"},{"原词":"恩人","解":"施恩搭救之人。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"panci-13":{"题":"正冊判詞：李紈","串讲":"正册判词写李纨。「李」「完」暗点姓名，「一盆兰」指贾兰。后两句含义有争议，「空」「枉」透露出人生终归徒劳的悲凉。","典故":[{"原词":"桃李春風結子完","解":"借桃李结实写生子；「李」点姓，「完」与「纨」谐音，暗指李纨。"},{"原词":"一盆蘭","解":"借「兰」字暗指李纨之子贾兰。"},{"原词":"如冰水好","解":"通常解为品行如冰水般清洁美好，但所在句的具体含义有争议。"},{"原词":"笑談","解":"供人谈说、取笑的话题；此处具体所指不宜断定。"}],"情绪":["哀婉","清冷","怅惘"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"panci-14":{"题":"正冊判詞：秦可卿","串讲":"正册判词写秦可卿。前两句连用五个「情」字，写情与淫的关联；后两句由个人转向家族，指出祸乱的开端在宁国府。","典故":[{"原词":"情天情海","解":"以天、海比喻情的广大深厚。"},{"原词":"幻情身","解":"幻化而成的情之化身，是诗中的象征性说法。"},{"原词":"不肖","解":"不成器、不贤，此处指不肖子弟。"},{"原词":"造釁開端","解":"酿成祸乱的开端。"}],"情绪":["哀婉","怅惘","悲愤"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"qu-00":{"题":"紅樓夢曲：紅樓夢引子","串讲":"第五回由警幻命舞女唱给宝玉听，是《红楼梦》曲组的引子。以「谁为情种」发问，以「悲金悼玉」点明悲悼之意。","典故":[{"原词":"鴻蒙","解":"古人设想天地未开时的混沌状态。"},{"原词":"情種","解":"痴情之人。"},{"原词":"悲金悼玉","解":"悲悼金玉般的人物，指书中诸钗。"},{"原词":"愚衷","解":"自谦之词，谓自己的一片心意。"}],"情绪":["怅惘","哀婉"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"qu-01":{"题":"紅樓夢曲：終身誤","串讲":"此曲出太虚幻境，写姻缘错配。金玉良缘与木石前盟相对，纵得举案齐眉，到底意难平。","典故":[{"原词":"金玉良緣","解":"此指薛宝钗的金锁与贾宝玉的通灵宝玉相配所象征的姻缘。"},{"原词":"木石前盟","解":"此指宝玉、黛玉的前缘，联系绛珠仙草受神瑛侍者灌溉、后来愿以一生眼泪报恩的故事；书中未写二人正式订立盟约。"},{"原词":"齊眉舉案","解":"举案齐眉，东汉梁鸿妻孟光敬夫之典，喻夫妻相敬。"},{"原词":"山中高士","解":"山中高洁的隐士，此处用来比拟薛宝钗；「雪」谐音「薛」，暗点其姓。"}],"情绪":["哀婉","怅惘","思念"],"情绪组":"哀婉","诗笺":"冷金笺","诗笺依据":"推断"},"qu-02":{"题":"紅樓夢曲：枉凝眉","串讲":"此曲写宝玉与黛玉有缘相遇而心愿难成。水中月、镜中花比喻难以实现的美好，四季流泪写出无尽悲愁。","典故":[{"原词":"閬苑仙葩","解":"阆苑为传说中神仙居处，仙葩即仙花。"},{"原词":"美玉無瑕","解":"无斑点的美玉，喻人品完美无缺。"},{"原词":"水中月","解":"水中的月亮，喻虚幻不实。"},{"原词":"鏡中花","解":"镜中的花影，喻空幻难求。"}],"情绪":["哀婉","旖旎","怅惘"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"qu-03":{"题":"紅樓夢曲：恨無常","串讲":"此曲出太虚幻境，写荣华骤断。万事全抛，家乡路远，只余梦中告爹娘：儿已入黄泉，须早退步抽身。","典故":[{"原词":"無常","解":"佛家语，指生灭变化，此指死亡。"},{"原词":"黃泉","解":"地下的泉水，指阴间。"},{"原词":"天倫","解":"指父子兄弟等天然的亲属关系。"},{"原词":"芳魂","解":"对女子魂魄的美称。"}],"情绪":["哀婉","思念","怅惘"],"情绪组":"哀婉","诗笺":"洒金红笺","诗笺依据":"推断"},"qu-04":{"题":"紅樓夢曲：分骨肉","串讲":"此曲出太虚幻境，写远嫁离亲。一帆风雨，抛下骨肉家园。劝爹娘休要挂念，离合有定，各自保平安。","典故":[{"原词":"骨肉","解":"指父母兄弟等至亲。"},{"原词":"殘年","解":"余年，指晚年。"},{"原词":"窮通","解":"困厄与显达，指境遇顺逆。"},{"原词":"三千","解":"指路途遥远，非确数。"}],"情绪":["哀婉","坚贞","怅惘"],"情绪组":"哀婉","诗笺":"月白笺","诗笺依据":"推断"},"qu-05":{"题":"紅樓夢曲：樂中悲","串讲":"此曲出太虚幻境，写襁褓失亲、性情豪阔之人。虽配得才貌仙郎，终归云散水涸，好景难长。","典故":[{"原词":"綺羅叢","解":"穿绮罗的富贵人群，指富贵之家。"},{"原词":"霽月光風","解":"雨过天晴的明月清风，喻胸怀开朗。"},{"原词":"雲散高唐","解":"借宋玉《高唐赋》中楚王梦遇巫山神女、神女自称朝云暮雨的故事，以云散比喻夫妻情缘消散。"},{"原词":"水涸湘江","解":"字面指湘江水干涸，与「云散高唐」共同写美好姻缘不能长久；「湘江」还暗含史湘云的名字。"}],"情绪":["豪迈","哀婉","怅惘"],"情绪组":"哀婉","诗笺":"洒金粉笺","诗笺依据":"推断"},"qu-06":{"题":"紅樓夢曲：世難容","串讲":"《红楼梦曲》一支，咏孤高自许、不合流俗的女子。太高招妒，过洁被嫌，青灯古殿，辜负春色，写尽清高者的违心之恨。","典故":[{"原词":"青燈古殿","解":"佛前青灯与古老殿宇，指清苦的出家修行生活。"},{"原词":"風塵骯髒","解":"风尘指尘世。「肮脏」有不同解释：可读āng zāng，指污浊、受辱，与下文白玉陷泥相应；也有注家读kǎng zǎng，解释为坎坷不遇。"},{"原词":"無瑕白玉","解":"完美无瑕的白玉，喻人品纯洁高贵。"},{"原词":"紅粉朱樓","解":"指女子的青春年华与富贵闺阁生活。"}],"情绪":["孤高","哀婉","清冷"],"情绪组":"哀婉","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"qu-07":{"题":"紅樓夢曲：喜冤家","串讲":"《红楼梦曲》一支，写公府千金错嫁中山狼，受尽作践，一载而亡。以无情兽比人，恨意直露，最为沉痛。","典故":[{"原词":"中山狼","解":"典出《中山狼传》，喻忘恩负义、反噬恩人之徒。"},{"原词":"同蒲柳","解":"蒲柳早衰易凋，喻视人如低贱易衰之物。"},{"原词":"公府千金","解":"公侯之家的千金小姐。"},{"原词":"芳魂艷魄","解":"指美貌女子的魂魄。"}],"情绪":["悲愤","哀婉","怅惘"],"情绪组":"哀婉","诗笺":"素白竹纸","诗笺依据":"推断"},"qu-08":{"题":"紅樓夢曲：虛花悟","串讲":"《红楼梦曲》一支，咏看破繁华、心向清净的女子。勘破三春，以白杨衰草写坟茔冷落，末寄意西方宝树，近禅而冷。","典故":[{"原词":"夭桃","解":"语本《诗经》「桃之夭夭」，喻盛美艳丽的青春。"},{"原词":"白楊","解":"古诗中白杨多植墓旁，悲风萧瑟，此指坟茔之地。"},{"原词":"婆娑","解":"曲中西方宝树的名称。宝树与长生果的想象，寄托了摆脱生死苦难的愿望，不宜据此断言佛经中确有这种树及果实。"},{"原词":"清淡天和","解":"清净淡泊、天然冲和之境。"}],"情绪":["禅寂","哀婉","清冷"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"},"qu-09":{"题":"紅樓夢曲：聰明累","串讲":"《红楼梦曲》一支，咏精明能干、执掌家务的女子。机关算尽反算自身，半世心悬终成一梦，大厦倾、灯将尽，盛衰之警最惊心。","典故":[{"原词":"機關算盡","解":"机关指心机权术；算尽谓用尽心计。"},{"原词":"卿卿","解":"旧时对人的亲昵称呼，此指所咏之人。"},{"原词":"性空靈","解":"性指性灵、魂灵。此处可理解为死后魂灵即使有知觉，也徒然无益，无法挽回生前的算计与败局。"},{"原词":"大廈傾","解":"高楼倾倒，喻家业崩败。"}],"情绪":["哀婉","怅惘","自伤"],"情绪组":"哀婉","诗笺":"洒金红笺","诗笺依据":"推断"},"qu-10":{"题":"紅樓夢曲：留餘慶","串讲":"《红楼梦曲》一支，女儿蒙难自述：因娘亲积阴功，忽遇恩人得救，并痛骂爱钱忘亲的狠舅奸兄。借因果劝人济困扶穷，带暖意。","典故":[{"原词":"留餘慶","解":"语出《易经》「积善之家，必有余庆」，谓遗留福泽。"},{"原词":"陰功","解":"暗中积下的功德、阴德。"},{"原词":"乘除加減","解":"本为算术，此喻命运因果的消长折算。"},{"原词":"蒼穹","解":"苍天、上天。"}],"情绪":["思念","悲愤","哀婉"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"qu-11":{"题":"紅樓夢曲：晚韶華","串讲":"太虚幻境《红楼梦》曲第11支，咏李纨晚景。因子得贵、戴珠冠披凤袄，却黄泉路近，镜里恩情、梦里功名一场空。","典故":[{"原词":"簪纓","解":"古代贵官的冠饰，代指做官显贵。"},{"原词":"陰騭","解":"阴德，暗中积下的善行。"},{"原词":"無常","解":"佛家语，指生死变化、死亡。"},{"原词":"黃泉","解":"地下的泉水，指阴间、死后。"}],"情绪":["哀婉","怅惘","自伤"],"情绪组":"哀婉","诗笺":"月白笺","诗笺依据":"推断"},"qu-12":{"题":"紅樓夢曲：好事終","串讲":"太虚幻境《红楼梦》曲中一支，咏秦可卿。以风情月貌为败家根本，归罪宁国府，末句「宿孽总因情」点出祸根。","典故":[{"原词":"箕裘","解":"语出《礼记》，比喻祖先留下的事业。"},{"原词":"擅風情","解":"擅长男女间的风情魅力。"},{"原词":"秉月貌","解":"具有如月的美貌。"},{"原词":"畫梁","解":"彩绘的屋梁，指华美的房屋。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"qu-13":{"题":"紅樓夢曲：飛鳥各投林（收尾）","串讲":"《红楼梦》曲的收尾，总束诸人命运。恩怨情债一一还报，末以鸟投林、白茫茫大地作结，繁华散尽归于空无。","典故":[{"原词":"冤冤相報","解":"冤仇相互报复，循环不休。"},{"原词":"前定","解":"预先注定，指命运早有安排。"},{"原词":"白茫茫","解":"形容一片空阔洁白；此处表现繁华消散、一无所有的景象。"}],"情绪":["哀婉","怅惘","禅寂"],"情绪组":"哀婉","诗笺":"雪浪笺","诗笺依据":"推断"},"jinghuan-qu":{"题":"警幻仙曲（春夢隨雲散）","串讲":"宝玉梦入太虚幻境，闻警幻仙姑作此歌。云散花流，寄语儿女莫自寻愁，为一场春梦定下淡淡调子。","典故":[{"原词":"春夢","解":"春日之梦，喻世事虚幻易逝。"},{"原词":"飛花","解":"飘落的花，喻飘零无定。"},{"原词":"閒愁","解":"无端而生、多余的愁绪。"}],"情绪":["禅寂","清冷"],"情绪组":"幽静","诗笺":"淡青薛涛笺","诗笺依据":"推断"},"jinghuan-fu":{"题":"警幻賦（方離柳塢）","串讲":"宝玉梦入太虚幻境，见警幻仙姑蹁跹而出，此赋即写其仙姿容貌。柳坞花房、环佩麝兰，铺陈出一位缥缈仙子。","典故":[{"原词":"西子","解":"西施，春秋时越国的美女。"},{"原词":"王嬙","解":"王昭君，名嫱，汉代美女。"},{"原词":"瑤池","解":"神话中西王母所居之地，指仙境。"},{"原词":"紫府","解":"道教所称仙人所居之处。"}],"情绪":["旖旎","清冷"],"情绪组":"幽静","诗笺":"洒金粉笺","诗笺依据":"推断"},"lian-taixu-1":{"题":"太虛幻境聯（假作真時真亦假）","串讲":"太虚幻境牌坊之联，以真假、有无相互翻转，提示表象与真实可能被颠倒看待，呼应全书真事隐去、假语存留的叙述方式。","典故":[{"原词":"假作真","解":"把虚假当作真实。"},{"原词":"真亦假","解":"真的也被当作假的，与上半句形成真假颠倒的关系。"},{"原词":"有還無","解":"有的也被当作没有，与「无为有」相对应，写有无被颠倒看待。"}],"情绪":["禅寂","清冷"],"情绪组":"幽静","诗笺":"冷金笺","诗笺依据":"推断"},"lian-taixu-2":{"题":"孽海情天聯（厚地高天）","串讲":"太虚幻境「孽海情天」宫门之联。天地高厚而情不尽，痴男怨女而债难偿，仙家口气里满是对世间情痴的怜叹。","典故":[{"原词":"癡男怨女","解":"沉迷情爱的男子与幽怨的女子。"},{"原词":"風月債","解":"男女情爱所欠下的情债。"},{"原词":"情不盡","解":"情意绵长，古往今来没有尽头。"}],"情绪":["哀婉","怅惘"],"情绪组":"哀婉","诗笺":"桃红笺","诗笺依据":"推断"},"lian-bomingsi":{"题":"薄命司聯（春恨秋悲）","串讲":"太虚幻境薄命司之联。恨与悲皆由自惹，花月之容又为谁而妍？一问一叹，替司中薄命人先写下一笔凄凉。","典故":[{"原词":"春恨秋悲","解":"春日的怅恨、秋天的悲愁，泛指四时感伤。"},{"原词":"花容月貌","解":"形容女子容貌如花似月般美好。"},{"原词":"為誰妍","解":"为谁而美；妍，美好、娇艳。"}],"情绪":["自伤","哀婉","怅惘"],"情绪组":"哀婉","诗笺":"秋香笺","诗笺依据":"推断"},"lian-qiongfang":{"题":"警幻仙閨聯（幽微靈秀地）","串讲":"宝玉在太虚幻境后宫房内见到此联。上句写幽深微妙、灵秀清美的境地，下句转出无可奈何的怅惘，清美之中含着悲凉。","典故":[{"原词":"幽微靈秀","解":"幽深精微，灵秀之气汇聚。"},{"原词":"無可奈何","解":"没有办法、无可奈何。"},{"原词":"靈秀","解":"灵秀之气，指天地间的灵慧。"}],"情绪":["清冷","怅惘"],"情绪组":"幽静","诗笺":"月白笺","诗笺依据":"推断"}}')},on={题:"卷首小记",段:["园中一日，未必只从一处院门记起。有时是竹影下遇见一个人，有时是窗前读到一首诗；待回头翻看，原本散在各处的声息，才渐渐连成自己的游踪。此册将人物、地点、物件、画册、诗词与回目分置六志，又把已经记下的相逢汇在一页。数字记的是本册已收的条目；至于那次为何驻足，仍须留给自己的笔墨。","大观园先为省亲而建，后来成为宝玉与姊妹们日常起居、结社吟咏的所在。第十七、十八回的题额与赐名，让山水有了名目；第二十三回迁入之后，院落才有各人的笑语与心事。读游记时，可将一处景与它前后发生的事相照：同一条水岸，春日可以共读，秋夜又有联诗；景色相似，人在其中的处境却已不同。","笺边所添的白话，是随原著前八十回所作的阅读补记，不能替代原文。画面与园中陈设也有复原和拟设的部分，须与出处、推断标记一并看。若一句话触动了自己，不妨留在游踪旁边；隔日再来，旧笔便能提醒人记起，当时看见的究竟是一处景，还是景中人的一段生活。"]},hn={题:"人物志引",段:["一人之名，往往牵出几重关系：是谁家的儿女，住在何处，又在谁身边当差。身份决定了许多人的去留，却不能尽说他们的性情。读人物志，可将日常言语与紧要关头的行事相照；同样一声劝告，有人出于体贴，有人为了规矩，也有人两者兼有。判词所示是预兆，眼前发生的事仍须按回目细读，才不至于只凭一句评语把一个人看尽。"]},gn={题:"地点志引",段:["院名是读园的起点，院中人的生活才使它有了意味。潇湘馆的竹、蘅芜苑的异草、怡红院的蕉棠，各有题额时的缘由；姊妹迁入以后，又添上读书、待客与作诗的声息。读一处地点，可先辨山水门庭，再看谁曾驻足、何事发生于此。原著未明言的尺寸与方位不能仅凭画面坐实；一处景的复原，应与回目依据和拟设说明合看。"]},yn={题:"物件志引",段:["床帐、镜屏、茶器与书函，既是起居所需，也能照见贾府的生活层次。物件的意义常在一次使用、赠送或遗失中显出来：谁拿来待客，谁替人收好，谁又为它受了委屈。读物件志，宜把器形与情节分开辨认；原文只说名称的地方，图上纹饰便仍属复原想象。再循所记回目读去，器物才从一件好看的陈设，回到人手中的日用之物。"]},cn={题:"画册志引",段:["一幅画只能择取片刻，故事却常在这一刻的前后转折。画册将园中情节拆作分镜，借人物的站位、目光与景物引人回看原文；画面的取舍属于编绘，不能据此断定书中未写的衣色、器形或路径。读时可将卷首提要、逐幅旁白与所引段落相照，尤其留心谁在场、谁听见、谁尚不知情。这样重看一卷，才会看见热闹背后的误会与牵挂。"]},rn={题:"诗词志引",段:["园中的诗不只写花月，也写作诗的人。省亲应制、海棠结社、菊花分题与秋夜联句，各有不同的场合和声口；同题相和，尤能照出姊妹们的才情差别。读一首作品，先看题目、作者与回目，再将字注和白话释意放回当时的情节。诗中有自况，也有游戏笔墨，不宜句句硬指后事；人物尚未说出口的心绪，却常已在一字一韵间露出来。"]},ln={题:"回目志引",段:["回目以两句撮取一回要事，读来整齐，所写的人情却并不沿一条直线展开。同回的两件事可能互相映照，也可能一明一暗；前回埋下的小事，数回后才见分量。此志所添撮要止于前八十回，只助认清人物、场合与转折。已有预示应按预示读，未发生的结局不替原文补成定论；循回目回看全回，方能辨出一段笑语如何渐成一场离散。"]},dn={home:on,person:hn,place:gn,prop:yn,album:cn,poem:rn,hui:ln},x=/[“”「」『』]/,sn=/第(?:8[1-9]|9\d|1\d\d)回/,j=n=>new Map(n.map(a=>[a.id,a])),xn=j(b.人物),bn=j(b.地点),jn=j(b.作品),qn=new Map(N.map(n=>[{ningmen:"fu-ningmen",xijiaomen:"fu-xijiaomen",chuihua:"fu-chuihua",chuantang:"fu-jiamu",jiamu:"fu-jiamu",rongxi:"fu-rongxi",erfang:"fu-erfang",donglang:"fu-donglang",fengjie:"fu-fengjie"}[n.id],n]).filter(([n])=>n)),fn=(n,a=110)=>{let i="";for(const u of String(n||"").match(/[^。！？]+[。！？]?/g)||[])if(i+=u,i.length>=a)break;return i};function Cn(n){const a=n.页.hui;a.条目=Object.fromEntries(Object.entries(a.条目).filter(([u])=>Number(u)<=80)),a.分组=a.分组.map(u=>({...u,ids:u.ids.filter(e=>Number(e)<=80)})).filter(u=>u.ids.length),a.总=80,Object.assign(n.页.album,{分组:l.分组,条目:l.条目,总:Object.keys(l.条目).length});const i=n.页.prop;delete i.条目.yh06,i.分组=i.分组.map(u=>({...u,ids:u.ids.filter(e=>e!=="yh06")})),i.总=Object.keys(i.条目).length,i.条目.yh05&&(i.条目.yh05.line="怡红院槅格可贮书；六函的数量、函套与所收诗稿，是游戏所作陈设。"),i.条目.yh08&&(i.条目.yh08.推断=!0),i.条目.yh11&&Object.assign(i.条目.yh11,{n:"联珠瓶",t:"聯珠瓶",line:"十锦槅顶上的一对联珠瓶，曾被宝玉拿来插新开的桂花，分别送给贾母与王夫人；游戏器形为推定。",hui:[37],quote:{文:"那槅子盡上頭的一對聯珠瓶還沒收來呢。",回:37}});for(const u of Object.values(n.页))for(const e of Object.values(u.条目))e.hui&&(e.hui=e.hui.filter(g=>g<=80)),e.quote?.回>80&&delete e.quote;return n}function pn(n){const a=xn.get(n);if(!a)return"";const i=k.人物[n]?.解析续;if(i)return[a.身份,i].filter(Boolean).join(`

`);const u=[a.身份,a.性格].filter(e=>e&&!x.test(e));for(const e of a.解析||[])if(!(x.test(e)||sn.test(e))&&(u.join("").length+e.length>290||(u.push(e),u.join("").length>=150)))break;if(u.join("").length<150)for(const e of a.大事记||[]){if(e.回>80||x.test(e.事))continue;const g=`第${e.回}回，${e.事}`;if(u.join("").length+g.length>300||(u.push(g),u.join("").length>=150))break}return v[n]&&u.push(v[n]),u.join(`

`)}function mn(n){if(z.地点[n])return z.地点[n];if(S[n])return S[n];const a=qn.get(n);return a?a.白话:bn.get(n)?.形制||""}function zn(n){const[a]=n.split(":"),i=l.条目[n];if(!i)return"";const u=fn(un.续论[a],115);return[`画面分镜：${i.画面}`,`本卷背景：${u}`].join(`

`)}function Sn(n){const a=jn.get(n);if(a?.白话?.length>100)return a.白话;const i=en.作品[n],u=tn.作品[n];if(!i)return"";const e=n==="liuxu-tan"?"探春写柳絮，既看它随风飞起，也想到离散后难再挽留。此词写于第七十回，须与同席诸人的词相照，方见春尽之际各人的心绪。":i.串讲2;return[u?.串讲,e].filter(Boolean).join(`

`)}const vn=(n,a)=>({person:pn,place:mn,prop:i=>an[i],album:zn,poem:Sn,hui:i=>m[i]&&`第${i}回。${m[i]}`})[n]?.(a)||"";function Dn(n,a){let i=null;const u=()=>{const o=a.querySelector(".jn-page"),t=a.querySelector(".jn-tab.is-on")?.dataset.k,y=dn[t];if(o&&y&&!o.querySelector(".normal-journal-intro")){const h=document.createElement("section");h.className="normal-journal-note normal-journal-intro";const c=document.createElement("h4");c.textContent=y.题,h.appendChild(c);for(const w of y.段){const p=document.createElement("p");p.textContent=w,h.appendChild(p)}t==="home"?o.querySelector(".jn-sum")?.after(h):o.prepend(h)}const d=a.querySelector(".jn-detail");if(!d||d.querySelector(".normal-journal-note")||!i)return;const q=vn(i.kind,i.id);if(!q)return;const s=d.querySelector(".jn-d-info");if(!s)return;const r=document.createElement("section");r.className="normal-journal-note";const f=document.createElement("h4");f.textContent="笺边补记",r.appendChild(f);for(const h of q.split(/\n\n+/).filter(Boolean)){const c=document.createElement("p");c.textContent=h,r.appendChild(c)}(s.querySelector(".jn-d-line")||s.querySelector(".jn-d-name"))?.after(r)};a.addEventListener("click",o=>{const t=o.target.closest(".jn-tile[data-kind][data-id]");t&&(i={kind:t.dataset.kind,id:t.dataset.id})},!0);const e=n.show.bind(n);return n.show=(o,t)=>{i=t?{kind:o,id:String(t)}:null;const y=e(o,t);return u(),y},new MutationObserver(u).observe(a,{childList:!0,subtree:!0}),u(),n}export{Dn as installNormalJournalProse,vn as normalJournalNoteOf,Cn as prepareNormalJournalSchema};
